@import "./components/ProviderConnections.css";
@import "./components/ProviderCatalogPicker.css";
/*
/*
 * Reasonix desktop — single-column, developer-dense, terminal-flavored chat UI.
 *
 * Multi-platform notes:
 *  - System font stack for text; bundled icon fonts only (no web-font fetches).
 *  - No backdrop-filter / blur (slow & inconsistent on Linux WebKitGTK).
 *  - Colors via CSS variables + prefers-color-scheme so the webview follows the OS.
 *  - --wails-draggable marks the title region as an OS drag handle (macOS inset
 *    title bar); interactive children opt out with --wails-draggable: no-drag.
 */

@font-face {
  font-family: "Reasonix Seti";
  src: url("./assets/file-icons/seti/seti.woff") format("woff");
  font-style: normal;
  font-weight: normal;
  font-display: block;
}

:root {
  color-scheme: dark;

  /* surfaces */
  --bg: #090a0c;
  --bg-soft: #111319;
  --bg-elev: #191b22;
  --bg-elev-2: #222631;
  --sidebar-bg: #0c0e12;
  --sidebar-hover: #181c24;
  --sidebar-active: rgba(217, 119, 87, 0.13);
  --chat-bg: var(--bg);
  --workspace-preview-bg: var(--bg);
  --workspace-files-bg: var(--bg-soft);
  --workspace-files-hover: var(--sidebar-hover);
  --workspace-selection-bg: var(--sidebar-active);
  --workspace-selection-fg: var(--accent);
  --workspace-selection-bar: var(--accent);
  --border: #343945;
  --border-soft: #252a34;

  /* text */
  --fg: #f4f5f7;
  --fg-dim: #c0c4cc;
  --fg-faint: #858b96;

  /* Shared semantic contract. Theme directions may override any of these,
     while partial directions such as Amber inherit a complete, usable set. */
  --stage: var(--bg);
  --surface: var(--bg-elev);
  --surface-2: var(--bg-elev-2);
  --surface-3: var(--bg-soft);
  --panel: var(--bg-elev);
  --border-2: color-mix(in srgb, var(--fg) 20%, transparent);
  --text: var(--fg);
  --text-2: var(--fg-dim);
  --text-3: var(--fg-faint);
  --shadow-color: #000;
  /* Operational overlays are opaque unless a background theme pack opts into
     the existing pane-opacity contract. */
  --overlay-surface-bg: var(--bg-elev);
  --global-font-scale: 1;
  --font-scale: var(--global-font-scale);
  --text-2xs: calc(10px * var(--font-scale));
  --text-xs: calc(11px * var(--font-scale));
  --text-sm: calc(12px * var(--font-scale));
  --text-md: calc(13px * var(--font-scale));
  --text-base: calc(14px * var(--font-scale));
  --text-lg: calc(15px * var(--font-scale));
  --text-xl: calc(18px * var(--font-scale));
  --font-caption: var(--text-xs);
  --font-code: var(--text-sm);
  --font-content: var(--text-base);
  --font-control: var(--text-md);
  --font-control-small: var(--text-sm);
  --font-status: var(--font-control-small);
  /* Task 827 ②③: project-tree grid tokens — the single source of truth for
     the row icon column (same width on every row, acceptance ③'s hard
     constraint) and the group/project title sizes ("one step larger", token-
     driven so themes and font-scale compose). Pure sizing, no color: dark
     themes need no special case. The per-skin overrides below keep "project
     font" equal to whatever the skin already renders project rows at, so the
     group title is always exactly one step larger than the project title. */
  --project-tree-icon-col: 16px;
  --project-tree-project-font: 13.5px;
  --project-tree-group-font: calc(var(--project-tree-project-font) + 1px);
  --statusbar-dock-height: max(30px, calc(28px * var(--font-scale)));
  --font-ui: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "PingFang SC", "Microsoft YaHei UI", "Microsoft YaHei",
    "Noto Sans SC", "Helvetica Neue", Arial, sans-serif;
  --font-content-family: var(--font-ui);
  --font-mono: ui-monospace, "SF Mono", SFMono-Regular, "Cascadia Code",
    Consolas, "Liberation Mono", Menlo, monospace;
  --font-symbol: "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol",
    "Noto Color Emoji", sans-serif;
  --font-smoothing: antialiased;
  --text-rendering: optimizeLegibility;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-strong: 600;
  --scrollbar-size: 10px;
  --scrollbar-track: transparent;
  --scrollbar-thumb: color-mix(in srgb, var(--fg-faint) 42%, transparent);
  --scrollbar-thumb-hover: color-mix(in srgb, var(--fg-dim) 56%, transparent);
  --scrollbar-thumb-active: color-mix(in srgb, var(--accent) 52%, var(--fg-faint));
  --scrollbar-corner: transparent;

  /* brand + semantic */
  --accent: #d97757;
  --accent-fg: #1a0f0a;
  --accent-text: var(--accent-fg);
  --accent-soft: rgba(217, 119, 87, 0.14);
  --accent-strong: #e58a6b;
  --grad: linear-gradient(120deg, var(--accent), var(--accent-strong));
  /* Chart series colours for the usage-stats model charts (donut + stacked
     trend). A fixed two-set palette taken from GitHub Primer's data-viz
     tokens (data-blue/green/orange/purple/pink/gray emphasis, light + dark
     variants; dark orange uses the palette's brighter .5 step #c46212
     instead of the official #984b10 emphasis, which reads brownish on this
     dark background); theme styles and theme packs deliberately do not
     override these so charts keep the same readable sets in both
     directions. */
  --chart-1: #0576ff;
  --chart-2: #2f6f37;
  --chart-3: #c46212;
  --chart-4: #975bf1;
  --chart-5: #d34591;
  --chart-other: #576270;
  --chat-user-bg: color-mix(in srgb, var(--accent) 16%, var(--bg-elev-2));
  --chat-user-border: color-mix(in srgb, var(--accent) 28%, var(--border-soft));
  --chat-user-fg: var(--fg);
  --chat-user-shadow: 0 8px 22px color-mix(in srgb, var(--accent) 10%, transparent);
  --ok: #74b87a;
  --warn: #d9a441;
  --err: #e0696a;
  --danger: #e5484d;
  --danger-fg: #fff;
  /* 任务 910：.rt-notice 第四档（中性提示蓝，更新类通知等）——demo 提案新增档。 */
  --info: #5b8def;
  --shell-accent: #22c55e;
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.22);
  --shadow-2: 0 14px 40px rgba(0, 0, 0, 0.28);

  /* z-index scale */
  --z-transcript-scene-image: 0;
  --z-transcript-scene-overlay: 1;
  --z-transcript-content: 2;
  --z-theme-bg: 0;
  --z-app-content: 1;
  --z-local-raised: 2;
  --z-local-handle: 4;
  --z-local-handle-active: 5;
  --z-layout-resizer: 12;
  --z-layout-resizer-active: 13;
  --z-inline-sticky: 20;
  --z-local-backdrop: 30;
  --z-local-popover: 31;
  --z-workspace-float: 40;
  --z-app-chrome: 70;
  --z-drawer-backdrop: 90;
  --z-menu-backdrop: 95;
  --z-menu: 96;
  --z-dock: 100;
  --z-floating-menu: 110;
  --z-topicbar-menu: 210;
  --z-startup-overlay: 300;
  --z-modal: 1200;
  --z-overlay-backdrop: 1300;
  --z-popover: 1301;
  --z-popover-elevated: 1303;
  --z-toast: 1302;
  --z-tooltip: 1302;
  --z-onboarding: 9999;
  --z-performance-report-prompt: 99998;
  --z-crash-overlay: 99999;

  /* component recipes */
  --list-row-height: 38px;
  --list-row-radius: 7px;
  --list-row-gap: 10px;
  --list-row-px: 10px;
  --list-row-title: var(--fg-dim);
  --list-row-meta: var(--fg-faint);
  --list-row-hover-bg: var(--sidebar-hover);
  --list-row-current-bg: color-mix(in srgb, var(--accent) 7%, var(--sidebar-hover));
  --list-row-current-title: var(--fg);
  --list-row-current-meta: var(--accent);
  --tree-row-height: 30px;
  --tree-row-radius: 7px;
  --tree-row-hover-bg: var(--workspace-files-hover);
  --tree-row-current-bg: color-mix(in srgb, var(--workspace-selection-bg) 42%, var(--workspace-files-bg));
  --tree-row-current-fg: var(--fg);
  --tree-row-current-icon: var(--fg-dim);
  --tree-row-marker: var(--workspace-selection-bar);
  --control-primary-bg: var(--accent);
  --control-primary-fg: var(--accent-fg);
  --control-disabled-bg: var(--bg-elev-2);
  --control-disabled-fg: var(--fg-faint);
  --focus-ring: 0 0 0 3px var(--accent-soft);
  --button-height: 34px;
  --button-small-height: 30px;
  --button-icon-size: 30px;
  --button-radius: 8px;
  --button-px: 12px;
  --button-bg: color-mix(in srgb, var(--bg-elev-2) 62%, var(--bg-soft));
  --button-bg-hover: color-mix(in srgb, var(--bg-elev-2) 82%, var(--bg-soft));
  --button-border: var(--border);
  --button-border-hover: color-mix(in srgb, var(--fg-faint) 48%, var(--border));
  --button-fg: var(--fg);
  --button-muted-fg: var(--fg-dim);
  --button-danger-bg: color-mix(in srgb, var(--err) 10%, var(--bg-elev));
  --button-danger-border: color-mix(in srgb, var(--err) 30%, var(--border));
  --button-danger-fg: var(--err);
  --pill-bg: color-mix(in srgb, var(--bg-elev-2) 62%, transparent);
  --pill-border: var(--border);
  --pill-fg: var(--fg-dim);
  --pill-hover-bg: var(--bg-elev-2);
  --pill-plan-bg: var(--accent-soft);
  --pill-plan-border: color-mix(in srgb, var(--accent) 24%, var(--border));
  --pill-yolo-bg: var(--danger);
  --pill-yolo-bg-hover: color-mix(in srgb, var(--danger) 90%, var(--fg));
  --pill-yolo-border: var(--danger);
  --pill-yolo-border-hover: color-mix(in srgb, var(--danger) 90%, var(--fg));
  --pill-yolo-fg: var(--danger-fg);
  /* 任务 614 权限四档语义色调（此处为暗背景默认值；亮背景在下方两块覆写）：
     approval/ask=蓝·确认、yolo=红·警示、autopilot=橙·自治（595/614）、
     plan=紫·规划；自动(auto)=绿为既有安全档补充，不在四档映射内；goal=青
     为协作档补充。五组色相互异，徽章/标签/tint 各消费面对位取用。 */
  --mode-auto-bg: #2f6de8;
  --mode-auto-border: #3978f0;
  --mode-auto-fg: #fff;
  /* 任务 614 权限四档语义色调：plan=紫（原借 accent 蓝，与 approval 蓝撞色）。
     goal=青为协作档补充（原与 plan 共用徽章类，plan 转紫后拆分）。 */
  --mode-plan-bg: rgba(139, 92, 246, 0.16);
  --mode-plan-border: color-mix(in srgb, #a78bfa 36%, var(--border));
  --mode-plan-fg: #a78bfa;
  --mode-goal-bg: rgba(20, 184, 166, 0.16);
  --mode-goal-border: color-mix(in srgb, #2dd4bf 36%, var(--border));
  --mode-goal-fg: #2dd4bf;
  --mode-yolo-bg: #f04b52;
  --mode-yolo-border: #ff6268;
  --mode-yolo-fg: #fff;
  /* 任务 595/614：autopilot 专属橙色系——与 yolo 红（#f04b52）明确区分。
     614 修色三层排查：①token 定义（主因）——原 #cf6a1d 亮度 L*≈49 本就在
     棕色域，再叠滑块内 18% 白色高光后视觉呈土黄，提饱和提亮至 #f97316；
     ②透明度叠加——滑块填充不透明，内高光仅 1px 顶缘，非主因，不改；
     ③容器背景——填充不透明，与容器（--surface-2）无混色，非因素。
     前景改深色：白字在真橙上对比不足 3:1，深字（#2b1503）≥4.8:1。 */
  --mode-autopilot-bg: #f97316;
  --mode-autopilot-border: #fb8f3d;
  --mode-autopilot-fg: #2b1503;

  /* diff */
  --add-bg: rgba(116, 184, 122, 0.12);
  --add-fg: #82c98a;
  --del-bg: rgba(224, 105, 106, 0.12);
  --del-fg: #e58587;

  /* Opaque readability island for code and diffs. Theme packs replace these
     with a flattened background and WCAG-adjusted syntax palette. */
  --code-bg: #111319;
  --code-border: var(--border-soft);
  --code-fg: var(--fg);

  /* syntax (One Dark-tuned) */
  --hl-keyword: #c678dd;
  --hl-string: #98c379;
  --hl-number: #d19a66;
  --hl-comment: #6a6a72;
  --hl-func: #61afef;
  --hl-type: #e5c07b;
  --hl-builtin: #56b6c2;
  --hl-meta: #7f848e;

  /* motion — shared timing + easing tokens. Durations mirror the values
   * already used across the app (0.12 / 0.18 / 0.34 / 0.42s); easings reuse the
   * existing curves. The global prefers-reduced-motion block at EOF collapses
   * every animation to ~0ms and removes transitions, so these tokens are safe
   * to reuse freely without per-rule reduce overrides. */
  --dur-fast: 120ms; /* color/border hovers, tooltips */
  --dur-base: 180ms; /* popovers, menus, small enters */
  --dur-slow: 340ms; /* drawers, modals, panel slides */
  --dur-slower: 420ms; /* large overlay fades */
  --ease-out: cubic-bezier(0.2, 0.72, 0.2, 1); /* fast-out / decelerate */
  --ease-decelerate: cubic-bezier(0.2, 0.7, 0.1, 1); /* soft landing (splash) */
  --ease-standard: cubic-bezier(0.25, 0.1, 0.25, 1); /* symmetric */
  --motion-pop-scale: 0.98; /* enter-from scale for popovers/palette */
  --motion-rise: 4px; /* enter-from translateY for popovers/menus */

  --radius: 9px;
  /* 833 圆角三档收敛：small=紧凑控件/徽章，medium=按钮/卡片/菜单/浮层，pill=全圆胶囊。
     布局档位常量，不随主题变（主题语义圆角仍走 --radius / --button-radius）。
     迁移映射：6px→sm（等价）、4/5px→sm（±1-2px 归档）、8px→md（等价）、7/9/10px→md（±1-2px 归档）、999px→pill（等价）；
     3px 及以下（近直角微件/滚动条/描边）、12px 及以上（大容器/主题风格覆盖变体）不归档，行内 833-radius-wl 白名单注释。 */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-pill: 999px;
  --maxw: 960px;
  --maxw-inner: 100%;
  --mono: var(--font-mono);
  --sans: var(--font-ui);
  --font-sans: var(--font-ui);
}

:root[data-platform="windows"] {
  --font-ui: "Segoe UI Variable Text", "Segoe UI", "Microsoft YaHei UI",
    "Microsoft YaHei", "Noto Sans SC", Arial, sans-serif;
  --font-content-family: var(--font-ui);
  --font-mono: "Cascadia Code", "Cascadia Mono", Consolas, "Liberation Mono",
    ui-monospace, monospace;
  --font-smoothing: auto;
  --text-rendering: auto;
}

:root[data-platform="darwin"] {
  --font-ui: -apple-system, BlinkMacSystemFont, "SF Pro Text", "PingFang SC",
    "Hiragino Sans GB", "Helvetica Neue", Arial, sans-serif;
  --font-content-family: var(--font-ui);
  --font-mono: "SF Mono", SFMono-Regular, ui-monospace, Menlo, Monaco,
    "Cascadia Code", Consolas, monospace;
}

:root[data-platform="linux"] {
  --font-ui: system-ui, "Noto Sans", "Noto Sans CJK SC", "WenQuanYi Micro Hei",
    "Microsoft YaHei", Arial, sans-serif;
  --font-content-family: var(--font-ui);
  --font-mono: ui-monospace, "Cascadia Code", "JetBrains Mono",
    "Noto Sans Mono", "Liberation Mono", Consolas, monospace;
}

/* font-family presets */
:root[data-font-family="yahei"] {
  --font-ui: "Microsoft YaHei UI", "Microsoft YaHei", "微软雅黑", "PingFang SC", "Noto Sans SC",
    -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-content-family: var(--font-ui);
}

:root[data-font-family="pingfang"] {
  --font-ui: "PingFang SC", "苹方-简", "Noto Sans SC",
    "Microsoft YaHei", -apple-system, BlinkMacSystemFont,
    "Segoe UI", Roboto, sans-serif;
  --font-content-family: var(--font-ui);
}

:root[data-font-family="noto"] {
  --font-ui: "Noto Sans SC", "Noto Sans", "PingFang SC",
    "Microsoft YaHei", -apple-system, BlinkMacSystemFont,
    "Segoe UI", Roboto, sans-serif;
  --font-content-family: var(--font-ui);
}

:root[data-font-family="custom"] {
  --font-ui: var(--font-family-custom, "PingFang SC"),
    "PingFang SC", "Microsoft YaHei", "Noto Sans SC",
    -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    sans-serif;
  --font-content-family: var(--font-ui);
}

:root[data-mono-font-family="cascadia"] {
  --font-mono: "Cascadia Code", "Cascadia Mono", Consolas, "Liberation Mono",
    ui-monospace, monospace;
}

:root[data-mono-font-family="jetbrains"] {
  --font-mono: "JetBrains Mono", "Cascadia Code", "SF Mono", Consolas,
    ui-monospace, monospace;
}

:root[data-mono-font-family="sfmono"] {
  --font-mono: "SF Mono", SFMono-Regular, ui-monospace, Menlo, Monaco,
    "Cascadia Code", Consolas, monospace;
}

:root[data-mono-font-family="custom"] {
  --font-mono: var(--font-family-mono-custom, "Cascadia Code"),
    "Cascadia Code", "SF Mono", Consolas, ui-monospace, monospace;
}

@media (prefers-color-scheme: light) {
  :root:not([data-theme]) {
    color-scheme: light;

    --bg: #f7f8fb;
    --bg-soft: #eef2f7;
    --bg-elev: #ffffff;
    --bg-elev-2: #f2f5f9;
    --sidebar-bg: #f9f9f9;
    --sidebar-hover: #e8edf4;
    --sidebar-active: #eaf1ff;
    --chat-bg: #ffffff;
    --workspace-preview-bg: #ffffff;
    --workspace-files-bg: #f6f8fb;
    --workspace-files-hover: #edf2f7;
    --workspace-selection-bg: #eaf1ff;
    --workspace-selection-fg: var(--accent);
    --workspace-selection-bar: var(--accent);
    --border: #d8dee8;
    --border-soft: #e7ebf2;
    --fg: #111827;
    --fg-dim: #4b5563;
    --fg-faint: #8a94a6;
    --accent: #2f5fa8;
    --accent-fg: #fff;
    --accent-soft: rgba(47, 95, 168, 0.12);
    --accent-strong: #244f91;
    --chart-1: #006edb;
    --chart-2: #30a147;
    --chart-3: #eb670f;
    --chart-4: #894ceb;
    --chart-5: #ce2c85;
    --chart-other: #808fa3;
    --chat-user-bg: color-mix(in srgb, var(--accent) 9%, var(--bg-elev));
    --chat-user-border: color-mix(in srgb, var(--accent) 22%, var(--border-soft));
    --chat-user-fg: var(--fg);
    --chat-user-shadow: 0 8px 18px color-mix(in srgb, var(--accent) 8%, transparent);
    --ok: #15803d;
    --warn: #b45309;
    --err: #dc2626;
    --add-bg: rgba(21, 128, 61, 0.08);
    --add-fg: #15803d;
    --del-bg: rgba(220, 38, 38, 0.08);
    --del-fg: #dc2626;
    --code-bg: #f2f5f9;
    /* syntax (light) */
    --hl-keyword: #cf222e;
    --hl-string: #0a3069;
    --hl-number: #0550ae;
    --hl-comment: #6e7781;
    --hl-func: #8250df;
    --hl-type: #116329;
    --hl-builtin: #0550ae;
    --hl-meta: #6e7781;
    --list-row-title: #334155;
    --list-row-meta: #8a94a6;
    --list-row-hover-bg: #e8edf4;
    --list-row-current-bg: #dde7f7;
    --list-row-current-title: #111827;
    --list-row-current-meta: var(--accent);
    --tree-row-hover-bg: var(--workspace-files-hover);
    --tree-row-current-bg: color-mix(in srgb, var(--workspace-selection-bg) 42%, var(--workspace-files-bg));
    --tree-row-marker: var(--workspace-selection-bar);
    --mode-auto-bg: #2f5fa8;
    --mode-auto-border: #386dbb;
    --mode-auto-fg: #fff;
    /* 614：plan=紫 / goal=青（亮背景值，语义映射见根块注释）。 */
    --mode-plan-bg: rgba(124, 58, 237, 0.1);
    --mode-plan-border: color-mix(in srgb, #7c3aed 32%, var(--border));
    --mode-plan-fg: #7c3aed;
    --mode-goal-bg: rgba(13, 148, 136, 0.12);
    --mode-goal-border: color-mix(in srgb, #0f766e 32%, var(--border));
    --mode-goal-fg: #0f766e;
    --mode-yolo-bg: #e5484d;
    --mode-yolo-border: #ed5d62;
    --mode-yolo-fg: #fff;
    /* 614 修色：亮背景同提饱和（#c05e12 L*≈45 棕色域 → #ea580c），深字保对比。 */
    --mode-autopilot-bg: #ea580c;
    --mode-autopilot-border: #f4772e;
    --mode-autopilot-fg: #2b1503;
  }
}

/* Force light regardless of OS when the user picks it in Settings. */
:root[data-theme="light"] {
  color-scheme: light;

  --bg: #f7f8fb;
  --bg-soft: #eef2f7;
  --bg-elev: #ffffff;
  --bg-elev-2: #f2f5f9;
  --sidebar-bg: #f9f9f9;
