* {
  box-sizing: border-box;
}
html,
body,
#root {
  height: 100%;
  min-height: 100%;
  margin: 0;
}
html {
  cursor: default;
  /* WebKit/WKWebView auto-inflates text when layout changes (e.g. the file
     preview split appearing on first open). Nothing else in the app depends
     on text inflation, and it rescaled code rows so line spacing ballooned
     until the layout settled. Pin it off app-wide; the code viewer also
     re-asserts it locally. */
  -webkit-text-size-adjust: 100%;
}
body {
  --font-scale: var(--typography-interface-scale, var(--global-font-scale));
  --text-base: var(--typography-interface-size, calc(14px * var(--font-scale)));
  --font-content: var(--text-base);
  background: var(--bg);
  color: var(--fg);
  font-family: var(--typography-interface-font, var(--font-content-family));
  font-size: var(--text-base);
  line-height: 1.6;
  -webkit-font-smoothing: var(--font-smoothing);
  text-rendering: var(--text-rendering);
  font-synthesis-weight: auto;
  overflow: hidden;
}

button,
input,
select,
textarea {
  font-family: inherit;
}

/* Independent typography regions. Missing custom properties deliberately fall
/* Independent typography regions. Missing custom properties deliberately fall
   back to the global appearance settings, preserving existing installations. */
.transcript,
.transcript__live-region {
  --font-scale: var(--typography-conversation-scale, var(--global-font-scale));
  --text-base: var(--typography-conversation-size, calc(14px * var(--font-scale)));
  --font-content: var(--text-base);
  --font-content-family: var(--typography-conversation-font, var(--font-ui));
  font-family: var(--font-content-family);
  font-size: var(--font-content);
}
.composer-wrap {
  --font-scale: var(--typography-composer-scale, var(--global-font-scale));
  --text-base: var(--typography-composer-size, calc(14px * var(--font-scale)));
  --font-content: var(--text-base);
  --font-content-family: var(--typography-composer-font, var(--font-ui));
  font-family: var(--font-content-family);
  font-size: var(--font-content);
}
.code,
.md-code,
.tool,
.tool-group,
.readonly-batch {
  --font-scale: var(--typography-code-scale, var(--global-font-scale));
  --text-sm: var(--typography-code-size, calc(12px * var(--font-scale)));
  --font-code: var(--typography-code-size, calc(12px * var(--font-scale)));
  --font-code-family: var(--typography-code-font, var(--font-mono));
  font-family: var(--font-code-family);
  font-size: var(--font-code);
}
.statusbar,
.msg-meta,
.composer-meta,
.compaction__meta {
  --font-scale: var(--typography-metadata-scale, var(--global-font-scale));
  --font-status: var(--typography-metadata-size, calc(12px * var(--font-scale)));
  --font-metadata-family: var(--typography-metadata-font, var(--font-ui));
  font-family: var(--font-metadata-family);
  font-size: var(--font-status);
}

/* Root typography tokens are computed before inheritance, so a descendant
/* Root typography tokens are computed before inheritance, so a descendant
   --font-scale cannot retroactively change them. Re-declare the proportional
   tokens at each semantic region root to make independent scaling real. */
body,
.transcript,
.transcript__live-region,
.composer-wrap,
.code,
.md-code,
.tool,
.tool-group,
.readonly-batch,
.statusbar,
.msg-meta,
.composer-meta,
.compaction__meta {
  --text-2xs: calc(10px * var(--font-scale));
  --text-xs: calc(11px * var(--font-scale));
  --text-sm: calc(12px * var(--font-scale));
  --text-md: calc(13px * var(--font-scale));
  --text-lg: calc(15px * var(--font-scale));
  --text-xl: calc(18px * var(--font-scale));
  --font-caption: var(--text-xs);
  --font-control: var(--text-md);
  --font-control-small: var(--text-sm);
}

/* Only real hyperlinks get the pointer cursor; everything else (buttons, tabs,
/* Only real hyperlinks get the pointer cursor; everything else (buttons, tabs,
   tree rows, menu items) stays default so the UI reads as native chrome. */
a[href] {
  cursor: pointer;
}

.app {
  height: var(--app-viewport-height, 100%);
  min-height: 0;
  overflow-x: auto;
  overflow-y: hidden;
}

.layout {
  --sidebar-width: var(--sidebar-expanded-width, clamp(264px, 18vw, 300px));
  --chat-min-width: 400px;
  --workspace-width: 420px;
  --workspace-resizer-width: 8px;
  --terminal-height: 280px;
  --app-chrome-height: 38px;
  --topicbar-height: 56px;
  --statusbar-height: var(--statusbar-dock-height);
  --chrome-toggle-size: 42px;
  --chrome-left-safe-offset: 0px;
  --chrome-left-toggle-offset: max(var(--sidebar-width), var(--chrome-left-safe-offset));
  --chrome-right-toggle-offset: 0px;
  position: relative;
  display: grid;
  justify-content: start;
  grid-template-rows: var(--app-chrome-height) minmax(0, 1fr) var(--statusbar-height);
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
  height: 100%;
  min-height: 0;
  width: 100%;
  background: var(--bg);
  transition: grid-template-columns 0.16s ease, min-width 0.16s ease;
}

.layout.layout--statusbar-hidden,
:root[data-theme-style] .layout.layout--statusbar-hidden {
  --statusbar-height: 0px;
}

/* Automation is a focused main page. These rules only remove presentation
   rows; workspace and terminal preferences remain in their stores. */

.app--darwin .layout {
  --app-chrome-height: 44px;
  --chrome-toggle-size: 36px;
  --chrome-left-safe-offset: 112px;
  transition:
    grid-template-columns 0.28s cubic-bezier(0.2, 0.72, 0.2, 1),
    min-width 0.28s cubic-bezier(0.2, 0.72, 0.2, 1);
}

.layout--resizing {
  cursor: col-resize;
  transition: none;
}
.layout--resizing * {
  user-select: none;
}
.layout--sidebar-collapsed {
  --sidebar-width: 0px;
  grid-template-columns: 0px minmax(0, 1fr);
}
.layout:not(.layout--sidebar-collapsed):not(.layout--workspace-open):not(.layout--workspace-maximized) {
  grid-template-columns: var(--sidebar-expanded-width) minmax(0, 1fr);
}
.layout--workspace-open {
  --chrome-right-toggle-offset: var(--workspace-width);
  min-width: min(780px, 100vw);
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr) minmax(0, var(--workspace-width));
}
.layout--workspace-open:not(.layout--sidebar-collapsed) {
  min-width: min(780px, 100vw);
  grid-template-columns: var(--sidebar-expanded-width) minmax(0, 1fr) minmax(0, var(--workspace-width));
}
.layout--workspace-open.layout--sidebar-collapsed {
  min-width: min(560px, 100vw);
  grid-template-columns: 0px minmax(0, 1fr) minmax(0, var(--workspace-width));
}
.layout--workspace-maximized {
  min-width: 0;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
}
.layout--workspace-maximized.layout--sidebar-collapsed {
  grid-template-columns: 0px minmax(0, 1fr);
}
/* Terminal drawer — an independent bottom panel below the chat pane.
/* Terminal drawer — an independent bottom panel below the chat pane.
   Sidebar and workspace panel stay full-height in columns 1 and 3;
   the terminal occupies column 2 row 3, statusbar at row 4. */
.layout--terminal-drawer-open {
  grid-template-rows: var(--app-chrome-height) minmax(0, 1fr) var(--terminal-height, 280px) var(--statusbar-height);
  transition:
    grid-template-columns 0.16s ease,
    min-width 0.16s ease,
    grid-template-rows 0.22s cubic-bezier(0.2, 0.72, 0.2, 1);
}
/* Disable the open/close transition during a terminal resize drag. */
.layout--terminal-resizing.layout--terminal-drawer-open {
  transition: grid-template-columns 0.16s ease, min-width 0.16s ease;
}
.layout--terminal-drawer-open .terminal-drawer-resizer {
  grid-row: 2;
  grid-column: 2;
  align-self: end;
  position: relative;
  height: 8px;
  width: 100%;
  cursor: row-resize;
  z-index: var(--z-local-handle);
  background: transparent;
  border: 0;
  margin-bottom: -4px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s ease, background 0.12s ease;
}
/* Show the resizer only when the terminal is actually expanded. */
.layout--terminal-drawer-expanded .terminal-drawer-resizer {
  opacity: 1;
  pointer-events: auto;
}
.layout--terminal-drawer-open .terminal-drawer-resizer:hover,
.layout--terminal-drawer-open .terminal-drawer-resizer:active {
  background: var(--accent-soft);
}
.layout--terminal-drawer-open .terminal-drawer {
  grid-row: 3;
  grid-column: 2;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
/* Border and background only visible when the terminal is actually expanded,
/* Border and background only visible when the terminal is actually expanded,
   avoiding a 1px artifact line when the drawer is collapsed to 0px. */
.layout--terminal-drawer-expanded .terminal-drawer {
  background: var(--terminal-bg, #111315);
  border-top: 1px solid var(--terminal-border);
}
.layout--terminal-drawer-open .terminal-drawer .terminal-panel {
  height: 100%;
}
.layout--terminal-drawer-open .terminal-drawer .terminal-panel__header {
  border-bottom: 1px solid var(--terminal-border);
}
/* When the terminal drawer is open, the sidebar and workspace panel span the
/* When the terminal drawer is open, the sidebar and workspace panel span the
   full content height (rows 2–3) so only the chat pane is shortened. */
.layout.layout--terminal-drawer-open .sidebar {
  grid-row: 2 / 4;
}
.layout.layout--terminal-drawer-open .workbench-dock {
  grid-row: 2 / 4;
}
/* The dock's vertical drag handle must span the same rows as the dock so the
/* The dock's vertical drag handle must span the same rows as the dock so the
   resizer line extends from the top of the chat area down to the bottom of
   the terminal drawer. */
.layout--terminal-drawer-open .workspace-panel-resizer {
  grid-row: 2 / 4;
}
/* StatusBar shifts to row 4 when the terminal drawer adds an extra row. */
.layout--terminal-drawer-open .statusbar {
  grid-row: 4;
}

/* Keep the old layout--terminal-open rules for backward compat — they are
/* Keep the old layout--terminal-open rules for backward compat — they are
   no longer added by App.tsx but may remain in cached localStorage styles. */
.layout--terminal-open {
  grid-template-columns: var(--sidebar-expanded-width) minmax(0, 1fr);
  grid-template-rows: var(--app-chrome-height) minmax(0, 1fr) minmax(220px, min(42vh, 440px)) var(--statusbar-height);
}
.layout--terminal-open.layout--sidebar-collapsed {
  grid-template-columns: 0px minmax(0, 1fr);
}
.layout--terminal-open .workbench-dock {
  grid-row: 3;
  grid-column: 2;
  width: 100%;
  height: auto;
  max-width: none;
  border-top: 1px solid var(--border-soft);
  border-left: 0;
}
.layout--terminal-open .workbench-dock__tools {
  display: none;
}
.layout--terminal-open .workspace-panel-resizer {
  display: none;
}
.layout--terminal-open .statusbar {
  grid-row: 4;
}
.layout--workspace-maximized .chat-pane {
  display: none;
}
.layout--workspace-maximized .workspace-panel-resizer {
  display: none;
}

/* tl1191: Suspense skeleton for the classic-only chrome chunk (module-level
   prefetch makes it near-invisible). The row geometry lives here — shared
   skeleton stays in the app-shell stylesheet — so a late chunk paints into a
   reserved row with zero layout shift and keeps the drag region alive. */
.app-chrome--loading {
  grid-row: 1;
  grid-column: 1 / -1;
  height: var(--app-chrome-height);
  background: var(--bg-soft);
  border-bottom: 1px solid var(--border-soft);
}

.sidebar {
  --sidebar-entry-content-inset: 12px;
  grid-row: 2;
  grid-column: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 12px 10px 12px;
  background: var(--sidebar-bg);
  border-right: 1px solid var(--border-soft);
  --wails-draggable: drag;
  user-select: none;
  overflow: hidden;
}

/* Windows window movement belongs to the dedicated chrome surfaces. Keep the
/* Windows window movement belongs to the dedicated chrome surfaces. Keep the
   navigation sidebar and its adjacent resize handle out of the native drag path. */
.app--windows .sidebar {
  --wails-draggable: no-drag;
}

.app--darwin .sidebar {
  transform: translateX(0);
  opacity: 1;
  transition:
    opacity 0.22s ease,
    transform 0.28s cubic-bezier(0.2, 0.72, 0.2, 1),
    padding 0.28s cubic-bezier(0.2, 0.72, 0.2, 1),
    border-color 0.22s ease;
}
.sidebar button,
.sidebar input,
.sidebar select {
