}
.sidebar__new,
.sidebar__navitem {
  width: 100%;
  min-width: 0;
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  text-align: left;
  transition: color 0.12s, background 0.12s;
}
.sidebar__new {
  display: flex;
  flex: 0 0 44px;
  align-items: center;
  gap: 9px;
  height: 44px;
  min-height: 44px;
  padding: 0 var(--sidebar-entry-content-inset);
  margin-bottom: 10px;
  background: var(--grad);
  border: 0;
  border-radius: 12px; /* 833-radius-wl:large */
  color: var(--accent-text);
  font-size: var(--text-md);
  font-weight: 600;
  box-shadow: 0 6px 18px -6px var(--accent), var(--shadow-1);
  /* Logo, CTA icon, and search icon share the same content inset; CTA stays visually stronger. */
  transition:
    color var(--dur-fast),
    background var(--dur-fast),
    box-shadow var(--dur-fast),
    filter var(--dur-fast),
    transform var(--dur-fast);
}
.sidebar__new:hover,
.sidebar__navitem:hover {
  background: var(--sidebar-hover);
  color: var(--fg);
}
.sidebar__new:hover {
  background: var(--grad);
  color: var(--accent-text);
  filter: saturate(1.08) brightness(1.03);
  transform: translateY(-1px);
}
.sidebar__new:active {
