/* ── Shimmer sweep for running items ──────────────────────────────── */
.tool__head[data-running],
.reasoning__head[data-running],
.turn-collapse__reasoning-head[data-running] {
  background: linear-gradient(
    105deg,
    var(--fg-faint) 0%,
    var(--fg-faint) 38%,
    var(--fg) 46%,
    var(--fg) 54%,
    var(--fg-faint) 62%,
    var(--fg-faint) 100%
  );
  background-size: 220% 100%;
  background-position: 100% 0;
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  animation: shimmer-sweep 5s linear infinite;
}
.tool__head[data-running] .tool__chevron,
.tool__head[data-running] .tool__duration,
.reasoning__head[data-running] svg,
.reasoning__head[data-running] .reasoning__meta,
.turn-collapse__reasoning-head[data-running] svg {
