  color: var(--fg-faint);
  font-size: var(--font-caption);
  flex-shrink: 0;
}
.process-card__chevron {
  display: inline-flex;
  color: var(--fg-faint);
  transition: transform 0.15s ease;
  flex-shrink: 0;
}
