.composer-wrap {
  position: relative;
  max-width: var(--maxw);
  margin: 0 auto;
}
.composer-card {
  container-type: inline-size;
  position: relative;
  border: 1px solid var(--border);
  border-radius: 12px; /* 833-radius-wl:large */
  background: var(--bg-elev);
  overflow: visible;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.08);
  transition: border-color 0.12s;
}
.composer-card--resized {
  /* --composer-height excludes the run strip and may grow above the user's
     saved minimum to reveal a longer draft. The strip reservation stays in
     this calc so live resize and content sizing share one coordinate space. */
  height: calc(var(--composer-height) + var(--composer-run-strip-reserved, 0px));
  display: flex;
  flex-direction: column;
}
/* Ported from studio's glowring: a constant-speed trace along the perimeter.
   Mounted only during active work, so idle/waiting cards consume no frames. */
.composer-glowring {
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  padding: 1.5px;
  pointer-events: none;
  overflow: hidden;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}
.composer-glowring i {
  position: absolute;
  width: 150px;
  height: 150px;
  background: radial-gradient(circle closest-side, var(--accent) 0%,
    color-mix(in srgb, var(--accent) 42%, transparent) 38%, transparent 72%);
  offset-path: border-box;
  animation: composer-border-trace 3.4s linear infinite;
}
@keyframes composer-border-trace {
  to { offset-distance: 100%; }
}
@supports not (offset-path: border-box) {
  .composer-glowring { background: var(--accent); }
  .composer-glowring i { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .composer-glowring { background: color-mix(in srgb, var(--accent) 60%, transparent); }
  .composer-glowring i { display: none; animation: none; }
}
.composer-card:focus-within {
  border-color: var(--fg-faint);
}
/* Run strip: an in-flow bar at the top of the card. For user-sized cards JS
/* Run strip: an in-flow bar at the top of the card. For user-sized cards JS
   adds the strip's reserved height so the input's logical minimum is unchanged.
   For natural-height cards the card grows without the explicit reservation. */
.composer-run-strip {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 24px;
  padding: 4px 14px 0;
  color: var(--accent);
  font-family: var(--sans);
  font-size: var(--text-sm);
}
.composer-card--waiting .composer-run-strip {
  /* inherited from the card border tint; no extra rule needed */
}
.composer-run-strip__dot {
  flex: 0 0 auto;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  animation: pulse 1.2s ease-in-out infinite;
}
.composer-run-strip__text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.composer-run-strip__metrics {
  color: var(--fg-dim);
}
/* 任务 1082：本轮工具/文件/检索汇总——与 metrics 同维度的次级读数，
   自带 8px 左距（不依赖 flex gap 语义），不挤压状态文本的省略号行为。 */
.composer-run-strip__tally {
  flex: 0 0 auto;
  margin-left: 8px;
  color: var(--fg-dim);
  white-space: nowrap;
}
.composer-run-strip--waiting {
  color: color-mix(in srgb, var(--warn) 74%, var(--fg));
}
.composer-run-strip--waiting .composer-run-strip__dot {
  animation: none;
}
/* Attention handoff: while a prompt card is waiting on the user, the card
/* Attention handoff: while a prompt card is waiting on the user, the card
   drops the accent running tint and takes a calm warn edge instead. */
.composer-card--waiting {
  border-color: color-mix(in srgb, var(--warn) 30%, var(--border));
}
/* Provider-recovery wait: a card above the composer so a minute-scale wait is
   never mistaken for model work (#9890). */
.recovery-wait-banner {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 8px;
  padding: 10px 14px;
  border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--border));
  border-radius: 12px; /* 833-radius-wl:large */
  background: color-mix(in srgb, var(--warn) 10%, var(--bg-elev));
  font: 12px var(--sans);
}
.recovery-wait-banner__body {
  display: grid;
  flex: 1;
  gap: 4px;
  min-width: 0;
}
.recovery-wait-banner__title {
  font-weight: 600;
  color: color-mix(in srgb, var(--warn) 74%, var(--fg));
}
.recovery-wait-banner__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  color: var(--fg-dim);
  font-variant-numeric: tabular-nums;
}
.recovery-wait-banner__hint {
  color: var(--fg-faint);
}
.recovery-wait-banner__stop {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border: 1px solid currentColor;
  border-radius: var(--radius-md);
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.recovery-wait-banner__stop:disabled {
  opacity: 0.6;
  cursor: default;
}
.composer-resize-handle {
  --wails-draggable: no-drag;
  appearance: none;
  position: absolute;
  top: -10px;
  left: 0;
  right: 0;
  z-index: var(--z-local-handle-active);
  height: 18px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: ns-resize;
  touch-action: none;
}
.composer-resize-handle::before {
  content: "";
  position: absolute;
  top: 7px;
  left: 50%;
  width: 72px;
  height: 4px;
  transform: translateX(-50%);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--fg-faint) 38%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--border) 82%, transparent);
  opacity: 0.72;
  transition: background 0.12s, box-shadow 0.12s, opacity 0.12s;
}
.composer-resize-handle:hover::before,
.composer-resize-handle:focus-visible::before,
.composer-card--resizing .composer-resize-handle::before {
  background: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 70%, transparent);
  opacity: 0.95;
}
/* Hide the resize handle while the input is focused — the user is typing,
/* Hide the resize handle while the input is focused — the user is typing,
   not resizing.  The handle otherwise appears as a colored pill above the
   card on hover (which always co-occurs with focus after a click). */
.composer-card:focus-within .composer-resize-handle::before {
  opacity: 0 !important;
  background: color-mix(in srgb, var(--fg-faint) 38%, transparent) !important;
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--border) 82%, transparent) !important;
}
.composer-resize-handle:focus-visible {
  outline: none;
}
.composer-resizing,
.composer-resizing * {
  cursor: ns-resize !important;
  user-select: none;
}
.slashmenu {
