  background: none;
  color: var(--fg);
  font: inherit;
  font-size: var(--font-content);
  line-height: 1.55;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  caret-color: var(--fg);
}
.composer__rich-input:empty::before {
