/* Task 113: turn-level edit list */
.turn-edit-list { margin-top: 8px; border: 1px solid var(--border-soft); border-radius: 8px; background: var(--bg-soft); overflow: hidden; }
.turn-edit-list__head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 10px; border-bottom: 1px solid var(--border-soft); }
