.turn-edit-list__actions { display: flex; flex-wrap: wrap; gap: 6px; }
.turn-edit-list__files { list-style: none; margin: 0; padding: 0; }
.turn-edit-list__file { display: grid; grid-template-columns: auto 1fr auto; gap: 8px; align-items: center; padding: 6px 10px; border-bottom: 1px solid var(--border-soft); font-size: var(--text-xs); }
