.turn-edit-list__hint { margin: 0; padding: 0 10px 8px; color: var(--fg-dim); font-size: var(--text-xs); }

/* Task 114: session artifacts & references */
.side-files { display: grid; gap: 12px; padding: 12px; min-width: 0; }
.side-files__group { border: 1px solid var(--border-soft); border-radius: 8px; overflow: hidden; }
.side-files__group > summary { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 10px; cursor: pointer; list-style: none; background: var(--bg-soft); font-size: var(--text-sm); font-weight: 600; color: var(--fg); }
.side-files__group > summary::-webkit-details-marker { display: none; }
.side-files__meta { font-weight: 400; color: var(--fg-dim); font-size: var(--text-xs); }
.side-files__list { list-style: none; margin: 0; padding: 0; max-height: 240px; overflow: auto; }
.side-files__item { display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-top: 1px solid var(--border-soft); font-size: var(--text-xs); color: var(--fg); }
.side-files__item span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--mono, ui-monospace, monospace); }
.side-files__foot { display: flex; flex-wrap: wrap; gap: 6px; padding: 8px 10px; border-top: 1px solid var(--border-soft); }
.side-files__empty { padding: 12px; color: var(--fg-dim); font-size: var(--text-sm); }
/* Task 260: dock-tab variant fills the dock body (the body clips overflow). */
