.tooltip-trigger {
  display: inline-flex;
  min-width: 0;
}
.tooltip-trigger--fill {
  display: flex;
  width: 100%;
}
.tooltip-trigger--block {
  display: flex;
}
.tooltip {
  --wails-draggable: no-drag;
  --tooltip-arrow-x: 50%;
  --tooltip-arrow-y: 50%;
  position: fixed;
  z-index: var(--z-tooltip);
  max-width: min(320px, calc(100vw - 16px));
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-elev);
  color: var(--fg);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.28);
  font-size: var(--text-sm);
  line-height: 1.35;
  overflow-wrap: anywhere;
  pointer-events: none;
  white-space: pre-line;
  animation: tooltip-in var(--dur-fast) var(--ease-out) both;
}
.tooltip--top {
  --tooltip-from-y: var(--motion-rise);
  --tooltip-from-x: 0;
}
.tooltip--bottom {
  --tooltip-from-y: calc(-1 * var(--motion-rise));
  --tooltip-from-x: 0;
}
.tooltip--left {
  --tooltip-from-x: var(--motion-rise);
  --tooltip-from-y: 0;
}
.tooltip--right {
  --tooltip-from-x: calc(-1 * var(--motion-rise));
  --tooltip-from-y: 0;
}
@keyframes tooltip-in {
  from {
    opacity: 0;
    transform: translate(var(--tooltip-from-x, 0), var(--tooltip-from-y, 0));
  }
  to {
    opacity: 1;
    transform: translate(0, 0);
  }
}
.tooltip::before {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  border: 1px solid var(--border);
  background: var(--bg-elev);
  transform: rotate(45deg);
}
.tooltip--top::before {
  left: calc(var(--tooltip-arrow-x) - 4px);
  bottom: -5px;
  border-left: 0;
  border-top: 0;
}
.tooltip--bottom::before {
  left: calc(var(--tooltip-arrow-x) - 4px);
  top: -5px;
  border-right: 0;
  border-bottom: 0;
}
.tooltip--left::before {
  right: -5px;
  top: calc(var(--tooltip-arrow-y) - 4px);
  border-left: 0;
  border-bottom: 0;
}
.tooltip--right::before {
  left: -5px;
  top: calc(var(--tooltip-arrow-y) - 4px);
  border-right: 0;
  border-top: 0;
}
.tooltip .md {
  white-space: normal;
  font-size: inherit;
  line-height: inherit;
}
.tooltip .md pre {
  max-height: 240px;
  overflow: auto;
  font-size: var(--text-xs);
}
/* 任务1033: interactive hover card for long command/task labels. Width is set
   inline as min(maxWidthCh ch, 46vw); pointer-events flips on so the copy
   button is reachable, and the text wraps per the JS line model. */
.tooltip--interactive {
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-width: none;
  pointer-events: auto;
}
.tooltip__text {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-family: var(--font-code-family);
}
.tooltip__foot {
  display: flex;
