}
.workspace-files__scope-meta {
  flex: 0 1 auto;
  color: var(--fg-faint);
}
.workspace-files__scope button {
  --wails-draggable: no-drag;
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-faint);
}
.workspace-files__scope button:hover {
  background: var(--tree-row-hover-bg);
  color: var(--fg);
}
.workspace-tree {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 0 6px 12px;
}
.workspace-tree__row {
  --wails-draggable: no-drag;
  position: relative;
  width: 100%;
  min-width: 0;
  height: var(--tree-row-height);
  display: flex;
  align-items: center;
  gap: 6px;
  border: none;
  border-radius: var(--tree-row-radius);
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  font-size: 12.5px;
  text-align: left;
}
.workspace-tree__guides {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.12s ease;
}
/* Guides appear only while hovering the files panel so the expanded-tree
/* Guides appear only while hovering the files panel so the expanded-tree
   connectors don't clutter the default view. */
.workspace-files:hover .workspace-tree__guides,
.workspace-files:focus-within .workspace-tree__guides {
  opacity: 1;
}
.workspace-tree__guide {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: color-mix(in srgb, var(--fg-faint) 28%, transparent);
}
.workspace-tree__row:hover {
  background: var(--tree-row-hover-bg);
  color: var(--fg);
}
.workspace-tree__row--active {
  background: var(--tree-row-current-bg);
  color: var(--tree-row-current-fg);
}
.workspace-tree__row--active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 5px;
  bottom: 5px;
  width: 2px;
  border-radius: var(--radius-pill);
  background: var(--tree-row-marker);
}
.workspace-tree__row--search {
  height: auto;
  min-height: 38px;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
}
.workspace-tree__row--search.workspace-tree__row--active {
  color: var(--fg);
}
.workspace-change {
  --wails-draggable: no-drag;
  width: 100%;
  min-width: 0;
  min-height: 48px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 8px;
  border: 0;
  border-radius: var(--tree-row-radius);
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  text-align: left;
}
.workspace-change > svg {
  flex: 0 0 auto;
  width: 14px;
  height: 14px;
}
.workspace-change-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  border-radius: var(--tree-row-radius);
}
/* Hover/selection highlight spans the whole row (file entry + revert button)
/* Hover/selection highlight spans the whole row (file entry + revert button)
   so the revert control sits inside the same background as the file. The
   inner file button stays transparent and inherits the row's surface. */
.workspace-change-row:hover {
  background: var(--tree-row-hover-bg);
}
.workspace-change-row:hover .workspace-change {
  color: var(--fg);
}
.workspace-change-row:has(.workspace-change--active) {
  background: var(--tree-row-current-bg);
}
.workspace-change-row:has(.workspace-change--active) .workspace-change {
  color: var(--tree-row-current-fg);
}
.workspace-change-row .workspace-change {
  flex: 1 1 auto;
  border-radius: 0;
}
.workspace-change__revert {
  --wails-draggable: no-drag;
  position: absolute;
  top: 50%;
  right: 8px;
  transform: translateY(-50%);
  min-width: 42px;
  height: 26px;
  padding: 0 8px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  /* Opaque surface so the overlay fully covers the status text beneath it —
     a transparent fill would let the badge glyphs show through the button. */
  background: var(--bg-soft);
  color: var(--fg-faint);
  font: inherit;
  font-size: var(--text-xs);
  line-height: 1;
  cursor: pointer;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast), background var(--dur-fast);
}
/* The revert control is a per-row action overlaid on the status badge: hidden
/* The revert control is a per-row action overlaid on the status badge: hidden
   until the row is hovered, then revealed in the same right-hand slot so it
   reads as replacing the badge. Keyboard focus reveals it too, so the action
   is reachable without a pointer. */
.workspace-change-row:hover .workspace-change__revert,
.workspace-change-row:has(.workspace-change--active) .workspace-change__revert,
.workspace-change__revert:focus-visible {
  opacity: 1;
  pointer-events: auto;
}
.workspace-change__revert:hover,
.workspace-change__revert:focus-visible {
  border-color: color-mix(in srgb, var(--danger) 38%, var(--border));
  background: color-mix(in srgb, var(--danger) 9%, var(--bg-soft));
  color: color-mix(in srgb, var(--danger) 82%, var(--fg));
}
.workspace-change__revert:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--danger) 24%, transparent);
  outline-offset: 2px;
}
.workspace-change--disabled {
  cursor: default;
}
.workspace-change--disabled:hover {
  background: transparent;
  color: var(--fg-dim);
}
.workspace-change--active {
  /* Background now lives on the row (see .workspace-change-row:has(...)); the
     entry itself only tints the text so the revert button shares the surface. */
  color: var(--tree-row-current-fg);
}
.workspace-change__body {
  min-width: 0;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.workspace-change__name,
.workspace-change__path,
.workspace-change__detail {
