  font-weight: 560;
}
.workspace-change__path {
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.workspace-change__detail {
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.workspace-change__meta {
  flex: 0 0 auto;
  max-width: 96px;
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 3px;
}
.workspace-change__badge {
  /* Pure status label — intentionally non-interactive: no border, no
