.drawer {
  position: relative;
  width: min(var(--drawer-width, 440px), 92vw);
  height: 100%;
  background: var(--bg-elev);
  border-left: 1px solid var(--border);
  box-shadow: -18px 0 48px rgba(0, 0, 0, 0.46);
  display: flex;
  flex-direction: column;
  animation: drawer-in var(--dur-slow) var(--ease-out) both;
}
.drawer--wide {
  width: min(var(--drawer-width, 720px), 94vw);
}
.drawer-resizer {
  --wails-draggable: no-drag;
  position: absolute;
  top: 0;
  bottom: 0;
  left: -4px;
  z-index: var(--z-local-handle);
  width: 8px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: col-resize;
}
.drawer-resizer::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
  background: transparent;
  transition: background 0.12s, box-shadow 0.12s;
}
.drawer-resizer:hover::after,
.drawer-resizer:focus-visible::after,
.drawer--resizing .drawer-resizer::after {
  background: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 24%, transparent);
}
.drawer--resizing,
.drawer--resizing * {
  cursor: col-resize !important;
  user-select: none;
}
@keyframes drawer-in {
  from {
    transform: translateX(24px);
    opacity: 0;
  }
}
@keyframes drawer-out {
  to {
    transform: translateX(24px);
    opacity: 0;
  }
}
.drawer[data-state="closing"] {
  animation: drawer-out var(--dur-slow) var(--ease-out) both;
}
.drawer__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background: var(--bg-elev);
  border-bottom: 1px solid var(--border);
}
.drawer__title {
  font-size: 15px;
  font-weight: 650;
  color: var(--fg);
}
.drawer__summary {
  margin-top: 3px;
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.drawer__actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.drawer__body {
  overflow-y: auto;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

