  color: var(--fg-faint);
}
.mem-fact__main {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  flex: 1;
}
.mem-fact__title {
  min-width: 0;
  font-size: var(--text-md);
  font-weight: 650;
  color: var(--fg);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mem-fact__meta {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  color: var(--fg-faint);
  font-size: 10.5px;
  overflow: hidden;
}
.mem-fact__type {
  flex: none;
  display: inline-flex;
  align-items: center;
  height: 16px;
  padding: 0 7px;
  border-radius: var(--radius-pill);
  font-family: var(--font-sans, inherit);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.01em;
  text-transform: capitalize;
  color: var(--mem-type-color, var(--fg-dim));
  background: color-mix(in srgb, var(--mem-type-color, var(--fg-faint)) 16%, transparent);
}
.mem-fact__scope {
  flex: none;
  display: inline-flex;
  align-items: center;
  height: 16px;
  padding: 0 7px;
  border: 1px solid color-mix(in srgb, var(--mem-scope-color, var(--fg-faint)) 34%, transparent);
  border-radius: var(--radius-pill);
  color: var(--mem-scope-color, var(--fg-dim));
  background: color-mix(in srgb, var(--mem-scope-color, var(--fg-faint)) 9%, transparent);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0;
  white-space: nowrap;
}
.mem-fact__scope[data-mem-scope="project"] { --mem-scope-color: var(--ok); }
.mem-fact__scope[data-mem-scope="global"] { --mem-scope-color: var(--accent); }
.mem-fact__slug {
  min-width: 0;
  font-family: var(--mono);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mem-freshness {
  flex: none;
  display: inline-flex;
  align-items: center;
  min-height: 16px;
  color: var(--fg-dim);
  font-size: 10px;
  font-weight: 650;
  white-space: nowrap;
}
.mem-freshness--fresh { color: var(--ok); }
.mem-freshness--stale { color: var(--warning, #d69a32); }
.mem-fact__archived {
  flex: none;
  color: var(--fg-faint);
}
.mem-fact__desc {
  min-width: 0;
  font-size: var(--text-sm);
  color: var(--fg-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mem-fact__links {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  padding: 0 10px 9px 32px;
}
.mem-link-chip {
  display: inline-flex;
  max-width: 100%;
  min-height: 22px;
  align-items: center;
  padding: 2px 7px;
  border: 1px solid var(--accent-soft);
  border-radius: var(--radius-pill);
  background: var(--accent-soft);
  color: var(--accent);
  font: inherit;
  font-family: var(--mono);
  font-size: 10.5px;
  line-height: 1.2;
}
.mem-link-chip:hover {
  border-color: color-mix(in srgb, var(--accent) 42%, transparent);
}
.mem-link-chip--dead {
  border-color: color-mix(in srgb, var(--danger, #d66) 30%, transparent);
  background: color-mix(in srgb, var(--danger, #d66) 10%, transparent);
  color: var(--danger, #d66);
  cursor: help;
  text-decoration: line-through;
}
.mem-fact__detail {
  border-top: 1px solid var(--border-soft);
  padding: 10px;
  background: color-mix(in srgb, var(--bg) 54%, transparent);
}
.mem-fact__body {
  font-size: var(--text-sm);
  color: var(--fg-dim);
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}
.mem-fact__provenance {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 12px;
  margin-top: 9px;
  color: var(--fg-faint);
  font-size: var(--font-caption);
}
.mem-fact__provenance code {
  color: var(--fg-dim);
  font-family: var(--mono);
  overflow-wrap: anywhere;
}
.mem-revisions {
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid var(--border-soft);
}
.mem-revisions__head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  color: var(--fg-dim);
  font-size: var(--font-caption);
}
.mem-revision {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 32px;
  border-top: 1px solid var(--border-soft);
}
.mem-revision > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}
.mem-revision strong { color: var(--fg-dim); font-size: var(--font-caption); }
.mem-revision span { color: var(--fg-faint); font-size: var(--text-2xs); }
.mem-context-notice {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 12px;
  padding: 9px 10px;
  border-left: 3px solid var(--warning, #d69a32);
  background: color-mix(in srgb, var(--warning, #d69a32) 8%, transparent);
  color: var(--fg-dim);
}
.mem-context-notice > svg { flex: none; margin-top: 1px; color: var(--warning, #d69a32); }
.mem-context-notice > div { display: flex; min-width: 0; flex-direction: column; gap: 3px; }
.mem-context-notice strong { color: var(--fg); font-size: var(--font-control-small); }
.mem-context-notice span { font-size: var(--font-caption); line-height: 1.4; }
.mem-context-notice--muted { border-left-color: var(--fg-faint); background: var(--bg-soft); }
.mem-context-notice--muted > svg { color: var(--fg-faint); }
.mem-recall-summary {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-soft);
}
.mem-recall-summary > svg { flex: none; color: var(--accent); }
.mem-recall-summary > div { display: flex; min-width: 0; flex-direction: column; gap: 4px; }
.mem-recall-summary strong { color: var(--fg); font-size: var(--font-control); overflow-wrap: anywhere; }
.mem-recall-summary span { color: var(--fg-faint); font-size: var(--font-caption); }
.mem-recall-hits { display: flex; flex-direction: column; }
.mem-recall-hit { padding: 11px 0; border-bottom: 1px solid var(--border-soft); }
.mem-recall-hit__head { display: flex; justify-content: space-between; gap: 12px; }
.mem-recall-hit__head strong { color: var(--fg); font-size: var(--font-control-small); }
.mem-recall-hit__head > span { color: var(--accent); font-family: var(--mono); font-size: var(--font-caption); }
.mem-recall-hit p { margin: 8px 0 4px; color: var(--fg-dim); font-size: var(--text-sm); line-height: 1.5; white-space: pre-wrap; }
.mem-recall-hit small { color: var(--fg-faint); font-size: var(--font-caption); }
.mem-instruction-diagnostics {
  margin-bottom: 12px;
  padding: 10px 0;
  border-block: 1px solid var(--border-soft);
}
.mem-instruction-diagnostics__title { display: flex; align-items: center; gap: 6px; color: var(--warning, #d69a32); font-size: var(--font-control-small); font-weight: 700; }
.mem-instruction-diagnostic { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 3px 8px; padding-top: 8px; font-size: var(--font-caption); }
.mem-instruction-diagnostic strong { color: var(--fg-dim); }
.mem-instruction-diagnostic span { color: var(--fg-dim); overflow-wrap: anywhere; }
.mem-instruction-diagnostic code { grid-column: 2; color: var(--fg-faint); font-family: var(--mono); overflow-wrap: anywhere; }
.mem-doc__expanded { border-top: 1px solid var(--border-soft); }
.mem-doc__expanded .mem-doc__body { border-top: 0; }
.mem-doc__imports { display: flex; flex-direction: column; gap: 4px; padding: 9px 10px; border-top: 1px solid var(--border-soft); }
.mem-doc__imports strong { color: var(--fg-dim); font-size: var(--font-caption); }
.mem-doc__imports code { color: var(--fg-faint); font-family: var(--mono); font-size: var(--text-2xs); overflow-wrap: anywhere; }
.mem-archive__path {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--border-soft);
  color: var(--fg-faint);
  font-family: var(--mono);
  font-size: var(--text-xs);
  line-height: 1.45;
  word-break: break-all;
}
.mem-fact__forget {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--fg-dim);
}
.mem-fact__forget:hover {
  color: var(--danger, #d66);
  border-color: color-mix(in srgb, var(--danger, #d66) 36%, transparent);
}
.mem-fact__actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 10px;
}
.mem-confirm {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.mem-danger {
  color: var(--danger, #d66);
  border-color: color-mix(in srgb, var(--danger, #d66) 34%, transparent);
  background: color-mix(in srgb, var(--danger, #d66) 10%, transparent);
}
.mem-danger:hover {
  color: var(--danger, #d66);
  border-color: color-mix(in srgb, var(--danger, #d66) 52%, transparent);
}
.mem-deadline {
  margin-top: 8px;
  color: var(--danger, #d66);
  font-size: 11.5px;
}
.mem-error {
  margin-top: 8px;
  padding: 7px 9px;
  border: 1px solid color-mix(in srgb, var(--danger, #d66) 34%, transparent);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--danger, #d66) 10%, transparent);
  color: var(--danger, #d66);
  font-size: 11.5px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.mem-hint--error {
  color: var(--danger, #d66);
}
.mem-fact--hl {
  background: var(--accent-soft, rgba(120, 170, 255, 0.12));
  border-color: color-mix(in srgb, var(--accent) 42%, transparent);
}
.mem-suggestions {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.mem-suggestions__stamp {
  color: var(--fg-faint);
  font-size: var(--font-caption);
}
.mem-suggestion-settings {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 12px;
  padding: 10px 11px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--bg-elev) 58%, transparent);
}
.mem-suggestion-settings > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}
.mem-suggestion-settings strong {
  color: var(--fg);
  font-size: var(--font-control-small);
  font-weight: 700;
  line-height: 1.35;
}
.mem-suggestion-settings span {
  color: var(--fg-dim);
  font-size: var(--font-caption);
  line-height: 1.45;
}
.mem-suggestion-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.mem-suggestion-group__title {
  color: var(--fg);
  font-size: var(--font-control-small);
  font-weight: 700;
}
.mem-suggestion {
  --mem-type-color: var(--accent);
}
.mem-suggestion--skill {
  --mem-type-color: #2dd4bf;
}
.mem-suggestion--skill .mem-fact__summary {
  align-items: flex-start;
}
.mem-suggestion__body {
  padding: 9px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--bg-elev) 70%, transparent);
  color: var(--fg-dim);
  font-size: var(--text-sm);
  line-height: 1.5;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.mem-suggestion__body--code {
  margin: 0;
  max-height: 280px;
  overflow: auto;
  font-family: var(--mono);
}
.mem-suggestion__reason {
  margin-top: 8px;
  color: var(--fg-dim);
  font-size: var(--font-caption);
}
.mem-suggestion__evidence {
  margin: 8px 0 0;
  padding-left: 18px;
  color: var(--fg-faint);
  font-size: var(--font-caption);
  line-height: 1.45;
}
.mem-suggestion__accepted {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--success, #2aa36b);
  font-size: var(--font-caption);
  font-weight: 650;
}
.mem-link {
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  color: var(--accent, #6aa3ff);
  text-decoration: underline dotted;
}
.mem-link--dead {
  color: var(--danger, #d66);
  cursor: help;
  text-decoration: line-through;
}
.mem-hint--inline {
  margin-top: 0;
  font-family: inherit;
  line-height: 1.35;
}
.btn--small {
  height: var(--button-small-height);
  padding: 0 10px;
  font-size: var(--font-control-small);
}
/* 任务578：btn--sm（5 处）与 btn--small 是两个独立变体，不互为别名——
   sm 更矮更窄，用于对话框头部/横幅里的紧凑动作。 */
.btn--sm {
  height: calc(var(--button-small-height) - 4px);
  padding: 0 8px;
  font-size: var(--font-control-small);
}
/* 任务578：btn--icon（ThemeGallery 关闭键）方形图标规格，.btn 的 flex 居中承接图标。 */
.btn--icon {
  width: var(--button-icon-size);
  min-width: var(--button-icon-size);
  height: var(--button-icon-size);
  padding: 0;
}
.badge {
  flex-shrink: 0;
  font-size: var(--text-2xs);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 2px 7px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border);
  background: var(--bg-soft);
  color: var(--fg-dim);
}
.badge--user {
  color: var(--accent);
  border-color: var(--accent-soft);
}
.badge--global {
  color: var(--accent);
  border-color: var(--accent-soft);
}
.badge--project {
  color: var(--ok);
  border-color: rgba(116, 184, 122, 0.4);
}
.badge--local {
  color: var(--warn);
  border-color: rgba(217, 164, 65, 0.4);
}
.badge--ancestor {
  color: var(--fg-faint);
}
.badge--feedback {
  color: var(--warn);
  border-color: rgba(217, 164, 65, 0.4);
}
.badge--reference {
  color: var(--accent);
  border-color: var(--accent-soft);
}

.customize {
  position: relative;
  display: inline-flex;
}
.menu-backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--z-menu-backdrop);
}
.menu {
  position: absolute;
  top: 32px;
  right: 0;
  z-index: var(--z-menu);
  min-width: 160px;
  padding: 5px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  display: flex;
  flex-direction: column;
  gap: 2px;
  animation: drawer-in 0.12s ease;
}
.menu__item {
  --wails-draggable: no-drag;
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 7px 10px;
  border: none;
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  font-size: var(--text-md);
  text-align: left;
  border-radius: var(--radius-sm);
}
.menu__item:hover {
  background: var(--bg-soft);
  color: var(--fg);
}
.menu__item:disabled {
  opacity: 0.4;
  cursor: default;
}

.cap-row {
  width: 100%;
  display: flex;
  gap: 9px;
  align-items: flex-start;
  padding: 8px 0;
}
.cap-server-entry {
  border-bottom: 1px solid var(--border-soft);
}
.cap-row--disabled .cap-dot {
  background: var(--fg-faint);
  opacity: 0.72;
}
.cap-row--disabled .cap-row__name,
.cap-row--disabled .cap-row__sub,
.cap-server-entry--disabled .cap-tool {
  color: var(--fg-faint);
}
.cap-disclosure {
  --wails-draggable: no-drag;
  flex-shrink: 0;
  width: 14px;
  height: 18px;
  border: 0;
  padding: 0;
  margin-top: 0;
  color: var(--fg-faint);
  background: transparent;
  font-size: 16px;
  line-height: 18px;
}
.cap-disclosure:disabled {
  cursor: default;
  opacity: 0;
}
.cap-tool-list {
  display: grid;
  grid-template-columns: minmax(82px, max-content) minmax(0, 1fr);
  column-gap: 12px;
  row-gap: 5px;
  margin: 0 0 9px 31px;
  padding: 7px 0 2px 12px;
  border-left: 1px solid var(--border-soft);
}
.cap-tool-list__title {
  grid-column: 1 / -1;
  margin-bottom: 1px;
  color: var(--fg-faint);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 0.04em;
  line-height: 1.2;
  text-transform: uppercase;
}
.cap-tool {
  display: contents;
}
.cap-tool__name {
  color: var(--fg);
  font-family: var(--mono);
  font-size: var(--text-xs);
  line-height: 1.45;
  overflow-wrap: anywhere;
}
.cap-tool__desc {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  color: var(--fg-dim);
  font-size: var(--text-xs);
  line-height: 1.45;
  overflow-wrap: anywhere;
}
.cap-tool-hint {
  display: inline-flex;
  align-items: center;
  min-height: 17px;
  padding: 0 5px;
  border: 1px solid color-mix(in srgb, var(--accent) 26%, transparent);
  border-radius: var(--radius-pill);
  color: var(--fg-dim);
  background: color-mix(in srgb, var(--accent) 6%, transparent);
  font-size: 10px;
  line-height: 1;
  white-space: nowrap;
}
.cap-tool-hint--error {
  gap: 3px;
  border-color: color-mix(in srgb, var(--warn) 34%, transparent);
  color: var(--warn);
  background: color-mix(in srgb, var(--warn) 8%, transparent);
}
.cap-tool--unavailable .cap-tool__name,
.cap-tool--unavailable .cap-tool__desc {
  color: var(--fg-faint);
}
.cap-server-entry--disabled .cap-tool__name,
.cap-server-entry--disabled .cap-tool__desc {
  color: var(--fg-faint);
}
.cap-server-details {
  margin: 0 0 10px 31px;
  padding: 7px 0 2px 12px;
  border-left: 1px solid var(--border-soft);
}
.cap-update-notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
  padding: 9px 11px;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border));
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--accent) 7%, var(--bg-soft));
}
.cap-update-notice--error {
  border-color: color-mix(in srgb, var(--err) 28%, var(--border));
  background: color-mix(in srgb, var(--err) 8%, var(--bg-soft));
}
.cap-update-notice__text {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.cap-update-notice__title {
  color: var(--fg);
  font-size: var(--text-sm);
  font-weight: 700;
  line-height: 1.25;
}
.cap-update-notice__summary {
  color: var(--fg-dim);
  font-size: 11.5px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}
.cap-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 12px;
}
.cap-detail {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.cap-detail--wide {
  grid-column: 1 / -1;
}
.cap-detail--select .mem-select {
  height: 30px;
  font-size: var(--text-sm);
}
.cap-detail__label {
  color: var(--fg-faint);
  font-size: 10px;
  font-weight: 650;
  line-height: 1.2;
  text-transform: uppercase;
}
.cap-detail__value,
.cap-detail__code {
  min-width: 0;
  color: var(--fg-dim);
  font-size: 11.5px;
  line-height: 1.35;
}
.cap-detail__code {
  font-family: var(--mono);
  overflow-wrap: anywhere;
}
.cap-detail-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 10px;
}
.cap-confirm-hint {
  flex-basis: 100%;
  color: var(--fg-faint);
  font-size: var(--text-xs);
  line-height: 1.35;
}
.cap-connection-mode {
  min-width: 0;
  border: 0;
  padding: 0;
  margin: 0;
}
.cap-connection-options {
  margin-top: 4px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg);
}
.cap-connection-option {
  --wails-draggable: no-drag;
  display: grid;
  grid-template-columns: 17px minmax(0, 1fr);
  gap: 9px;
  padding: 8px 10px;
  border-top: 1px solid var(--border-soft);
}
.cap-connection-option:first-child {
  border-top: 0;
}
.cap-connection-option:hover {
  background: var(--bg-soft);
}
.cap-connection-option--selected {
  box-shadow: inset 3px 0 0 var(--ok);
  background: var(--bg-soft);
}
