.subagents-field-error {
  margin-top: -4px;
  color: var(--err);
  font-size: var(--text-xs);
  line-height: 1.4;
}
.subagents-hint {
  color: var(--fg-faint);
  font-size: var(--text-xs);
  line-height: 1.4;
}
.subagents-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 6px;
}
.subagents-toolbar .mem-input {
  min-width: 0;
}
.subagents-profile-group {
  display: grid;
  gap: 10px;
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: transparent;
}
.subagents-profile-group .cap-skills-head {
  margin: 0;
  padding: 0;
  border: 0;
}
.subagents-profile-group .cap-skills-head__title {
  margin: 0;
}
.subagents-builtin-card {
  background: color-mix(in srgb, var(--bg-soft) 38%, transparent);
}
.subagents-builtin-overrides {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr)) 152px;
  align-items: end;
  gap: 8px;
  margin: 8px 0 0 33px;
}
.subagents-builtin-overrides__field {
  display: grid;
  min-width: 0;
  gap: 4px;
}
.subagents-builtin-overrides__field-label {
  color: var(--fg-faint);
  font-size: 10.5px;
  font-weight: 650;
  line-height: 1.3;
}
.subagents-builtin-overrides__field .settings-model-picker,
.subagents-builtin-overrides__field .mem-select {
