  color: var(--fg-faint);
  white-space: nowrap;
  flex-shrink: 0;
}

/* 百分比值，与右侧步进控件同排显示 */
.zoom-slider__value {
  font-size: var(--font-control-small);
  font-weight: 700;
  color: var(--accent);
  line-height: 1;
  text-align: left;
  min-width: 42px;
}

.zoom-stepper {
  display: inline-flex;
  align-items: center;
  flex: none;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
}

.zoom-stepper__btn,
.zoom-stepper__reset {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  height: 25px;
  border: 0;
  border-right: 1px solid var(--border);
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  font-size: var(--font-control-small);
  line-height: 1;
}

.zoom-stepper__btn {
  width: 28px;
}

.zoom-stepper__reset {
  min-width: 58px;
  padding: 0 8px;
  font-weight: 650;
}

.zoom-stepper__btn:last-child {
  border-right: 0;
}

.zoom-stepper__btn:not(:disabled):hover,
.zoom-stepper__reset:not(:disabled):hover {
  background: var(--accent-soft);
  color: var(--accent);
}

.zoom-stepper__btn:disabled,
.zoom-stepper__reset:disabled {
  color: var(--fg-faint);
  opacity: .55;
  cursor: default;
}

/* 让 label 在 settings-field 网格中靠下对齐 */
.settings-field:has(.zoom-slider-wrap) {
  align-items: end;
}

/* 轨道容器 */
.slider-track {
  position: relative;
  flex: 1;
  width: 100%;
  height: 20px;
  cursor: pointer;
  user-select: none;
  touch-action: none;
}

/* 轨道背景 */
.slider-track__bg {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  border-radius: var(--radius-md);
  background: var(--bg-elev-2);
  overflow: hidden;
}

/* 填充 — 两端圆角，右侧半圆收口 */
.slider-track__fill {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  border-radius: var(--radius-md);
  background: var(--accent);
  max-width: 100%;  /* 防止超出轨道 */
}

/* 胶囊滑块 — 外包 1px 主题色边框 */
.slider-thumb {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 26px;
  height: 16px;
  pointer-events: none;
  z-index: var(--z-local-raised);
  background: #fff;
  border: 1px solid var(--accent);
  border-radius: var(--radius-md);
  box-sizing: border-box;
}

/* slider-thumb is now a single element; child segments were removed. */

/* 透明 input range — 事件捕获 */
.slider-track input[type="range"] {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
  z-index: var(--z-local-handle);
  margin: 0;
}
