  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  width: 100%;
}
.bot-list-input {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.bot-list-input > span {
  color: var(--fg-dim);
  font-size: var(--text-2xs);
  font-weight: 650;
}
.bot-list-input__textarea {
  min-height: 88px;
  max-height: 180px;
  resize: vertical;
}
.set-row--stack {
  align-items: flex-start;
  flex-direction: column;
}
.theme-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 190px), 1fr));
  gap: 10px;
  width: 100%;
}
.theme-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-width: 0;
  overflow: hidden;
  border: 1.5px solid var(--border);
  border-radius: 12px; /* 833-radius-wl:large */
  background: var(--surface, var(--bg));
  color: var(--fg);
  font: inherit;
  text-align: left;
  padding: 12px 13px;
  cursor: pointer;
  transition: border-color 0.13s ease, transform 0.13s cubic-bezier(0.34, 1.4, 0.5, 1), box-shadow 0.13s ease;
}
.theme-card:hover {
  border-color: var(--button-border-hover);
  transform: translateY(-2px);
}
.theme-card--on {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.theme-card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}
.theme-card--on .theme-card__head {
  padding-right: 24px;
}
.theme-card__name {
  flex: 1 1 120px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 13.5px;
  font-weight: 700;
  white-space: nowrap;
}
.theme-card__zh {
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--fg-dim);
  margin-left: 2px;
}
.theme-card__tag {
  flex: 0 1 auto;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--fg-dim);
  background: var(--bg);
  border: 1px solid var(--border);
  padding: 2px 8px;
  border-radius: var(--radius-pill);
  white-space: nowrap;
}
.theme-card__swatches {
  display: flex;
  gap: 6px;
  min-width: 0;
}
.theme-card__swatch {
  flex: 1;
  min-width: 28px;
  height: 30px;
  border-radius: var(--radius-md);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fg-faint) 30%, transparent);
}
.theme-card__desc {
  display: -webkit-box;
  overflow: hidden;
  font-size: 11.5px;
  line-height: 1.55;
  color: var(--fg-dim);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}
.theme-card__check {
  position: absolute;
  top: 11px;
  right: 11px;
  display: grid;
  place-items: center;
  width: 19px;
  height: 19px;
  border-radius: var(--radius-pill);
  background: var(--accent);
  color: var(--accent-fg);
  opacity: 0;
  transform: scale(0.6);
  transition: opacity 0.13s ease, transform 0.13s cubic-bezier(0.34, 1.4, 0.5, 1);
}
.theme-card--on .theme-card__check {
  opacity: 1;
  transform: scale(1);
}
/* The check badge owns the selected state; the note chip remains inside the card layout. */
.theme-card--on .theme-card__tag {
  margin-right: 24px;
}

/* Per-direction preview swatches (dark variant is the default). */
.theme-card__swatches[data-theme-style-card="graphite"] .theme-card__swatch--bg { background: #0c0d10; }
