}
.rt-notice__close:hover {
  background: color-mix(in srgb, var(--fg) 8%, transparent);
  color: var(--fg);
}
.rt-notice__intro {
  margin: 0;
  color: var(--fg-dim);
  font-size: var(--text-sm);
  line-height: 1.45;
}
.rt-notice__body {
  max-height: 120px;
  margin: 0;
  padding: 9px 10px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--fg-dim);
  font-family: var(--mono, monospace);
  font-size: 11.5px;
  line-height: 1.45;
  overflow: auto;
  white-space: pre-wrap;
  word-break: break-word;
}
.rt-notice__actions {
  display: flex;
  flex-wrap: wrap;
