  padding-bottom: 6px;
}

.project-tree__skeleton-bar {
  display: block;
  height: 12px;
  width: 72%;
  border-radius: var(--radius-sm);
  background: var(--fg-faint);
  opacity: 0.16;
  animation: pulse 1.2s ease-in-out infinite;
}

.project-tree__skeleton-bar--short {
  width: 48%;
}

.project-tree__header-actions .project-tree__add-project:focus-visible,
.project-tree__header-actions .project-tree__collapse-all:focus-visible,
.project-tree__header-actions .project-tree__header-action-btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.project-tree__list {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0 var(--project-tree-edge-gap) 0 8px;
  scrollbar-width: none;
}

.project-tree__list::-webkit-scrollbar {
  display: none;
}

.project-tree__folder {
  position: relative;
  height: 34px;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0;
  margin-right: 0;
  border-radius: var(--project-tree-row-radius);
  color: var(--fg-dim);
  font-size: 13.5px;
}

.project-tree__folder:hover {
  background: var(--sidebar-hover);
}

.project-tree__folder--active,
.project-tree__folder--menu-open {
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 5%, transparent);
  color: var(--fg);
}

.project-tree__folder--menu-open,
.project-tree__folder--active:hover {
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 5%, var(--sidebar-hover));
}

.project-tree__folder--dragging {
  cursor: grabbing;
  opacity: 0.55;
}

/* tl 1225: the project-row placement hint reuses the topic row's mechanism
   (.project-tree__topic--drop-*): an inset 2px accent bar on the edge nearest
   the insertion point. The old outset hairlines (::before/::after at
   top/bottom: -2px) painted OUTSIDE the row box, where the per-row
   `contain: layout` stacking context lets the neighbouring wrapper paint over
   them and the scroll container clips them on the first/last row — the target
   feedback the user compared against topic drags never read as a hint.
   Inset bars live inside the row: they can neither be covered nor clipped. */
.project-tree__folder--drop-before {
  box-shadow: inset 0 2px 0 var(--accent);
}

.project-tree__folder--drop-after {
  box-shadow: inset 0 -2px 0 var(--accent);
}

.project-tree__folder--editing {
  padding-right: 8px;
}

.project-tree__folder-main {
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 7px;
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: inherit;
  font: inherit;
  padding-right: 0;
  text-align: left;
  font-weight: 560;
}

.project-tree__folder--global,
.project-tree__topic--global {
  --project-accent: var(--project-tree-global-accent);
}

.project-tree__folder-color {
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: var(--radius-pill);
  background: var(--project-accent, var(--accent));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--project-accent, var(--accent)) 14%, transparent);
}

.project-tree__folder-main:focus-visible {
  outline: 2px solid var(--accent-soft);
  outline-offset: -2px;
}

.project-tree__folder--draggable {
  cursor: grab;
}

.project-tree__folder--draggable .project-tree__folder-main {
  cursor: inherit;
}

.project-tree__folder--draggable:active {
  cursor: grabbing;
}

.project-tree__folder-toggle {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: none;
  background: transparent;
  color: inherit;
  padding: 0;
}

.project-tree__folder-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-tree__folder-input {
  --wails-draggable: no-drag;
  flex: 1 1 auto;
  min-width: 0;
  height: 26px;
  border: 1px solid var(--accent-soft);
  border-radius: var(--radius-md);
  background: var(--bg-elev);
  color: var(--fg);
  font: inherit;
  font-size: var(--text-md);
  padding: 0 8px;
  outline: none;
}

.project-tree__new-topic {
  opacity: 0.62;
}

.project-tree__new-topic:hover {
  background: var(--button-bg);
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border-soft));
  color: var(--fg);
}

.project-tree__new-topic--active {
  opacity: 1;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border-soft));
}

.project-tree__topic {
  position: relative;
  width: auto;
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 4px;
  padding-top: 0;
  padding-bottom: 0;
  padding-left: 0 !important;
  margin-left: 22px;
  margin-right: var(--project-tree-action-column);
  padding-right: 8px;
  border-radius: var(--project-tree-row-radius);
  color: var(--fg-dim);
  font-size: var(--text-md);
  cursor: default;
}

.project-tree__topic--has-meta {
  min-height: 48px;
}

.project-tree__topic--active {
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 10%, var(--sidebar-hover));
  border-radius: 0;
  color: var(--fg);
}

.project-tree__topic--active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 88%, #ff9d22);
  pointer-events: none;
}

.project-tree__topic--menu-open {
  background: color-mix(in srgb, var(--accent) 6%, var(--sidebar-hover));
  color: var(--fg);
}

.project-tree__topic:hover {
  background: var(--list-row-hover-bg);
}

.project-tree__topic--remote-static:hover {
  background: transparent;
}

.project-tree__topic--active:hover {
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 10%, var(--sidebar-hover));
}

.project-tree__topic-main {
  --wails-draggable: no-drag;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 0;
  border: none;
  border-radius: inherit;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
}

/* Task 827 ③: the session row's icon-column placeholder. Same fixed column
   width as every row, plus the shared 7px icon-to-label gap, so a session
   title starts exactly one indent step right of its container row's title.
   The status dot keeps its established home in the side area — this column
   only holds the grid. */
.project-tree__topic-lead {
  flex: 0 0 var(--project-tree-icon-col);
  width: var(--project-tree-icon-col);
  margin-right: 7px;
}
/* Workbench and creation pin their own topic paddings; the grid column is a
   classic-tree geometry and must not add width there. */
.sidebar--workbench .project-tree__topic-lead,
.app--creation .project-tree__topic-lead,
:root[data-theme-style] .app--creation .project-tree__topic-lead {
