}

.project-tree__topic-im {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 74px;
  height: 17px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 0 5px;
  border-radius: var(--radius-sm);
