  color: var(--fg-faint);
}

.project-tree__topic-status--awaiting_delivery {
  max-width: 80px;
  background: color-mix(in srgb, var(--warn) 13%, transparent);
  color: color-mix(in srgb, var(--warn) 82%, var(--fg));
}

.project-tree__topic-status--error {
  background: color-mix(in srgb, var(--err) 12%, transparent);
  color: color-mix(in srgb, var(--err) 84%, var(--fg));
}

.project-tree__topic-meta {
  max-width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg-faint);
  font-size: var(--text-xs);
  line-height: 1.2;
}

.project-tree__topic--session .project-tree__topic-label {
  color: var(--fg-dim);
}

.project-tree__topic-main:focus-visible {
  outline: 2px solid var(--accent-soft);
  outline-offset: -2px;
}

.project-tree__topic--editing {
  padding-right: 8px;
}

.project-tree__topic-input {
  --wails-draggable: no-drag;
  flex: 1 1 auto;
  min-width: 0;
  align-self: stretch;
  border: 1px solid var(--accent-soft);
  border-radius: var(--radius-md);
  background: var(--bg-elev);
  color: var(--fg);
  font: inherit;
  font-size: var(--text-md);
  padding: 0 8px;
  outline: none;
}

.project-tree__children {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transform: translateY(-4px);
  pointer-events: none;
  transition: opacity 0.16s ease, transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
}

.project-tree__children--expanded {
  grid-template-rows: 1fr;
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

.project-tree__children-inner {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

/* Project tree: icon stack holds folder open/closed icon.
   Task 827 ③: the stack is the row's uniform icon column — the same
   --project-tree-icon-col width on every row, so titles start on one grid. */
.project-tree__icon-stack {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--project-tree-icon-col);
  height: 14px;
  flex: 0 0 auto;
  position: relative;
}
.project-tree__icon-stack > .project-tree__folder-icon {
  width: 14px;
  height: 14px;
  color: var(--fg-faint);
}
/* Task 827 ③: the project color dot moved inside the icon column (bottom-
   right overlay) so the label starts right after the column — the folder
   glyph and the dot together are the column's content ("folder + status dot"). */
.project-tree__icon-stack .project-tree__folder-color {
  position: absolute;
  right: -2px;
  bottom: -1px;
}

/* Project name de-emphasis: empty projects (no children) use lighter color */
:root[data-theme-style] .project-tree__folder-label--empty {
  color: var(--fg-faint);
}
:root[data-theme-style] .project-tree__folder-label:not(.project-tree__folder-label--empty) {
  color: color-mix(in srgb, var(--fg-dim) 58%, var(--fg-faint) 42%);
}
:root[data-theme-style] .project-tree__topic-label {
  color: var(--fg);
  font-weight: 500;
}

/* Extra spacing after expanded project section */
/* Extra spacing only after expanded project that actually has children */
.project-tree__project-wrapper {
  contain: layout;
}
.project-tree__project-wrapper:has(.project-tree__folder-main[aria-expanded="true"]):has(.project-tree__children) {
  margin-bottom: 6px;
}

/* Topic action icons (pin, archive): clean, no background, no border */
:root[data-theme-style] .sidebar--workbench .project-tree__topic-action,
:root[data-theme-style] .app--classic .project-tree__topic-action {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
}
:root[data-theme-style] .sidebar--workbench .project-tree__topic-action:hover,
:root[data-theme-style] .app--classic .project-tree__topic-action:hover {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  transform: none;
}

/* Remove right-side slide animations on topic hover */
:root[data-theme-style] .sidebar--workbench .project-tree__topic-actions,
:root[data-theme-style] .app--classic .project-tree__topic-actions {
  transform: translateY(-50%) translateX(0);
}
:root[data-theme-style] .sidebar--workbench .project-tree__topic:hover .project-tree__topic-actions,
:root[data-theme-style] .sidebar--workbench .project-tree__topic:focus-within .project-tree__topic-actions,
:root[data-theme-style] .sidebar--workbench .project-tree__topic--menu-open .project-tree__topic-actions,
:root[data-theme-style] .app--classic .project-tree__topic:hover .project-tree__topic-actions,
:root[data-theme-style] .app--classic .project-tree__topic:focus-within .project-tree__topic-actions,
:root[data-theme-style] .app--classic .project-tree__topic--menu-open .project-tree__topic-actions {
  transform: translateY(-50%) translateX(0);
}
:root[data-theme-style] .sidebar--workbench .project-tree__topic:hover .project-tree__topic-side,
:root[data-theme-style] .sidebar--workbench .project-tree__topic:focus-within .project-tree__topic-side,
:root[data-theme-style] .sidebar--workbench .project-tree__topic--menu-open .project-tree__topic-side,
:root[data-theme-style] .app--classic .project-tree__topic:hover .project-tree__topic-side,
:root[data-theme-style] .app--classic .project-tree__topic:focus-within .project-tree__topic-side,
:root[data-theme-style] .app--classic .project-tree__topic--menu-open .project-tree__topic-side {
  transform: translateX(0);
}

@media (prefers-reduced-motion: reduce) {
  .project-tree__children {
    transition: none;
  }

  .project-tree__children {
    transform: none;
  }
}

.context-menu {
  --wails-draggable: no-drag;
  position: fixed;
  z-index: var(--z-overlay-backdrop);
  max-height: calc(100vh - 16px);
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 5px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.36);
  transform-origin: top left;
  animation: menu-pop-in var(--dur-base) var(--ease-out) both;
}
@keyframes menu-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--motion-pop-scale)) translateY(calc(-0.5 * var(--motion-rise)));
  }
}

/* tl 1168: the submenu flyout — a second fixed panel anchored beside its
   trigger row (hover to open, tap for touch, →/← for keyboard). It shares the
   .context-menu chrome (border/shadow/scroll); only the width cap differs, so
   a long group title never pushes the panel past the viewport edge. */
.context-menu--flyout {
  max-width: min(320px, calc(100vw - 16px));
}

.context-menu__item {
  width: 100%;
  min-height: 30px;
  display: flex;
  align-items: center;
  gap: 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  font-size: var(--text-sm);
  text-align: left;
  padding: 0 8px;
}

.context-menu__item:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.context-menu__item--section:disabled {
  cursor: default;
  opacity: 1;
  color: var(--fg-faint);
  font-size: var(--text-xs);
  font-weight: 650;
}

.context-menu__item > span {
  flex: 1 1 auto;
  min-width: 0;
}

.context-menu__shortcut {
  margin-left: 16px;
  color: var(--fg-faint);
  font-size: var(--text-xs);
  font-family: inherit;
  pointer-events: none;
}

.context-menu__item:hover .context-menu__shortcut,
.context-menu__item:focus-visible .context-menu__shortcut {
  color: var(--fg);
}

/* tl 1103: "open with ▸" marks the currently preferred opener — same pattern
   as the topicbar more-menu check (accent, pushed to the row end). */
.context-menu__item--checked {
  color: var(--fg);
}

.context-menu__check {
  margin-left: auto;
  color: var(--accent);
  pointer-events: none;
}

/* Task 720: submenu rows carry the expand chevron; the first label span keeps
   flex:1, so the arrow only needs to stop growing and sit at the row end. */
.context-menu__item--submenu > .context-menu__submenu-arrow {
  flex: 0 0 auto;
  color: var(--fg-faint);
  font-size: 10px;
  pointer-events: none;
}

.context-menu__item:not(:disabled):hover > .context-menu__submenu-arrow,
.context-menu__item:not(:disabled):focus-visible > .context-menu__submenu-arrow {
  color: var(--fg);
}

/* Task 720: leaves of an expanded submenu row indent one step inside the same
   menu (the section expands in place — the menu itself scrolls). */
.context-menu__item--nested {
  padding-left: 22px;
}

.context-menu--composer-input .context-menu__item {
  padding: 0 12px;
}

.context-menu__label-with-check {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
}

.context-menu__label-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.context-menu__check {
  flex: 0 0 auto;
  margin-left: auto;
  color: var(--fg);
}

.context-menu__item:not(:disabled):hover,
.context-menu__item:not(:disabled):focus-visible {
  background: var(--sidebar-hover);
  color: var(--fg);
  outline: none;
}

.context-menu__separator {
  height: 1px;
  margin: 5px 4px;
  background: var(--border-soft);
}

.context-menu__item--danger:not(:disabled):hover,
.context-menu__item--danger:not(:disabled):focus-visible {
  color: #e5534b !important;
}

.transcript-selection-action {
  --wails-draggable: no-drag;
  position: fixed;
  z-index: var(--z-floating-menu);
  max-width: calc(100vw - 16px);
  padding: 4px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--bg-elev) 94%, transparent);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(12px);
  animation: menu-pop-in var(--dur-base) var(--ease-out) both;
}

.transcript-selection-action button {
  display: inline-flex;
  min-width: 0;
  height: 32px;
  align-items: center;
  gap: 7px;
  padding: 0 9px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg);
  font: inherit;
  font-size: var(--text-sm);
  white-space: nowrap;
}

.transcript-selection-action button:not(:disabled):hover,
.transcript-selection-action button:not(:disabled):focus-visible {
  background: var(--sidebar-hover);
  outline: none;
}

.transcript-selection-action button:not(:disabled):focus-visible {
  box-shadow: var(--focus-ring);
}

.transcript-selection-action svg {
  flex: 0 0 auto;
  color: var(--accent);
}

.transcript-selection-action kbd {
  flex: 0 0 auto;
  margin-left: 5px;
  color: var(--fg-faint);
  font: inherit;
  font-size: 10.5px;
}

@media (prefers-reduced-motion: reduce) {
  .transcript-selection-action {
    animation: none;
  }
}

/*
 * Task 525: the quick-action result card (task 369) portals to <body> after
 * #root. Without position:fixed the inline left/top are inert and the card
 * lands below the viewport, where body{overflow:hidden} clips it — rendered
 * in the DOM but never visible. Anchor it at the selection point like the
 * action toolbar above, and scroll long results inside the card.
 */
.transcript-selection-result-card {
  --wails-draggable: no-drag;
  position: fixed;
  z-index: var(--z-floating-menu);
  display: flex;
  flex-direction: column;
  width: min(420px, calc(100vw - 16px));
  max-height: min(320px, calc(100vh - 16px));
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--bg-elev) 94%, transparent);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(12px);
  animation: menu-pop-in var(--dur-base) var(--ease-out) both;
}

.transcript-selection-result-card__head {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 4px;
  margin-bottom: 6px;
}

.transcript-selection-result-card__title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-size: var(--text-sm);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.transcript-selection-result-card__pin,
.transcript-selection-result-card__close {
  display: inline-flex;
  flex: 0 0 auto;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-faint);
  cursor: pointer;
  font: inherit;
}

.transcript-selection-result-card__pin:hover,
.transcript-selection-result-card__close:hover,
.transcript-selection-result-card__pin:focus-visible,
.transcript-selection-result-card__close:focus-visible {
  background: var(--sidebar-hover);
  outline: none;
}

.transcript-selection-result-card__pin:focus-visible,
.transcript-selection-result-card__close:focus-visible {
  box-shadow: var(--focus-ring);
}

.transcript-selection-result-card__pin[aria-pressed="true"] {
  color: var(--accent);
}

.transcript-selection-result-card__body {
  flex: 1 1 auto;
  min-height: 1.5em;
  overflow-y: auto;
  color: var(--fg);
  font-size: 12.5px;
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.transcript-selection-result-card__body[data-state="loading"] {
  color: var(--fg-faint);
}

.transcript-selection-result-card__body[data-state="error"] {
  color: var(--danger);
}

@media (prefers-reduced-motion: reduce) {
  .transcript-selection-result-card {
    animation: none;
  }
}

.project-tree__color-option {
  min-width: 0;
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: 8px;
}

.project-tree__color-swatch {
  flex: 0 0 auto;
  width: 12px;
  height: 12px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-pill);
  background: var(--project-accent, var(--accent));
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--bg-elev) 72%, transparent);
}

.project-tree__color-check {
  margin-left: auto;
  color: var(--project-accent, var(--accent));
}

.project-tree__empty {
  padding: 10px 12px;
  color: var(--fg-faint);
  font-size: var(--text-md);
}

/* Task 403: first-read loading row. It takes the exact spot where rows will
   appear, so the sidebar never paints the "no projects yet" empty state while
   the first project-tree read is still in flight. */
.project-tree__loading {
  padding: 10px 12px;
  color: var(--fg-faint);
  font-size: var(--text-md);
  font-style: italic;
}

.project-tree__catalog-progress {
	display: flex;
	align-items: center;
	gap: 8px;
  padding: 4px 10px 6px;
  color: var(--fg-faint);
  font-size: var(--text-xs);
  line-height: 1.35;
}

.project-tree__empty--subtle {
  padding: 8px 12px;
  font-size: var(--text-sm);
}

.project-tree__empty-state {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 2px 0 0;
}

.project-tree__empty-primary {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 32px;
  margin: 0 8px;
  border: 1px solid color-mix(in srgb, var(--accent) 45%, var(--border));
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--accent) 14%, var(--bg-elev));
  color: var(--accent-strong);
  font: inherit;
  font-size: 12.5px;
  font-weight: 620;
}

.project-tree__empty-primary:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 21%, var(--bg-elev));
  color: var(--fg);
}

.project-tree__empty-primary:disabled {
  cursor: default;
  opacity: 0.45;
}

.project-tree__empty-secondary {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 32px;
  margin: 0 8px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  font-size: 12.5px;
  font-weight: 560;
}

.project-tree__empty-secondary:hover:not(:disabled) {
  background: var(--sidebar-hover);
  color: var(--fg);
}

.project-tree__empty-secondary:disabled {
  cursor: default;
  opacity: 0.45;
}

.context-inspector,
.workbench-dock {
  grid-row: 2;
  grid-column: 3;
  min-width: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  /* Unify the dock surface with the chat pane; inner panels inherit this. */
  --workspace-files-bg: var(--chat-bg);
  --workspace-preview-bg: var(--chat-bg);
  background: var(--chat-bg);
  border-left: 0px solid var(--border-soft);
  overflow: hidden;
}

.workbench-dock {
  justify-self: stretch;
  width: 100%;
  max-width: none;
  container-type: inline-size;
}

.layout--workspace-maximized .workbench-dock {
  width: auto;
  max-width: none;
}

@media (prefers-reduced-motion: reduce) {
  .layout {
    transition: none;
  }
}

.workbench-dock__tools {
  flex: 0 0 auto;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  padding: 7px 10px 3px;
  border-bottom: 1px solid transparent;
  --wails-draggable: drag;
}

/* Dock collapse/expand toggle pinned to the top-right corner of the window.
/* Dock collapse/expand toggle pinned to the top-right corner of the window.
   Fixed position keeps it at the same spot whether the dock is open (it
   overlaps the dock's tools row) or closed (it sits on the topic bar's
   right edge) — the icon never shifts. */
.app__dock-toggle {
  position: fixed;
  top: 0;
  right: 12px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: var(--z-app-chrome);
  --wails-draggable: no-drag;
  pointer-events: auto;
}
.app__dock-toggle .topicbar__chrome-btn {
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
}
.app__dock-toggle .topicbar__chrome-btn:hover:not(:disabled),
.app__dock-toggle .topicbar__chrome-btn:focus-visible:not(:disabled) {
  background: var(--button-bg) !important;
  color: var(--fg) !important;
}
.app__dock-toggle .topicbar__chrome-btn--workspace:not(:hover):not(:focus-visible) {
  color: var(--fg-faint);
}

.workbench-dock__tabs {
  --wails-draggable: no-drag;
  flex: 0 1 auto;
  width: max-content;
  max-width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 3px;
  border-radius: var(--radius-md);
  background: var(--bg);
  border: 1px solid var(--border-soft);
}

.workbench-dock__tab {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  flex: 0 1 auto;
  min-width: 30px;
  max-width: 118px;
  height: 24px;
  padding: 0 8px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-faint);
  font: inherit;
  font-size: 11.5px;
  font-weight: 560;
}

.workbench-dock__tab svg {
  flex: 0 0 auto;
}

.workbench-dock__tab-label {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.workbench-dock__tab:hover {
  color: var(--fg-dim);
}

.workbench-dock__tab--active {
  background: var(--bg-elev);
  color: var(--fg);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.16);
}

@container (max-width: 520px) {
  .workbench-dock__tabs {
    width: 100%;
  }

  .workbench-dock__tab {
    flex: 1 1 0;
    max-width: none;
  }
}

/* tl1129 返修（用户 20261025 拍板：最小宽度基线保 2 字 tab 可读）：删除原
   @container (max-width: 340px) 的 icon-only 段（tab 压成 30px、label 隐藏）。
   该段是 2026-06（c80ba8ad76）在 dock 正常宽度 ≥280 时代加的极窄兜底；
   tl1108 引入 246 窄态 rail 后该段成为日常态——246 rail 下「概览/文件/改动」
   两字标签永远消失。dock clamp 下限 246（creation 252），≤340 区间只可能是
   窄态 rail 本身；删除后由上方 520 断点均分接管，默认 3-4 个两字 tab 在 246
   下完整显示，label 的 ellipsis 基础规则保留作极值兜底。 */

/* Task 259: wrap mode — only while the todo-sidebar experiment is on. Tabs keep
   a fixed quarter-width cell so the default dock width fits exactly four per
   row and a fifth wraps to the next line; hidden tabs just leave gaps. The
   two-class specificity also wins over the container queries above. */
.workbench-dock__tools--wrap {
  height: auto;
  min-height: 42px;
  align-items: flex-start;
}

.workbench-dock__tabs--wrap {
  flex-wrap: wrap;
  width: 100%;
  justify-content: flex-start;
}

/* Task 452: a bare 25% cell ignores the strip's row gap (3px) — 4×25% + 3
   gaps never fits, so only three tabs landed per row. The cell is a quarter
   minus the gap share (exact 2.25px, rounded up to 2.5px so sub-pixel
   rounding can never push the fourth tab to the next line). */
.workbench-dock__tabs--wrap .workbench-dock__tab {
  flex: 0 0 calc(25% - 2.5px);
  min-width: 0;
  max-width: calc(25% - 2.5px);
  box-sizing: border-box;
}

.workbench-dock__todo {
  height: 100%;
  overflow-y: auto;
  padding: 10px 12px;
}

.workbench-dock__todo--empty {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fg-faint);
  font-size: var(--text-sm);
}

/* Task 495: right-dock subagent directory (running/ended sections, folded
   rows, 20-per-page reveal). Theme-token contract: same variable set as the
   sibling dock panels above. */
.subagents-panel {
  height: 100%;
  overflow-y: auto;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.subagents-panel__empty,
.subagents-panel__section-empty {
  padding: 6px 2px;
  color: var(--fg-faint);
  font-size: var(--text-sm);
}

.subagents-panel__section-title {
  margin: 0 0 4px;
  font-size: var(--text-xs);
  font-weight: 600;
  color: var(--fg-dim);
}

.subagents-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.subagents-panel__row-wrap + .subagents-panel__row-wrap {
  border-top: 1px solid var(--border-soft);
}

/* tl1209: a running row may carry its own terminate button beside the row
   body — the wrap becomes a flex row so the body keeps filling and the
   button hugs the trailing edge. Wraps without the button are unchanged
   (a lone flex child with flex:1 renders exactly like width:100%); the
   expanded detail wraps onto its own full-width line. */
.subagents-panel__row-wrap {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
}

.subagents-panel__row {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: 1 1 auto;
  min-width: 0;
  padding: 7px 9px;
  background: transparent;
  border: 0;
  cursor: pointer;
  text-align: left;
  font-size: var(--text-xs);
  color: var(--fg);
}

.subagents-panel__terminate {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  border: 0;
  border-left: 1px solid var(--border-soft);
  background: transparent;
  color: var(--fg-dim);
  cursor: pointer;
}

.subagents-panel__terminate:hover {
  background: var(--bg-soft);
  color: var(--danger, var(--fg-dim));
}

.subagents-panel__terminate:disabled {
  opacity: 0.5;
  cursor: default;
}

.subagents-panel__row:hover {
  background: var(--bg-soft);
}

.subagents-panel__icon--done { color: var(--ok, var(--fg-dim)); }
.subagents-panel__icon--failed { color: var(--danger, var(--fg-dim)); }
.subagents-panel__icon--cancelled { color: var(--fg-faint); }

.subagents-panel__spin {
  animation: spin 0.9s linear infinite;
  color: var(--fg-dim);
}

.subagents-panel__row-title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* 任务1033: the row title is wrapped in a Tooltip trigger — the trigger takes
   over the row's flex slot so the status/chevron keep their positions and the
   inner span keeps its ellipsis. */
.subagents-panel__row .tooltip-trigger {
  flex: 1 1 auto;
  min-width: 0;
}

.subagents-panel__row-status {
  flex: 0 0 auto;
  color: var(--fg-dim);
  font-size: 10px;
}

.subagents-panel__chevron {
  flex: 0 0 auto;
  color: var(--fg-faint);
  transition: transform 0.15s ease;
}

.subagents-panel__row--open .subagents-panel__chevron {
  transform: rotate(90deg);
}

.subagents-panel__detail {
  /* tl1209: inside the flexed row-wrap the expanded detail takes its own
     full-width line below the row body. */
  flex: 1 1 100%;
  min-width: 0;
  padding: 0 9px 8px 29px;
}

.subagents-panel__detail-summary {
  margin: 0 0 4px;
  font-size: var(--text-xs);
  color: var(--fg-dim);
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
}

.subagents-panel__detail-meta {
  margin: 0;
  display: flex;
  gap: 10px;
  font-size: 10px;
  color: var(--fg-faint);
}

.subagents-panel__foot {
  padding: 6px 0 0;
}

/* Task 507: plan-C widen toolbar + plan-A read-only detail view. Same
   theme-token set as the sibling subagents-panel rules above; the detail
   blocks wrap long tokens so a narrow dock never scrolls sideways. */
.subagents-panel__toolbar {
  display: flex;
  justify-content: flex-end;
}

.subagents-panel__wide {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-dim);
  font-size: 10px;
  cursor: pointer;
}

.subagents-panel__wide:hover {
  background: var(--bg-soft);
  color: var(--fg);
}

.subagents-panel__wide[aria-pressed="true"] {
  color: var(--fg);
  border-color: var(--fg-faint);
}

.subagents-panel__detailview {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* 任务440: the dock detail's live transcript container — a flex child of the
   detail column; the shared Transcript styles itself, the container only
   guards against wide-content overflow inside the dock body. */
.subagents-panel__live {
  min-width: 0;
  overflow-y: auto;
}

.subagents-panel__detailview-head {
  display: flex;
}

.subagents-panel__back {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-dim);
  font-size: var(--text-xs);
  cursor: pointer;
}

.subagents-panel__back:hover {
  background: var(--bg-soft);
  color: var(--fg);
}

.subagents-panel__detailview-title {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  font-size: var(--text-sm);
  color: var(--fg);
}

.subagents-panel__detailview-name {
  min-width: 0;
  overflow-wrap: anywhere;
}

.subagents-panel__detailview-meta {
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 10px;
  color: var(--fg-faint);
}

.subagents-panel__detailview-block {
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  padding: 7px 9px;
}

.subagents-panel__detailview-block--error {
  border-color: var(--danger, var(--border-soft));
}

.subagents-panel__detailview-label {
  margin: 0 0 4px;
  font-size: 10px;
  font-weight: 600;
  color: var(--fg-dim);
}

.subagents-panel__detailview-text {
  margin: 0;
  font-size: var(--text-xs);
  color: var(--fg-dim);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.subagents-panel__detailview-note,
.subagents-panel__readonly {
  margin: 0;
  font-size: 10px;
  color: var(--fg-faint);
}

/* tl1202: retry affordance for a failed transcript read — same quiet button
   chrome as the back button, placed under the failed note. */
.subagents-panel__retry {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-dim);
  font-size: var(--text-xs);
  cursor: pointer;
}

.subagents-panel__retry:hover {
  background: var(--bg-soft);
  color: var(--fg);
}

.workbench-dock__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.workbench-dock__body > .context-panel,
.workbench-dock__body > .workspace-panel {
  height: 100%;
}

.workbench-dock__body > .workspace-panel {
  border-left: none;
}

/* tl1108: 边栏宽度三态切换的 200ms 过渡（宽度是容器属性，动画落在
   layout 的 grid 列宽上；拖拽中由 --workspace-resizing 抑制）。 */
.layout:not(.layout--workspace-resizing) {
  transition: grid-template-columns 0.2s ease, min-width 0.2s ease;
}

/* tl1108/1109: 方案 E 浮动标签条（文件/子代理面板共用）。 */
.side-dock-tabstrip {
  --wails-draggable: no-drag;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 4px 6px 0;
  overflow-x: auto;
  scrollbar-width: thin;
  border-bottom: 1px solid var(--border-soft);
  background: var(--workspace-files-bg);
}

.side-dock-tab {
  --wails-draggable: no-drag;
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
  max-width: 180px;
  height: 24px;
  padding: 0 4px 0 8px;
  border: 1px solid transparent;
  border-bottom: none;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  background: transparent;
  color: var(--fg-faint);
  font-size: 11.5px;
  cursor: pointer;
  user-select: none;
}

.side-dock-tab__label {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.side-dock-tab--preview .side-dock-tab__label {
  font-style: italic;
}

.side-dock-tab:hover {
  color: var(--fg-dim);
}

.side-dock-tab--active {
  background: var(--bg-elev);
  border-color: var(--border-soft);
  color: var(--fg);
}

/* tl 1225b: same tl1225 inset bar mechanism for the side-dock tab strip's
   left/right insertion hints (horizontal strip → vertical bars on the nearest
   inside edge). The old outset hairlines (left/right: -2px) were painted
   outside the tab box and could be covered by neighbouring tabs. */
.side-dock-tab--drop-before {
  box-shadow: inset 2px 0 0 var(--accent);
}

.side-dock-tab--drop-after {
  box-shadow: inset -2px 0 0 var(--accent);
}

.side-dock-tab__close {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-faint);
  cursor: pointer;
}

.side-dock-tab__close:hover {
  color: var(--fg);
  background: var(--bg-soft);
}

/* tl1109: 子代理面板「列表(左) + 内容(右)」同屏布局（复用方案 E 容器宽度）。 */
.subagents-panel--split {
  display: grid;
  grid-template-columns: minmax(180px, 34%) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  height: 100%;
  min-height: 0;
}

.subagents-panel--split .subagents-panel__listpane {
  grid-row: 2;
  grid-column: 1;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  border-right: 1px solid var(--border-soft);
}

.subagents-panel--split .subagents-panel__detailview {
  grid-row: 2;
  grid-column: 2;
  min-width: 0;
  min-height: 0;
  overflow: auto;
}

.subagents-panel__openmain {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-dim);
  font-size: 11px;
  cursor: pointer;
}

.subagents-panel__openmain:hover {
  color: var(--fg);
  background: var(--bg-soft);
}

.layout--workspace-maximized .context-inspector,
.layout--workspace-maximized .workbench-dock {
  grid-column: 2;
}

.context-panel {
  --context-panel-gutter: 12px;
  --context-panel-scrollbar-gutter: 12px;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 0;
  gap: 0;
  background: var(--workspace-files-bg);
  color: var(--fg);
  overflow: hidden;
}

.context-panel__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 8px var(--context-panel-gutter) 12px;
  scrollbar-gutter: stable;
  /* tl1129: 指标卡按面板实际宽度自适应（246px 窄态 rail 单列展开，宽态保持
     多列）——面板宽度不随视口，媒体查询不可用，用容器查询。inline-size
     containment 只锁宽度轴，纵向滚动布局不受影响。 */
  container-type: inline-size;
  container-name: context-panel-body;
}

/* tl1129: 246px 窄态 rail（内容区 ~222px）下指标网格单列展开——会话指标
   「费用不可估算」「196分5秒」与用量分析「总计 107,164,532」不再被 2/3 列
   挤裁。断点 319px：低于它单列（每列拿到全部行宽），达到即恢复多列（宽态
   720px 与中间拖宽态观感不变）。 */
@container context-panel-body (max-width: 319px) {
  .context-panel__summary-rows,
  /* creation 覆写段（.app--creation 前缀）特异性更高，窄容器单列须同规则
     对齐，否则 creation 布局下仍被钉在 2 列。 */
  .app--creation .context-panel__summary-rows {
    grid-template-columns: minmax(0, 1fr);
  }

  /* 单列后奇偶项的左右 padding / 分隔竖线不再有意义，恢复对称行。 */
  .context-panel__mini-stat:nth-child(odd),
  .app--creation .context-panel__mini-stat:nth-child(odd) {
    padding-right: 0;
  }

  .context-panel__mini-stat:nth-child(even),
  .app--creation .context-panel__mini-stat:nth-child(even) {
    padding-left: 0;
    border-left: 0;
  }

  .context-panel__source-summary,
  .context-panel__source-metrics {
    grid-template-columns: minmax(0, 1fr);
  }

  .context-panel__source-legend {
    grid-template-columns: minmax(0, 1fr);
  }
}

.context-panel__overview {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.context-panel__usage,
.context-panel__section {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0;
  padding: 10px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: var(--bg);
}

.context-panel__mcp-empty {
  margin: 0;
  color: var(--fg-faint);
  font-size: var(--text-sm);
  line-height: 1.4;
}

.context-panel__mcp-rows {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.context-panel__mcp-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: var(--text-sm);
  color: var(--fg);
}

.context-panel__mcp-row strong {
  font-variant-numeric: tabular-nums;
}

.context-panel__section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}

.context-panel__section-head h3 {
  margin: 0;
  min-width: 0;
  color: var(--fg);
  font-size: var(--text-md);
  line-height: 1.2;
  font-weight: 670;
}

.context-panel__section-head span {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg-faint);
  font-size: 11.5px;
  line-height: 1.2;
}

.context-panel__view-switch {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  margin-left: auto;
  padding: 2px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--fg) 3%, var(--bg));
}

.context-panel__view-tab {
  appearance: none;
  min-width: 0;
  max-width: 9ch;
  overflow: hidden;
  padding: 3px 7px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-dim);
  cursor: pointer;
  font: inherit;
  font-size: var(--text-xs);
  font-weight: 560;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-panel__view-tab:hover {
  color: var(--fg);
  background: color-mix(in srgb, var(--fg) 5%, transparent);
}

.context-panel__view-tab--active,
.context-panel__view-tab--active:hover {
  color: var(--fg);
  background: var(--bg-elev);
  box-shadow: 0 1px 2px color-mix(in srgb, var(--fg) 10%, transparent);
}

.context-panel__usage-visual {
  display: none;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.context-panel__donut {
  width: 136px;
  height: 136px;
  padding: 12px;
  border-radius: 50%;
}

.context-panel__donut-core {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: var(--workspace-files-bg);
  text-align: center;
}

.context-panel__donut-core strong {
  color: var(--fg);
  font-size: 30px;
  line-height: 1;
}

.context-panel__donut-core span {
  margin-top: 6px;
  color: var(--fg-dim);
  font-size: var(--text-sm);
  line-height: 1.25;
}

.context-panel__percent {
  color: var(--fg);
  text-align: center;
  font-size: 18px;
  font-weight: 650;
}

.context-panel__capacity-card {
  min-width: 0;
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--accent) 12%, var(--border-soft));
  border-radius: var(--radius-md);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent) 5%, var(--chat-bg)) 0%, color-mix(in srgb, var(--chat-bg) 86%, var(--stage, #000)) 100%);
}

.context-panel__capacity-card--good {
  border-color: color-mix(in srgb, var(--ok) 20%, var(--border-soft));
}

.context-panel__capacity-card--notice {
  border-color: color-mix(in srgb, var(--warn) 26%, var(--border-soft));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--warn) 6%, var(--bg)) 0%, var(--bg) 100%);
}

.context-panel__capacity-card--warn {
  border-color: color-mix(in srgb, var(--err) 28%, var(--border-soft));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--err) 6%, var(--bg)) 0%, var(--bg) 100%);
}

/* 任务665: the row may wrap in a narrow card — badges keep their full text
   and the right-aligned used/window figure yields (drops below) instead of
   the status label being clipped mid-glyph. */
.context-panel__capacity-top {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 6px 10px;
}

/* 任务549: status pill + projection-stale badge grouped on the left so the
   right-aligned used/window figure stays a single flex child.
   任务665: the flag group never shrinks or clips — labels render whole. */
.context-panel__capacity-flags {
  flex: 0 0 auto;
  max-width: 100%;
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.context-panel__projection-stale {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border: 1px solid color-mix(in srgb, var(--warn) 24%, transparent);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--warn) 11%, transparent);
  color: var(--warn);
  font-size: var(--text-sm);
  font-weight: 650;
  line-height: 1;
  white-space: nowrap;
  cursor: help;
}

/* 任务1025: 读数来源标记——「实测」/「估算」，与投影失效标记同族小 pill。 */
.context-panel__readout-source {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border: 1px solid color-mix(in srgb, var(--fg-dim) 28%, transparent);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--fg-dim) 10%, transparent);
  color: var(--fg-dim);
  font-size: var(--text-sm);
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
  cursor: help;
}

.context-panel__capacity-top strong {
  min-width: 0;
  overflow: hidden;
  margin-left: auto;
  color: var(--fg);
  text-align: right;
  font-size: 14.5px;
  font-weight: 620;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* 任务665: no max-width/overflow clip on the status badge —「即将压缩」and
   its translations always render in full; max-width:100% is only an overflow
   guard for a pathologically long label. */
.context-panel__capacity-status {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  max-width: 100%;
  padding: 3px 8px;
  border: 1px solid color-mix(in srgb, var(--ok) 20%, transparent);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--ok) 10%, transparent);
  color: var(--ok);
  font-size: var(--text-sm);
  font-weight: 650;
  line-height: 1;
  white-space: nowrap;
}

.context-panel__capacity-card--notice .context-panel__capacity-status {
  border-color: color-mix(in srgb, var(--warn) 24%, transparent);
  background: color-mix(in srgb, var(--warn) 11%, transparent);
  color: var(--warn);
}

.context-panel__capacity-card--warn .context-panel__capacity-status {
  border-color: color-mix(in srgb, var(--err) 24%, transparent);
  background: color-mix(in srgb, var(--err) 10%, transparent);
  color: var(--err);
}

.context-panel__capacity-meter {
  gap: 6px;
}

.context-panel__capacity-scale {
  position: relative;
  height: 21px;
}

.context-panel__capacity-pin {
  position: absolute;
  top: 0;
  z-index: var(--z-local-raised);
  max-width: 58px;
  overflow: hidden;
  padding: 3px 7px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-pill);
  background: var(--bg-elev);
  color: var(--fg-dim);
  font-size: var(--text-xs);
  font-weight: 680;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
  box-shadow: 0 1px 4px color-mix(in srgb, var(--shadow-color) 10%, transparent);
  transform: translateX(-50%);
  font-variant-numeric: tabular-nums;
}

.context-panel__capacity-pin--used {
  border-color: color-mix(in srgb, var(--accent) 42%, transparent);
  background: color-mix(in srgb, var(--accent) 92%, #fff);
  color: white;
}

.context-panel__capacity-pin--compact {
  border-color: color-mix(in srgb, var(--fg) 16%, transparent);
  background: color-mix(in srgb, var(--bg-elev) 90%, var(--fg) 10%);
  color: var(--fg-dim);
}

.context-panel__capacity-meter .context-panel__progress-track {
  height: 12px;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fg) 3%, transparent);
}

.context-panel__capacity-foot {
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding-top: 2px;
  color: var(--fg-dim);
  font-size: var(--text-sm);
  line-height: 1.2;
}

.context-panel__capacity-foot > span,
.context-panel__capacity-remaining span,
.context-panel__capacity-remaining strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-panel__capacity-remaining {
  display: inline-flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 6px;
  min-width: 0;
  line-height: 1.2;
}

.context-panel__capacity-remaining span {
  color: var(--fg-dim);
  font-size: var(--text-sm);
  font-weight: 500;
}

.context-panel__capacity-remaining strong {
  color: var(--fg);
  font-size: 13.5px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}

.context-panel__budget {
  margin-top: 12px;
}

.context-panel__budget-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.context-panel__budget-grid > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.context-panel__budget-grid span {
  color: var(--fg-dim);
  font-size: var(--text-xs);
}

.context-panel__budget-grid strong {
  font-size: var(--text-md);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}

.context-panel__budget-source,
.context-panel__budget-note,
.context-panel__budget-recovery {
  margin: 8px 0 0;
  color: var(--fg-dim);
  font-size: var(--text-sm);
  line-height: 1.4;
}

.context-panel__usage-progress {
  display: grid;
  gap: 0;
}

.context-panel__progress-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.context-panel__progress-head strong {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-size: var(--text-sm);
  font-weight: 600;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-panel__progress-head span {
  flex: 0 0 auto;
  color: var(--accent);
  font-size: var(--text-sm);
  font-weight: 660;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.context-panel__progress-track {
  position: relative;
  display: flex;
  height: 8px;
  overflow: hidden;
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--fg-faint) 10%, transparent);
}

.context-panel__compact-marker {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: var(--z-local-raised);
