/* Topic shortcut badges (Cmd/Ctrl+1-9 overlay) */

.project-tree__topic-shortcut {
  position: absolute;
  top: 50%;
  right: 8px;
  z-index: var(--z-local-raised);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
