  line-height: 1;
  letter-spacing: 0.02em;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-50%) translateX(4px);
  transition: opacity 120ms ease, transform 120ms ease;
}

/* Show badges when the parent topic has the modifier held class */
.project-tree__topic--show-shortcut .project-tree__topic-shortcut {
  opacity: 1;
