.sidebar--workbench .project-tree__topic--show-shortcut .project-tree__topic-actions,
.app--classic .project-tree__topic--show-shortcut .project-tree__topic-actions {
  opacity: 0;
  pointer-events: none;
  transform: translateY(-50%) translateX(4px);
}

/* In classic mode, hide the meta line when shortcuts are shown */
.project-tree__topic--show-shortcut .project-tree__topic-meta {
  opacity: 0;
}

