/* Capability diagnostics settings page */
.diag-page {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}
.diag-page__toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.diag-page__runtime {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: var(--text-md);
  min-width: 0;
}
.diag-page__actions {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
}
.diag-page__hint {
  margin: 0;
  font-size: var(--text-sm);
  color: var(--text-muted, #888);
