  line-height: 1.1;
}
.diag-summary__item--error strong { color: var(--danger, #e35); }
.diag-summary__item--warning strong { color: var(--warn, #d90); }
.diag-summary__item--info strong { color: var(--accent, #4af); }
.diag-summary__meta {
  grid-column: 1 / -1;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: var(--text-sm);
  color: var(--text-muted, #888);
  min-width: 0;
}
.diag-section {
  border: 1px solid var(--border, rgba(127,127,127,.25));
  border-radius: var(--radius-md);
  min-width: 0;
  overflow: hidden;
}
.diag-section__header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 12px;
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
}
.diag-section__body {
  padding: 0 12px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
.diag-section__body--frontend {
