  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  min-height: 32px;
  padding: 4px;
  border: 1px solid var(--border, rgba(127,127,127,.25));
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--bg-elev, #fff) 94%, transparent);
