}
.diag-issue__msg,
.diag-issue__fix {
  margin: 0;
  font-size: var(--text-md);
  line-height: 1.4;
}
.diag-issue__fix {
  color: var(--text-muted, #888);
}
/* Task 625: same-code issue cluster row (collapsed summary + expandable details). */
.diag-issues-scope {
  margin-left: auto;
  font-size: var(--text-sm);
  font-weight: 400;
  color: var(--text-muted, #888);
}
.diag-issue-cluster {
  border: 1px solid var(--border, rgba(127,127,127,.2));
  border-radius: var(--radius-md);
  padding: 4px 10px;
  min-width: 0;
