}
.diag-issue-cluster__details {
  margin: 2px 0 6px 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.diag-issue--nested header {
  justify-content: flex-start;
}
/* Goto button stays a small inline control pinned to its row's right edge, never full-width. */
.diag-issue__goto {
  align-self: flex-start;
  margin-left: auto;
  flex: 0 0 auto;
