/* ==========================================================================
/* ==========================================================================
   Theme Pack V1 — background layer, scene, library editor
   Overlay CSS variables are injected last by themePack.ts so pack tokens win
   over base style sheets and Creation-local variables.
   ========================================================================== */

.theme-bg {
  position: fixed;
  inset: 0;
  z-index: var(--z-theme-bg);
  pointer-events: none;
  overflow: hidden;
  display: none;
}

:root[data-theme-has-bg="true"] .theme-bg {
  display: block;
}

.theme-bg__image {
  position: absolute;
  inset: -4%;
  background-image: var(--theme-bg-home-image, var(--theme-bg-image, none));
  background-repeat: no-repeat;
  background-size: cover;
  background-position: var(--theme-bg-home-focus-x, var(--theme-bg-focus-x, 50%)) var(--theme-bg-home-focus-y, var(--theme-bg-focus-y, 50%));
  opacity: var(--theme-bg-home-opacity, 1);
  transition: opacity 180ms ease;
}

/* Task scene: reduce background strength for chat readability */
:root[data-theme-scene="task"] .theme-bg__image {
  background-image: var(--theme-bg-task-image, var(--theme-bg-home-image, var(--theme-bg-image, none)));
  background-position: var(--theme-bg-task-focus-x, var(--theme-bg-focus-x, 50%)) var(--theme-bg-task-focus-y, var(--theme-bg-focus-y, 50%));
  opacity: var(--theme-bg-task-opacity, 0.28);
}

.theme-bg__overlay {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 180ms ease;
  background: transparent;
}

:root[data-theme-scene="task"] .theme-bg__overlay {
  opacity: 1;
}

/* Directional readable safe-area wash (no backdrop-filter) */
:root[data-theme-scene="task"][data-theme-safe-area="left"] .theme-bg__overlay {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--bg) calc(var(--theme-bg-task-overlay, var(--theme-bg-overlay, 0.62)) * 100%), transparent) 0%,
    color-mix(in srgb, var(--bg) calc(var(--theme-bg-task-overlay, var(--theme-bg-overlay, 0.62)) * 55%), transparent) 42%,
    transparent 78%
  );
}

:root[data-theme-scene="task"][data-theme-safe-area="right"] .theme-bg__overlay {
  background: linear-gradient(
    270deg,
    color-mix(in srgb, var(--bg) calc(var(--theme-bg-task-overlay, var(--theme-bg-overlay, 0.62)) * 100%), transparent) 0%,
    color-mix(in srgb, var(--bg) calc(var(--theme-bg-task-overlay, var(--theme-bg-overlay, 0.62)) * 55%), transparent) 42%,
    transparent 78%
  );
}

:root[data-theme-scene="task"][data-theme-safe-area="center"] .theme-bg__overlay,
:root[data-theme-scene="task"]:not([data-theme-safe-area]) .theme-bg__overlay {
  background: radial-gradient(
    ellipse 70% 70% at 50% 45%,
    color-mix(in srgb, var(--bg) calc(var(--theme-bg-task-overlay, var(--theme-bg-overlay, 0.62)) * 70%), transparent) 0%,
    color-mix(in srgb, var(--bg) calc(var(--theme-bg-task-overlay, var(--theme-bg-overlay, 0.62)) * 40%), transparent) 55%,
    transparent 100%
  );
}

/* Keep chrome readable above the decorative layer */
.app > .layout,
.app > .theme-bg + .layout {
  position: relative;
  z-index: var(--z-app-content);
}

.app {
  position: relative;
  isolation: isolate;
}

:root[data-theme-pack][data-theme-has-bg="true"] {
  --overlay-surface-bg: color-mix(
    in srgb,
    var(--bg-elev) var(--theme-pane-overlay-pct, 90%),
    transparent
  );
}

:root[data-theme-pack][data-theme-has-bg="true"][data-theme-scene="task"] {
  --overlay-surface-bg: color-mix(
    in srgb,
    var(--bg-elev) var(--theme-pane-task-overlay-pct, 100%),
    transparent
  );
}

/* Density recipe consumers — pack overlay sets --theme-density-* / --theme-row-h */
:root {
  --theme-density-pad: 10px;
  --theme-density-gap: 10px;
  --theme-row-h: 34px;
}

:root[data-theme-pack] {
  --list-row-height: var(--theme-row-h);
  --list-row-gap: var(--theme-density-gap);
  --tree-row-height: calc(var(--theme-row-h) - 4px);
}

/* Theme library cards */
.theme-library {
  display: flex;
  flex-direction: column;
  gap: var(--theme-density-gap, 12px);
  width: 100%;
}

.theme-library__toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--theme-density-gap, 8px);
  align-items: center;
}

.theme-library__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(168px, 1fr));
  gap: var(--theme-density-gap, 10px);
}

.theme-lib-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--theme-density-gap, 8px);
  text-align: left;
  padding: var(--theme-density-pad, 10px);
  border-radius: var(--r, 8px);
  border: 1px solid var(--border-soft, var(--border));
  background: var(--bg-elev, var(--panel));
  color: inherit;
  cursor: pointer;
  min-height: calc(var(--theme-row-h, 34px) * 3.5);
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

.theme-lib-card:hover {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
}

.theme-lib-card--on {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 35%, transparent);
}

.theme-lib-card__thumb {
  height: 56px;
  border-radius: calc(var(--r, 8px) - 2px);
  background:
    linear-gradient(135deg, var(--thumb-light, #eee), var(--thumb-dark, #333));
  background-size: cover;
  background-position: center;
  border: 1px solid var(--border-soft, transparent);
}

.theme-lib-card__meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.theme-lib-card__name {
  font-size: var(--text-md);
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theme-lib-card__sub {
  font-size: var(--text-xs);
  color: var(--fg-faint, var(--text-3));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theme-lib-card__swatches {
  display: flex;
  gap: 4px;
}

.theme-lib-card__swatch {
  width: 12px;
  height: 12px;
  border-radius: var(--radius-pill);
  border: 1px solid color-mix(in srgb, var(--fg) 12%, transparent);
}

.theme-lib-card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: auto;
}

.theme-lib-card__actions .btn {
  font-size: var(--text-xs);
  padding: 2px 6px;
  height: auto;
}

/* Theme library groups: official / base / user */
.theme-library__group {
  display: flex;
  flex-direction: column;
  gap: var(--theme-density-gap, 8px);
}

.theme-library__heading {
  margin: 4px 0 0;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--fg-dim, var(--text-2));
  letter-spacing: 0.02em;
}

.theme-library__grid--official {
  grid-template-columns: repeat(auto-fill, minmax(218px, 1fr));
}

.theme-lib-card--official .theme-lib-card__thumb--img {
  position: relative;
  height: 108px;
  overflow: hidden;
  background: var(--bg-soft, #eee);
}

.theme-lib-card--official .theme-lib-card__thumb--img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.theme-lib-card__thumb-fallback {
  width: 100%;
  height: 100%;
}

.theme-lib-card__desc {
  font-size: var(--text-xs);
  line-height: 1.45;
  color: var(--fg-dim, var(--text-2));
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.theme-library__grid--base {
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
}

.theme-library__grid--base .theme-lib-card__thumb {
  height: 40px;
}

/* Appearance overview (demo 1) */
.appearance-overview {
  display: flex;
  flex-direction: column;
  gap: var(--theme-density-gap, 16px);
  max-width: 920px;
}
.appearance-overview__header { display: flex; flex-direction: column; gap: 4px; }
.appearance-overview__title {
  margin: 0;
  font-size: var(--text-lg, 1.125rem);
  font-weight: 600;
  color: var(--fg, var(--text));
}
.appearance-overview__sub {
  margin: 0;
  font-size: var(--text-base, 0.875rem);
  color: var(--fg-dim, var(--text-2));
}
.appearance-overview__section-label {
  margin: 0 0 10px;
  font-size: var(--text-base, 0.875rem);
  font-weight: 600;
  color: var(--fg-dim, var(--text-2));
}
.appearance-overview__hero {
  display: grid;
  grid-template-columns: minmax(150px, 210px) 1fr;
  gap: 14px;
  padding: 12px;
  border: 1px solid var(--border, var(--border-soft));
  border-radius: var(--r-l, 12px);
  background: var(--bg-elev, var(--panel));
}
.appearance-overview__thumb {
  border-radius: var(--r, 8px);
  overflow: hidden;
  min-height: 104px;
  background: var(--bg-soft);
}
.appearance-overview__thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  min-height: 104px;
}
.appearance-overview__thumb-base.theme-card__swatches {
  display: flex;
  gap: 8px;
  align-items: center;
  justify-content: center;
  width: auto;
  height: auto;
  min-height: 104px;
  padding: 16px;
  overflow: visible;
  border-radius: 0;
}
.appearance-overview__thumb-base .theme-card__swatch {
  min-width: 28px;
  height: 38px;
  border-radius: var(--radius-md);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fg-faint) 30%, transparent);
}
.appearance-overview__hero-meta { display: flex; flex-direction: column; justify-content: center; gap: 8px; min-width: 0; }
.appearance-overview__hero-title-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.appearance-overview__hero-name { margin: 0; font-size: var(--text-md, 1rem); font-weight: 600; }
.appearance-overview__swatches { display: flex; gap: 6px; }
.appearance-overview__swatches span {
  width: 18px; height: 18px; border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--fg) 12%, transparent);
}
.appearance-overview__in-use {
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--ok, #3d9a6a);
  font-size: var(--text-base, 0.875rem);
  font-weight: 500;
}
.appearance-overview__hero-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 4px; }
.appearance-overview__rows {
  display: flex; flex-direction: column;
  border: 1px solid var(--border, var(--border-soft));
  border-radius: var(--r-l, 12px);
  overflow: hidden;
  background: var(--bg-elev, var(--panel));
}
.appearance-overview__row {
  display: grid;
  grid-template-columns: minmax(100px, 140px) 1fr;
  gap: 12px;
  align-items: center;
  padding: 12px 14px;
  border-top: 1px solid var(--border-soft, var(--border));
}
.appearance-overview__row:first-child { border-top: 0; }
.appearance-overview__row-label {
  font-size: var(--text-base, 0.875rem);
  color: var(--fg-dim, var(--text-2));
}
.appearance-overview__row-note {
  margin-top: 3px;
  color: var(--fg-faint);
  font-size: var(--text-xs, 0.75rem);
  line-height: 1.45;
}
.appearance-overview__row--typography {
  grid-template-columns: minmax(0, 1fr) auto;
  background: color-mix(in srgb, var(--accent-soft) 24%, transparent);
}
.appearance-overview__segmented {
  justify-self: end;
  width: 424px;
  max-width: 100%;
  min-width: 0;
}
.appearance-overview__segmented .set-seg__btn {
  flex: 1;
  min-width: 0;
}
.appearance-overview__select {
  justify-self: end;
  min-width: 160px;
  max-width: 100%;
  padding: 6px 10px;
  border-radius: var(--r, 8px);
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--fg);
  font-size: var(--text-base, 0.875rem);
}
.appearance-overview__font-input {
  justify-self: stretch;
  min-width: 0;
  width: 100%;
  resize: vertical;
}
.appearance-overview__control-stack {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}
.appearance-overview__lock-note {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 5px;
  color: var(--fg-dim);
  font-size: var(--text-xs, 0.75rem);
  line-height: 1.35;
  text-align: right;
}
.appearance-overview__row--footer {
  grid-template-columns: minmax(0, 1fr) auto;
  background: color-mix(in srgb, var(--bg-soft) 50%, transparent);
}
.appearance-overview__reset-hint {
  color: var(--fg-dim);
  font-size: var(--text-xs, 0.75rem);
  line-height: 1.45;
}

@media (max-width: 720px) {
  .appearance-overview__hero { grid-template-columns: 1fr; }
  .appearance-overview__row { grid-template-columns: 1fr; }
  .appearance-overview__segmented { justify-self: stretch; width: 100%; }
  .appearance-overview__select { justify-self: stretch; }
  .appearance-overview__control-stack { align-items: stretch; }
  .appearance-overview__lock-note { justify-content: flex-start; text-align: left; }
  .appearance-overview__row--footer { grid-template-columns: 1fr; }
}

/* Detailed typography settings (master-detail). */
.typography-settings {
  display: flex;
  min-height: 0;
  height: 100%;
  flex-direction: column;
  gap: 14px;
  max-width: 1040px;
}
.typography-settings__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}
.typography-settings__header h2 {
  margin: 0;
  color: var(--fg);
  font-size: var(--text-lg);
  font-weight: 650;
}
.typography-settings__heading-row {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 4px;
}
.typography-settings__header p,
.typography-settings__detail-head p {
  margin: 0;
  color: var(--fg-dim);
  font-size: var(--text-sm);
}
.typography-settings__back {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  border-radius: var(--radius-md);
}
.typography-settings__back:hover { color: var(--fg); background: var(--sidebar-hover); }
.typography-settings__workspace {
  display: grid;
  grid-template-columns: 188px minmax(0, 1fr);
  min-height: 620px;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--r-l, 12px);
  background: var(--bg-elev);
}
.typography-settings__regions {
  padding: 14px 10px;
  border-right: 1px solid var(--border-soft);
  background: color-mix(in srgb, var(--bg-soft) 78%, var(--bg-elev));
}
.typography-settings__regions-label {
  padding: 0 10px 9px;
  color: var(--fg-faint);
  font-size: var(--text-xs);
  font-weight: 650;
  letter-spacing: 0.04em;
}
.typography-settings__region {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 7px;
  width: 100%;
  min-height: 38px;
  padding: 0 9px 0 11px;
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--fg-dim);
  text-align: left;
}
.typography-settings__region:hover { background: var(--sidebar-hover); color: var(--fg); }
.typography-settings__region--active {
  background: var(--sidebar-active);
  color: var(--accent);
  font-weight: 650;
}
.typography-settings__dot {
  width: 6px;
  height: 6px;
  border-radius: var(--radius-pill);
  background: var(--accent);
}
.typography-settings__detail {
  min-width: 0;
  overflow: auto;
  padding: 18px 20px 22px;
}
.typography-settings__detail-head,
.typography-settings__title-row,
.typography-settings__actions,
.typography-settings__preview-head {
  display: flex;
  align-items: center;
}
.typography-settings__detail-head {
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 15px;
  border-bottom: 1px solid var(--border-soft);
}
.typography-settings__title-row { gap: 8px; }
.typography-settings__title-row h3 {
  margin: 0 0 4px;
  font-size: var(--text-lg);
  font-weight: 650;
}
.typography-settings__badge {
  padding: 2px 7px;
  border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--border));
  border-radius: var(--radius-pill);
  background: var(--accent-soft);
  color: var(--accent);
  font-size: var(--text-xs);
}
.typography-settings__follow {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 0 0 auto;
  color: var(--fg-dim);
  font-size: var(--text-sm);
}
.typography-settings__follow input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.typography-settings__switch {
  position: relative;
  width: 34px;
  height: 20px;
  border-radius: var(--radius-pill);
  background: var(--bg-elev-2);
  box-shadow: inset 0 0 0 1px var(--border);
}
.typography-settings__switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--fg-faint);
  transition: transform var(--dur-fast), background var(--dur-fast);
}
.typography-settings__follow input:checked + .typography-settings__switch { background: var(--accent); }
.typography-settings__follow input:checked + .typography-settings__switch::after {
  transform: translateX(14px);
  background: var(--accent-fg);
}
.typography-settings__follow input:focus-visible + .typography-settings__switch { box-shadow: var(--focus-ring); }
.typography-settings__controls {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 17px 0 14px;
}
.typography-settings__controls--disabled { opacity: 0.58; }
.typography-settings__field {
  display: grid;
  grid-template-columns: 122px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  color: var(--fg-dim);
  font-size: var(--text-base);
}
.typography-settings__field select,
.typography-settings__field input {
  min-width: 0;
  height: 34px;
  padding: 0 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  outline: 0;
  background: var(--bg);
  color: var(--fg);
  font: inherit;
}
.typography-settings__field select:focus,
.typography-settings__field input:focus { border-color: var(--accent); box-shadow: var(--focus-ring); }
.typography-settings__size-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.typography-settings__stepper,
.typography-settings__presets { display: inline-flex; align-items: center; gap: 5px; }
.typography-settings__stepper {
  height: 34px;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
}
.typography-settings__stepper button {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 0;
  background: transparent;
  color: var(--fg-dim);
}
.typography-settings__stepper span { min-width: 48px; color: var(--fg); text-align: center; font-variant-numeric: tabular-nums; }
.typography-settings__presets button {
  min-width: 34px;
  height: 30px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: var(--bg-soft);
  color: var(--fg-dim);
}
.typography-settings__presets button.is-active { border-color: var(--accent); color: var(--accent); background: var(--accent-soft); }
.typography-settings__advanced {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: center;
  gap: 7px;
  width: 100%;
  padding: 11px 0 0;
  border: 0;
  border-top: 1px solid var(--border-soft);
  background: transparent;
  color: var(--fg-dim);
  text-align: left;
}
.typography-settings__advanced small { color: var(--fg-faint); text-align: right; }
.typography-settings__advanced-note { margin: -5px 0 0 21px; color: var(--fg-faint); font-size: var(--text-sm); }
.typography-settings__actions {
  justify-content: flex-end;
  gap: 10px;
  color: var(--ok);
  font-size: var(--text-xs);
}
.typography-settings__actions .btn { margin-right: auto; }
.typography-settings__undo {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--accent);
  font: inherit;
}
.typography-settings__undo:disabled { color: var(--fg-faint); }
.typography-settings__preview {
  --preview-size: var(--typography-conversation-size, calc(14px * var(--global-font-scale)));
  --preview-font: var(--typography-conversation-font, var(--font-content-family));
  margin-top: 14px;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
}
.typography-settings__preview--interface { --preview-size: var(--typography-interface-size, calc(14px * var(--global-font-scale))); --preview-font: var(--typography-interface-font, var(--font-ui)); }
.typography-settings__preview--composer { --preview-size: var(--typography-composer-size, calc(14px * var(--global-font-scale))); --preview-font: var(--typography-composer-font, var(--font-content-family)); }
.typography-settings__preview--code { --preview-size: var(--typography-code-size, calc(12px * var(--global-font-scale))); --preview-font: var(--typography-code-font, var(--font-mono)); }
.typography-settings__preview--metadata { --preview-size: var(--typography-metadata-size, calc(12px * var(--global-font-scale))); --preview-font: var(--typography-metadata-font, var(--font-ui)); }
.typography-settings__preview-head {
  justify-content: space-between;
  gap: 10px;
  padding: 9px 12px 0;
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.typography-settings__preview-head [role="tablist"] { display: flex; gap: 2px; }
.typography-settings__preview-head button {
  padding: 5px 8px 7px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--fg-faint);
  font: inherit;
}
.typography-settings__preview-head button.is-active { border-bottom-color: var(--accent); color: var(--fg); }
.typography-settings__preview-body {
  min-height: 140px;
  padding: 16px 18px;
  border-top: 1px solid var(--border-soft);
  color: var(--fg-dim);
  font-family: var(--preview-font);
  font-size: var(--preview-size);
  line-height: 1.65;
}
.typography-settings__preview-body h4 { margin: 0 0 7px; color: var(--fg); font-size: 1.05em; }
.typography-settings__preview-body p { margin: 0 0 7px; }
.typography-settings__preview-chat { display: flex; flex-direction: column; gap: 12px; }
.typography-settings__preview-message {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: start;
  gap: 10px;
}
.typography-settings__preview-message p { margin: 2px 0 0; }
.typography-settings__preview-avatar {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--bg-elev-2);
  color: var(--fg-dim);
}
.typography-settings__preview-message--assistant .typography-settings__preview-avatar {
  border-color: color-mix(in srgb, var(--accent) 25%, var(--border));
  color: var(--accent);
}
.typography-settings__preview-message code {
  display: block;
  width: max-content;
  margin: 8px 0;
  padding: 2px 8px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: var(--bg-soft);
  color: var(--fg-dim);
  font-family: var(--font-mono);
  font-size: 0.88em;
}
.typography-settings__preview-message small {
  display: inline-flex;
  padding: 2px 7px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  color: var(--fg-faint);
}
.typography-settings__preview-reasoning { padding-left: 12px; border-left: 2px solid var(--border); color: var(--fg-faint); }
.typography-settings__preview-body pre {
  margin: 0;
  padding: 11px;
  overflow: auto;
  border-radius: var(--radius-md);
  background: var(--bg-soft);
  color: var(--fg);
  font-family: var(--typography-code-font, var(--font-mono));
  white-space: pre-wrap;
}
@media (max-width: 760px) {
  .typography-settings__workspace { grid-template-columns: 1fr; }
  .typography-settings__regions { display: flex; gap: 4px; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--border-soft); }
  .typography-settings__regions-label { display: none; }
  .typography-settings__region { width: auto; min-width: max-content; }
  .typography-settings__region svg { display: none; }
  .typography-settings__field { grid-template-columns: 1fr; }
  .typography-settings__size-row { align-items: flex-start; flex-direction: column; }
}

/* Theme gallery (demo 2 + immersive demo 3) */
.theme-gallery {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
  container: theme-gallery / inline-size;
}
.theme-gallery__top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  flex-wrap: wrap;
}
.theme-gallery__crumbs { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.theme-gallery__back {
  display: inline-flex; align-items: center; gap: 6px;
  border: 0; background: transparent; color: var(--fg-dim);
  font-size: var(--text-sm, 0.8125rem); cursor: pointer; padding: 0;
}
.theme-gallery__back:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.theme-gallery__title {
  margin: 0;
  font-size: var(--text-lg, 1.125rem);
  font-weight: 600;
}
.theme-gallery__sub {
  margin: 0;
  font-size: var(--text-base, 0.875rem);
  color: var(--fg-dim);
}
.theme-gallery__top-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.theme-gallery__tabs {
  display: flex; gap: 4px; flex-wrap: wrap;
  border-bottom: 1px solid var(--border-soft);
  padding-bottom: 2px;
}
.theme-gallery__tab {
  border: 0; background: transparent; color: var(--fg-dim);
  padding: 8px 12px; border-radius: var(--r, 8px) var(--r, 8px) 0 0;
  font-size: var(--text-base, 0.875rem); cursor: pointer;
}
.theme-gallery__tab--on {
  color: var(--fg); font-weight: 600;
  box-shadow: inset 0 -2px 0 var(--accent);
}
.theme-gallery__tab:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.theme-gallery__tab-count {
  display: inline-block; margin-left: 4px; opacity: 0.7; font-size: var(--text-sm, 0.8125rem);
}
.theme-gallery__body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 320px);
  gap: 16px;
  min-height: 360px;
}
.theme-gallery__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 12px;
  align-content: start;
}
.theme-gallery__grid-section { display: contents; }
.theme-gallery__section-head {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 4px;
  padding: 2px 2px 6px;
  border-bottom: 1px solid var(--border-soft);
  color: var(--fg-dim);
}
.theme-gallery__grid-section:first-child .theme-gallery__section-head { margin-top: 0; }
.theme-gallery__section-head h3 {
  margin: 0;
  color: var(--fg);
  font-size: var(--text-base, 0.875rem);
  font-weight: 600;
}
.theme-gallery__section-head span {
  font-size: var(--text-sm, 0.8125rem);
  font-variant-numeric: tabular-nums;
}
:root[data-text-size="xxlarge"] .theme-gallery__grid,
:root[data-text-size="xlarge"] .theme-gallery__grid {
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
}
.theme-gallery-card {
  display: flex; flex-direction: column; gap: 8px;
  padding: 0; border: 1px solid var(--border-soft);
  border-radius: var(--r-l, 12px); overflow: hidden;
  background: var(--bg-elev, var(--panel));
  color: inherit; text-align: left; cursor: pointer;
}
.theme-gallery-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.theme-gallery-card--selected { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.theme-gallery-card--active .theme-gallery-card__name { font-weight: 600; }
.theme-gallery-card__thumb {
  position: relative; aspect-ratio: 16 / 9; background: var(--bg-soft); overflow: hidden;
}
.theme-gallery-card__thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.theme-gallery-card__thumb > .theme-preview-surface {
  width: 100%;
  height: 100%;
  min-height: 0;
  border-radius: 0;
}
.theme-gallery-card__swatches { width: 100%; height: 100%; }
.theme-gallery-card__check {
  position: absolute; top: 8px; right: 8px;
  width: 22px; height: 22px; border-radius: 999px;
  background: var(--accent); color: var(--accent-fg, #fff);
  display: grid; place-items: center;
}
.theme-gallery-card__name {
  padding: 0 10px 4px;
  font-size: var(--text-base, 0.875rem);
}
.theme-gallery-card__status {
  padding: 0 10px 10px;
  font-size: var(--text-sm, 0.8125rem);
  color: var(--ok, #3d9a6a);
}
.theme-gallery__detail {
  display: flex; flex-direction: column; gap: 12px;
  padding: 12px; border: 1px solid var(--border-soft);
  border-radius: var(--r-l, 12px);
  background: var(--bg-elev, var(--panel));
  min-width: 0;
  align-self: start;
  position: sticky;
  top: 0;
}
.theme-gallery__detail-preview { border-radius: var(--r, 8px); overflow: hidden; min-height: 140px; }
.theme-gallery__detail-meta {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.theme-gallery__detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}
.theme-gallery__detail-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex-wrap: wrap;
}
.theme-gallery__detail-title-row h3 { margin: 0; }
.theme-gallery__detail-name { margin: 0; font-size: var(--text-md, 1rem); }
.theme-gallery__detail-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border: 1px solid color-mix(in srgb, var(--ok, #3d9a6a) 35%, transparent);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--ok, #3d9a6a) 13%, transparent);
  color: var(--ok, #3d9a6a);
  font-size: var(--text-sm, 0.8125rem);
  font-weight: 600;
  white-space: nowrap;
}
.theme-gallery__detail-status--preview {
  border-color: color-mix(in srgb, var(--accent) 38%, transparent);
  background: color-mix(in srgb, var(--accent) 14%, transparent);
  color: var(--accent);
}
.theme-gallery__detail-tags { display: flex; gap: 6px; flex-wrap: wrap; }
.theme-gallery__badge {
  display: inline-flex; align-items: center;
  padding: 2px 8px; border-radius: 999px;
  font-size: var(--text-sm, 0.8125rem);
  background: color-mix(in srgb, var(--accent) 18%, transparent);
  color: var(--fg);
  border: 1px solid color-mix(in srgb, var(--accent) 35%, transparent);
}
.theme-gallery__badge--muted {
  background: var(--bg-soft);
  border-color: var(--border-soft);
  color: var(--fg-dim);
}
.theme-gallery__detail-desc {
  margin: 0;
  font-size: var(--text-base, 0.875rem);
  color: var(--fg-dim);
  line-height: 1.45;
}
.theme-gallery__detail-palette {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.theme-gallery__detail-swatches { display: flex; gap: 6px; }
.theme-gallery__detail-swatches span {
  width: 16px; height: 16px; border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--fg) 12%, transparent);
}
.theme-gallery__preview-controls {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.theme-gallery__preview-control {
  display: grid;
  grid-template-columns: minmax(76px, auto) minmax(0, 1fr);
  align-items: center;
  gap: 10px;
}
.theme-gallery__preview-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--fg-dim);
  font-size: var(--text-sm, 0.8125rem);
  white-space: nowrap;
}
.theme-gallery__preview-help {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--fg-faint);
  cursor: help;
}
.theme-gallery__preview-help:hover { color: var(--fg); }
.theme-gallery__preview-help:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}
.theme-gallery__preview-control .set-seg {
  display: flex;
  width: 100%;
}
.theme-gallery__preview-control .set-seg__btn {
  flex: 1;
  min-width: 0;
  cursor: pointer;
}
.theme-gallery__preview-control .set-seg__btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.theme-gallery__apply { width: 100%; }
.theme-gallery__detail-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.theme-gallery__detail-actions > .btn {
  width: 100%;
  min-width: 0;
  justify-content: center;
}
.theme-gallery__detail-user-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.theme-gallery__detail-user-actions > .btn {
  min-width: 0;
  justify-content: center;
}
.theme-gallery__detail-more > .btn { width: 100%; justify-content: center; }
.theme-gallery__detail-more .theme-gallery__menu { left: 0; right: 0; min-width: 0; }
.theme-gallery__more { position: relative; }
.theme-gallery__menu {
  position: absolute; right: 0; top: calc(100% + 4px); z-index: var(--z-local-popover);
  min-width: 160px; padding: 6px;
  border: 1px solid var(--border); border-radius: var(--r, 8px);
  box-shadow: 0 8px 24px color-mix(in srgb, #000 28%, transparent);
  display: flex; flex-direction: column; gap: 2px;
}
.theme-gallery__menu button {
  display: flex; align-items: center; gap: 8px;
  border: 0; background: transparent; color: var(--fg);
  padding: 8px 10px; border-radius: 6px; cursor: pointer;
  font-size: var(--text-base, 0.875rem); text-align: left;
}
.theme-gallery__menu button:hover { background: var(--bg-soft); }
.theme-gallery__menu-danger { color: var(--err, #e55) !important; }
.theme-gallery__editor-overlay {
  position: fixed; inset: 0; z-index: var(--z-modal);
  background: color-mix(in srgb, #000 58%, transparent);
  display: grid; place-items: center; padding: 20px;
  overflow: hidden;
  -webkit-app-region: no-drag;
}
.theme-gallery__editor {
  width: min(1180px, 100%);
  height: min(88vh, 860px);
  height: min(88dvh, 860px);
  max-height: calc(100vh - 40px);
  max-height: calc(100dvh - 40px);
  overflow: hidden;
  border-radius: var(--r-l, 12px);
  padding: 0; border: 1px solid var(--border);
  box-shadow: 0 24px 72px color-mix(in srgb, #000 42%, transparent);
  container: theme-editor / inline-size;
}

/* Isolated preview surface */
.theme-preview-surface {
  position: relative;
  min-height: 160px;
  border-radius: var(--r, 8px);
  overflow: hidden;
  background: var(--tp-bg, #111);
  color: var(--tp-fg, #fff);
}
.theme-preview-surface__bg {
  position: absolute; inset: 0;
  background-size: cover;
  background-position: var(--tp-focus-x, 72%) var(--tp-focus-y, 45%);
  opacity: var(--tp-bg-opacity, 1);
}
.theme-preview-surface__bg--swatch {
  background: linear-gradient(135deg, var(--tp-bg), var(--tp-accent));
}
.theme-preview-surface__bg--base {
  background:
    radial-gradient(circle at 82% 18%, color-mix(in srgb, var(--tp-accent) 13%, transparent), transparent 34%),
    var(--tp-bg);
  opacity: 1;
}
.theme-preview-surface__overlay {
  position: absolute; inset: 0;
  background: color-mix(in srgb, var(--tp-bg) calc(var(--tp-overlay, 0.6) * 70%), transparent);
  pointer-events: none;
}
.theme-preview-surface[data-scene="home"] .theme-preview-surface__overlay { opacity: 0.25; }
.theme-preview-surface[data-preview-kind="base"] .theme-preview-surface__overlay { display: none; }
.theme-preview-surface__chrome {
  position: relative; z-index: var(--z-app-content);
  display: grid; grid-template-columns: 56px 1fr;
  min-height: 160px;
}
.theme-preview-surface__side {
  background: color-mix(in srgb, var(--tp-sidebar) var(--tp-pane-shell-pct, 80%), transparent);
  border-right: 1px solid color-mix(in srgb, var(--tp-border) 70%, transparent);
  padding: 10px 8px; display: flex; flex-direction: column; gap: 8px;
}
.theme-preview-surface__logo {
  width: 28px; height: 28px; border-radius: min(var(--tp-radius, 8px), 10px);
  background: var(--tp-accent); color: var(--tp-accent-fg);
  display: grid; place-items: center; font-weight: 700; font-size: var(--text-sm);
}
.theme-preview-surface__nav {
  height: 8px; border-radius: 4px;
  background: color-mix(in srgb, var(--tp-fg) 18%, transparent);
}
.theme-preview-surface__nav--dim { opacity: 0.5; width: 70%; }
.theme-preview-surface__main {
  min-width: 0;
  padding: 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.theme-preview-surface__card {
  width: min(220px, 90%);
  background: color-mix(in srgb, var(--tp-panel) var(--tp-pane-card-pct, 88%), transparent);
  border: 1px solid color-mix(in srgb, var(--tp-border) 80%, transparent);
  border-radius: var(--tp-radius, 10px); padding: 12px; display: flex; flex-direction: column; gap: 8px;
}
.theme-preview-surface__title { height: 10px; width: 55%; border-radius: 4px; background: color-mix(in srgb, var(--tp-fg) 22%, transparent); }
.theme-preview-surface__line { height: 6px; border-radius: 3px; background: color-mix(in srgb, var(--tp-fg-dim) 35%, transparent); }
.theme-preview-surface__line--short { width: 70%; }
.theme-preview-surface__cta {
  margin-top: 4px; height: 22px; width: 72px; border-radius: 6px;
  background: var(--tp-accent);
}
.theme-preview-surface[data-variant="full"] .theme-preview-surface__chrome { min-height: 280px; }
.theme-preview-surface__code-island {
  width: min(360px, 92%);
  overflow: hidden;
  border: 1px solid var(--tp-code-border);
  border-radius: min(var(--tp-radius, 8px), 9px);
  background: var(--tp-code-bg);
  color: var(--tp-code-fg);
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.5;
  box-shadow: 0 8px 22px color-mix(in srgb, var(--tp-bg) 38%, transparent);
}
.theme-preview-surface__code-label {
  padding: 5px 8px;
  border-bottom: 1px solid var(--tp-code-border);
  color: color-mix(in srgb, var(--tp-code-fg) 72%, var(--tp-code-bg));
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
}
.theme-preview-surface__code-line {
  display: block;
  overflow: hidden;
  padding: 7px 8px;
  color: var(--tp-code-fg);
  font: inherit;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.theme-preview-surface__syntax--keyword { color: var(--tp-hl-keyword); }
.theme-preview-surface__syntax--string { color: var(--tp-hl-string); }
.theme-preview-surface__syntax--number { color: var(--tp-hl-number); }
.theme-preview-surface__syntax--comment { color: var(--tp-hl-comment); font-style: italic; }
.theme-preview-surface__syntax--func { color: var(--tp-hl-func); }
.theme-preview-surface__syntax--type { color: var(--tp-hl-type); }
.theme-preview-surface__diff-line {
  display: grid;
  grid-template-columns: 14px minmax(0, 1fr);
  padding: 3px 8px;
  border-top: 1px solid var(--tp-code-border);
  color: var(--tp-code-fg);
}
.theme-preview-surface__diff-line--add {
  background: var(--tp-code-add-bg);
  color: var(--tp-add-fg);
}
.theme-preview-surface__diff-line--del {
  background: var(--tp-code-del-bg);
  color: var(--tp-del-fg);
}
.theme-preview-surface[data-preview-kind="base"] .theme-preview-surface__card {
  box-shadow: 0 10px 28px color-mix(in srgb, var(--tp-bg) 52%, transparent);
}
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__chrome {
  grid-template-columns: 22% 1fr;
  min-height: 100%;
}
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__side {
  padding: 8% 10%;
  gap: 8%;
}
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__logo {
  width: clamp(12px, 18%, 24px);
  height: auto;
  aspect-ratio: 1;
  border-radius: min(var(--tp-radius, 8px), 7px);
  font-size: 0;
}
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__logo::after {
  content: "R";
  font-size: clamp(5px, 1.1vw, 10px);
}
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__nav {
  height: 5%;
  min-height: 2px;
}
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__main { padding: 8%; }
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__card {
  width: 78%;
  padding: 6%;
  gap: 6%;
}
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__title { height: 7%; min-height: 3px; }
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__line { height: 4%; min-height: 2px; }
.theme-preview-surface[data-variant="thumbnail"] .theme-preview-surface__cta {
  width: 38%;
  height: 16%;
  min-height: 5px;
  margin-top: 2%;
}

/* Immersive preview layout */
.theme-gallery--immersive .theme-gallery__immersive-body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: 12px;
  min-height: 420px;
}
.theme-gallery--immersive .theme-preview-surface { min-height: 420px; }
.theme-gallery__immersive-toolbar {
  display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap;
}
.theme-gallery__immersive-toolbar .theme-gallery__preview-controls {
  display: grid;
  grid-template-columns: repeat(2, minmax(220px, 1fr));
  gap: 12px;
  width: 100%;
}
.theme-gallery__immersive-rail {
  display: flex; flex-direction: column; gap: 10px;
  padding: 12px; border: 1px solid var(--border-soft);
  border-radius: var(--r-l, 12px); background: var(--bg-elev);
  max-height: 70vh; overflow: auto;
}
.theme-gallery__rail-list { display: flex; flex-direction: column; gap: 14px; }
.theme-gallery__rail-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.theme-gallery__rail-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 0 2px;
  color: var(--fg-dim);
  font-size: var(--text-xs, 0.75rem);
  font-weight: 600;
}
.theme-gallery__rail-section-count {
  color: var(--fg-faint);
  font-variant-numeric: tabular-nums;
}
.theme-gallery__rail-section-items {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.theme-gallery__rail-card {
  display: grid; grid-template-columns: 72px 1fr; gap: 8px; align-items: center;
  padding: 6px; border: 1px solid var(--border-soft); border-radius: 8px;
  background: transparent; color: inherit; cursor: pointer; text-align: left;
  font-size: var(--text-sm, 0.8125rem);
}
.theme-gallery__rail-card img, .theme-gallery__rail-fallback,
.theme-gallery__rail-card > .theme-preview-surface {
  width: 72px; height: 40px; object-fit: cover; border-radius: 4px; display: block;
  background: var(--bg-soft);
}
.theme-gallery__rail-card > .theme-preview-surface { min-height: 0; }
.theme-gallery__rail-card--on { border-color: var(--accent); }

@media (max-width: 900px) {
  .theme-gallery__body,
  .theme-gallery--immersive .theme-gallery__immersive-body {
    grid-template-columns: 1fr;
  }
}

/* The settings navigation consumes part of the window width, so gallery
/* The settings navigation consumes part of the window width, so gallery
   responsiveness must follow its own content box rather than the viewport. */
@container theme-gallery (max-width: 760px) {
  .theme-gallery__body,
  .theme-gallery--immersive .theme-gallery__immersive-body {
    grid-template-columns: 1fr;
  }

  .theme-gallery__detail {
    order: -1;
    position: static;
  }

  .theme-gallery__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@container theme-gallery (max-width: 480px) {
  .theme-gallery__grid {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .theme-gallery-card,
  .theme-gallery__tab,
  .appearance-overview__hero {
    transition: none !important;
  }
}

/* Editor shell */
.theme-editor {
  display: flex;
  flex-direction: column;
  gap: calc(var(--theme-density-gap, 10px) + 4px);
  padding: calc(var(--theme-density-pad, 10px) + 2px);
  border: 1px solid var(--border-soft, var(--border));
  border-radius: var(--r, 8px);
  background: var(--bg-soft, var(--bg-elev-2));
}

.theme-editor__row {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: var(--theme-density-gap, 10px);
  align-items: start;
}

.theme-editor__label {
  font-size: var(--text-sm);
  color: var(--fg-dim, var(--text-2));
  padding-top: 6px;
}

.theme-editor__fields {
  display: flex;
  flex-direction: column;
  gap: var(--theme-density-gap, 8px);
  min-width: 0;
}

.theme-editor__color-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: var(--theme-density-gap, 8px);
}

.theme-editor__color {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: var(--text-xs);
  color: var(--fg-dim);
}

.theme-editor__color input[type="color"] {
  width: 100%;
  height: 28px;
  padding: 0;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: transparent;
  cursor: pointer;
}

.theme-editor__color input[type="text"] {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: var(--text-xs);
  padding: 4px 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-soft);
  background: var(--bg-elev);
  color: var(--fg);
}

.theme-editor__bg-preview {
  position: relative;
  height: 140px;
  border-radius: var(--r, 8px);
  border: 1px solid var(--border-soft);
  background: var(--bg-soft);
  background-size: cover;
  background-position: center;
  overflow: hidden;
  cursor: crosshair;
  user-select: none;
}

.theme-editor__focus {
  position: absolute;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border-radius: 50%;
  border: 2px solid #fff;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.55);
  pointer-events: none;
}

.theme-editor__warn {
  font-size: var(--text-sm);
  color: var(--warn);
  background: color-mix(in srgb, var(--warn) 12%, transparent);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
}

.theme-editor__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

/* Full theme editor used by the redesigned gallery. */
.theme-gallery__editor.theme-editor { gap: 0; }
.theme-editor__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--border-soft);
}
.theme-editor__header strong { font-size: var(--text-lg, 1rem); }
.theme-editor__header p,
.theme-editor__live p,
.theme-editor__scene-head p,
.theme-editor__section-help {
  margin: 4px 0 0;
  color: var(--fg-dim);
  font-size: var(--text-xs, 0.75rem);
  line-height: 1.45;
}
.theme-editor__body {
  min-height: 0;
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 350px;
  overflow: hidden;
}
.theme-editor__controls {
  min-width: 0;
  overflow-y: auto;
  padding: 18px 20px 32px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.theme-editor__section {
  padding: 16px;
  border: 1px solid var(--border-soft);
  border-radius: var(--r, 8px);
  background: color-mix(in srgb, var(--bg-soft) 72%, transparent);
}
.theme-editor__section h3,
.theme-editor__section h4 { margin: 0; }
.theme-editor__section h3 { font-size: var(--text-base, 0.875rem); }
.theme-editor__section h4 {
  color: var(--fg-dim);
  font-size: var(--text-xs, 0.75rem);
  font-weight: 600;
}
.theme-editor__section-head,
.theme-editor__setting-row,
.theme-editor__scene-head,
.theme-editor__live-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.theme-editor__setting-row { margin-top: 12px; }
.theme-editor__setting-row > span {
  flex: 0 0 104px;
  color: var(--fg-dim);
  font-size: var(--text-xs, 0.75rem);
}
.theme-editor__setting-row > .set-seg,
.theme-editor__setting-row > .theme-editor__recipe-groups { flex: 1; min-width: 0; }
.theme-editor__recipe-groups { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.theme-editor__recipe-groups .set-seg,
.theme-editor__base-styles { width: 100%; }
.theme-editor__recipe-groups .set-seg__btn,
.theme-editor__base-styles .set-seg__btn,
.theme-editor__setting-row .set-seg__btn { flex: 1; min-width: 0; }
.theme-editor__fields--grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 12px;
}
.theme-editor__fields--grid label { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.theme-editor__fields--grid label > span { color: var(--fg-dim); font-size: var(--text-xs, 0.75rem); }
.theme-editor__fields--grid input,
.theme-editor__fields--grid textarea {
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid var(--border-soft);
  border-radius: var(--r-s, 5px);
  background: var(--bg-elev);
  color: var(--fg);
  font: inherit;
}
.theme-editor__wide { grid-column: 1 / -1; }
.theme-editor__token-group { margin-top: 14px; display: flex; flex-direction: column; gap: 8px; }
.theme-editor__color-control { display: grid; grid-template-columns: 34px minmax(0, 1fr); gap: 5px; }
.theme-editor__token-label { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.theme-editor__token-label > span { color: var(--fg); }
.theme-editor__token-label code { color: var(--fg-faint); font-size: 10px; }
.theme-editor__color-control input[type="color"] { width: 34px; height: 30px; }
.theme-editor__color-control input[type="text"] { min-width: 0; }
.theme-editor__scene-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 12px; }
.theme-editor__scene {
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--border-soft);
  border-radius: var(--r, 8px);
  background: var(--bg-elev);
}
.theme-editor__scene--ready { border-color: color-mix(in srgb, var(--accent) 42%, var(--border-soft)); }
.theme-editor__scene-head { align-items: flex-start; margin-bottom: 10px; }
.theme-editor__scene-head strong { font-size: var(--text-sm, 0.8125rem); }
.theme-editor__scene-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 6px; }
.theme-editor__scene-actions .btn { white-space: nowrap; }
.theme-editor__scene .theme-editor__bg-preview { height: 150px; }
.theme-editor__scene-empty {
  position: absolute; inset: 0;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px;
  color: var(--fg-faint); font-size: var(--text-xs, 0.75rem); text-align: center;
}
.theme-editor__scene-controls { display: flex; flex-direction: column; gap: 10px; margin-top: 10px; }
.theme-editor__scene-controls .theme-editor__setting-row { margin: 0; }
.theme-editor__scene-controls .theme-editor__setting-row > span { flex-basis: 86px; }
.theme-editor__setting-block { min-width: 0; }
.theme-editor__setting-hint {
  margin: 5px 0 0 98px;
  color: var(--fg-faint);
  font-size: var(--text-2xs, 0.6875rem);
  line-height: 1.45;
}
.theme-editor__range { display: flex; flex-direction: column; gap: 5px; color: var(--fg-dim); font-size: var(--text-xs, 0.75rem); }
.theme-editor__range span { display: flex; justify-content: space-between; }
.theme-editor__range b { color: var(--fg); font-variant-numeric: tabular-nums; }
.theme-editor__live {
  min-width: 0;
  padding: 18px;
  border-left: 1px solid var(--border-soft);
  overflow-y: auto;
}
.theme-editor__live-head { margin-bottom: 12px; }
.theme-editor__live-head span { color: var(--fg-dim); font-size: var(--text-xs, 0.75rem); }
.theme-editor__live .theme-gallery__preview-controls { display: grid; grid-template-columns: 1fr; gap: 10px; }
.theme-editor__live .theme-preview-surface { min-height: 280px; margin-top: 14px; }
.theme-gallery__editor > .theme-editor__actions {
  flex: 0 0 auto;
  padding: 12px 20px;
  border-top: 1px solid var(--border-soft);
}

/* Operational surfaces share one background recipe, including menus whose
   component CSS is loaded lazily and popovers portaled directly to body. */
.anchored-popover,
.slashmenu,
.composer-access-menu,
.jobs-popover,
.modelsw__menu,
.workspace-recent-menu,
.floating-menu,
.mem-ws-select__menu,
.menu,
.settings-select-menu,
.external-opener__menu,
.context-menu,
.theme-gallery__menu,
.theme-gallery__editor,
.theme-editor__header,
.theme-editor__live,
.theme-gallery__editor > .theme-editor__actions,
.provider-access-more__menu,
.topicbar__export-menu,
.heartbeat-filter-menu,
.heartbeat-project-menu,
.heartbeat-task-menu {
  background: var(--overlay-surface-bg);
}
.theme-editor__warn ul { margin: 6px 0 0; padding-left: 18px; }

@container theme-editor (max-width: 920px) {
  .theme-editor__body { grid-template-columns: 1fr; overflow-y: auto; }
  .theme-editor__controls { overflow: visible; }
  .theme-editor__live { border-left: 0; border-top: 1px solid var(--border-soft); }
  .theme-editor__scene-grid { grid-template-columns: 1fr; }
}

@container theme-editor (max-width: 620px) {
  .theme-editor__fields--grid,
  .theme-editor__recipe-groups { grid-template-columns: 1fr; }
  .theme-editor__setting-row { align-items: flex-start; flex-direction: column; }
  .theme-editor__setting-row > span { flex-basis: auto; }
  .theme-editor__setting-hint { margin-left: 0; }
  .theme-editor__base-styles {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .theme-gallery__editor > .theme-editor__actions .btn { flex: 1 1 140px; }
}

@container theme-editor (max-width: 420px) {
  .theme-editor__base-styles { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .theme-editor__header,
  .theme-editor__controls,
  .theme-editor__live,
  .theme-gallery__editor > .theme-editor__actions { padding-left: 12px; padding-right: 12px; }
}

@media (max-width: 620px) {
  .theme-gallery__editor-overlay { padding: 8px; }
  .theme-gallery__editor {
    max-height: calc(100vh - 16px);
    max-height: calc(100dvh - 16px);
  }
}

/* Restore-default control must stay readable even under broken packs */
.theme-reset-btn {
  color: #111827 !important;
  background: #f3f4f6 !important;
  border: 1px solid #d1d5db !important;
}
:root[data-theme="dark"] .theme-reset-btn,
:root:not([data-theme]) .theme-reset-btn {
  color: #f9fafb !important;
  background: #1f2937 !important;
  border-color: #4b5563 !important;
}

@media (prefers-color-scheme: light) {
  :root:not([data-theme]) .theme-reset-btn {
    color: #111827 !important;
    background: #f3f4f6 !important;
    border: 1px solid #d1d5db !important;
  }
}

/* ── Remote SSH module ──────────────────────────────────────────────────── */
.remote-hosts__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 12px;
}
.remote-hosts__actions {
  display: flex;
  gap: 8px;
}
.remote-hosts__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.remote-hosts__empty,
.remote-panel__hint {
  color: var(--fg-faint);
  font-size: var(--text-sm);
}
.remote-hosts__legacy {
  margin-top: 18px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-elev);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.remote-hosts__legacy h3 {
  margin: 0;
  font-size: var(--text-md);
  color: var(--fg);
}
.remote-hosts__legacy p {
  margin: 0;
  font-size: var(--text-sm);
  color: var(--fg-faint);
}
.remote-hosts__legacy-actions {
  display: flex;
  gap: 8px;
  margin-top: 4px;
}
.remote-host-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  background: var(--bg-elev);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
}
.remote-host-row__main {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.remote-host-row__name {
  font-weight: 600;
}
.remote-host-row__target {
  color: var(--fg-faint);
  font-size: var(--text-sm);
}
.remote-host-row__actions {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}
.remote-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 8px;
  border-radius: var(--radius-pill);
  font-size: var(--text-xs);
  border: 1px solid var(--border);
  color: var(--fg-dim);
  background: var(--bg-soft);
  flex-shrink: 0;
  white-space: nowrap;
}
.remote-chip--connected {
  color: var(--ok);
  border-color: color-mix(in srgb, var(--ok) 50%, var(--border));
}
.remote-chip--stopped {
  color: var(--fg-faint);
}
.remote-chip--connecting {
  color: var(--fg-dim);
}
.remote-chip--reconnecting,
.remote-chip--pending_hostkey,
.remote-chip--pending_secret,
.remote-chip--degraded {
  color: var(--warn);
  border-color: color-mix(in srgb, var(--warn) 50%, var(--border));
}
.remote-chip--error {
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 50%, var(--border));
}
.remote-host-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 480px;
}
.remote-host-form label,
.remote-server__ws {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: var(--text-sm);
  color: var(--fg-dim);
}
.remote-host-form input,
.remote-host-form select,
.remote-server__ws input,
.remote-ports__form input {
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--fg);
  padding: 6px 8px;
}
.remote-host-form__actions,
.remote-server__actions,
.remote-ports__form {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
}
.remote-host-form__credential {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.remote-host-form__credential-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.remote-host-form__credential-meta .btn {
  flex-shrink: 0;
}
.remote-host-form__error,
.remote-panel__error {
  color: var(--danger);
  font-size: var(--text-sm);
}
.remote-panel__error--warning {
  color: var(--warn);
}
.remote-panel {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  background: var(--bg);
}
.remote-panel__header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 54px;
  padding: 9px 12px;
  border-bottom: 1px solid var(--border-soft);
}
.remote-panel__host-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  flex: 1;
  gap: 1px;
}
.remote-panel__host {
  font-weight: 600;
}
.remote-panel__target {
  max-width: 220px;
  overflow: hidden;
  color: var(--fg-faint);
  font-size: var(--text-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.remote-panel__header-actions {
  width: 100%;
  margin-left: 0;
  display: flex;
  justify-content: flex-end;
  gap: 6px;
}
.remote-panel__error-banner {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--danger) 30%, var(--border-soft));
  background: color-mix(in srgb, var(--danger) 10%, var(--bg));
  color: var(--danger);
  font-size: var(--text-xs);
}
.remote-panel__error-banner--warning {
  border-bottom-color: color-mix(in srgb, var(--warn) 30%, var(--border-soft));
  background: color-mix(in srgb, var(--warn) 10%, var(--bg));
  color: var(--warn);
}
.remote-panel__banner {
  padding: 6px 12px;
  background: color-mix(in srgb, var(--warn) 18%, var(--bg-elev));
  color: var(--warn);
  font-size: var(--text-sm);
}
.remote-panel__tabs {
  display: flex;
  gap: 2px;
  padding: 6px 8px;
  border-bottom: 1px solid var(--border-soft);
}
.remote-panel__tab {
  background: transparent;
  border: none;
  color: var(--fg-faint);
  padding: 4px 10px;
  border-radius: var(--radius);
  cursor: pointer;
}
.remote-panel__tab.is-active {
  background: var(--bg-elev-2);
  color: var(--fg);
}
.remote-panel__body {
  flex: 1;
  overflow: auto;
  padding: 10px 12px;
}
.workbench-dock__body > .remote-panel {
  min-height: 0;
}
.remote-files {
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: 100%;
}
.remote-files__tree ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
.remote-tree__row {
  display: block;
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: var(--fg-dim);
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: var(--text-sm);
}
.remote-tree__row.is-selected {
  background: var(--bg-elev-2);
  color: var(--fg);
}
.remote-tree__empty {
  color: var(--fg-faint);
  font-size: var(--text-xs);
  padding: 2px 4px;
}
.remote-file-view__toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}
.remote-file-view__path {
  font-family: var(--font-mono, monospace);
  font-size: var(--text-xs);
  color: var(--fg-faint);
  overflow: hidden;
  text-overflow: ellipsis;
}
.remote-file-view__editor {
  width: 100%;
  min-height: 320px;
