}
.remote-switcher__host-main {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: 9px;
  padding: 4px 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.remote-switcher__state {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
