}
.remote-switcher__state--connected { background: var(--ok); }
.remote-switcher__state--connecting,
.remote-switcher__state--reconnecting,
.remote-switcher__state--pending_hostkey,
.remote-switcher__state--pending_secret,
.remote-switcher__state--degraded { background: var(--warn); }
.remote-switcher__state--error { background: var(--danger); }
.remote-switcher__manage {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 7px;
  padding: 10px 12px;
  border: 0;
  border-top: 1px solid var(--border-soft);
  background: transparent;
  color: var(--accent-strong);
  font: inherit;
  font-size: var(--text-sm);
  text-align: left;
  cursor: pointer;
}
.remote-switcher__manage:hover,
.remote-switcher__manage:focus-visible {
  outline: none;
  background: var(--bg-elev-2);
}
/* Task Monitor panel. The Codex-style popover keeps the chat composer clear. */
.taskmonitor-popover { position:absolute; top:calc(100% + 8px); right:0; width:min(440px, calc(100vw - 32px)); max-height:min(72vh, 680px); z-index:var(--z-dock); border:1px solid var(--border,#333); border-radius:10px; background:var(--overlay-surface-bg, var(--bg,#111)); box-shadow:0 14px 36px rgba(0,0,0,.42); overflow:hidden; }
.taskmonitor { background:var(--bg,#111); }
.taskmonitor--popover { max-height:inherit; background:transparent; }
.taskmonitor__head { display:flex; align-items:center; gap:6px; width:100%; padding:8px 12px; font-size: var(--text-md); }
.taskmonitor__toggle,.taskmonitor__refresh,.taskmonitor__close { display:inline-flex; align-items:center; justify-content:center; width:28px; height:28px; padding:0; border:0; border-radius:6px; background:none; color:inherit; cursor:pointer; }
.taskmonitor__toggle:hover,.taskmonitor__refresh:hover,.taskmonitor__close:hover,.taskmonitor__toggle:focus-visible,.taskmonitor__refresh:focus-visible,.taskmonitor__close:focus-visible { background:var(--bg-elev-2); outline:none; }
.taskmonitor__title { flex:1; text-align:left; font-weight:600; }
.taskmonitor__count { background:var(--muted,#555); color:#fff; border-radius:10px; padding:0 6px; font-size: var(--text-xs); line-height:18px; }
.taskmonitor__body { max-height:360px; overflow-y:auto; }
.taskmonitor--popover .taskmonitor__body { max-height:calc(min(72vh, 680px) - 44px); }
.taskmonitor__category-title { padding:10px 16px 4px; color:var(--fg-dim,#aaa); font-size: var(--text-xs); font-weight:650; text-transform:uppercase; letter-spacing:.06em; }
.taskmonitor__state { display:flex; align-items:center; gap:8px; padding:16px; font-size: var(--text-md); color:var(--muted,#888); }
.taskmonitor__state--error { color:#ef4444; }
.taskmonitor__task { border-bottom:1px solid var(--border,#2a2a2a); }
.taskmonitor__task-head { display:flex; align-items:center; }
.taskmonitor__expand { display:flex; align-items:center; gap:6px; width:100%; min-height:32px; padding:6px 12px; background:none; border:0; color:inherit; cursor:pointer; font-size: var(--text-sm); }
.taskmonitor__expand:hover,.taskmonitor__expand:focus-visible { background:var(--bg-elev-2); outline:none; }
.taskmonitor__dot { font-size:10px; width:14px; text-align:center; }
.taskmonitor__id { font-family:monospace; font-size: var(--text-xs); color:var(--muted,#888); }
.taskmonitor__badge { font-size:10px; padding:1px 6px; border-radius:8px; font-weight:600; text-transform:uppercase; }
.taskmonitor__runtime { display:inline-flex; align-items:center; gap:3px; font-size:10px; }
.taskmonitor__time { margin-left:auto; font-size: var(--text-xs); color:var(--muted,#666); }
.taskmonitor__detail { padding:6px 12px 10px 32px; font-size: var(--text-sm); }
.taskmonitor__detail dl { margin:0; display:grid; grid-template-columns:80px 1fr; gap:2px 8px; }
.taskmonitor__detail dt { color:var(--muted,#888); }
.taskmonitor__detail dd { margin:0; }
.taskmonitor__events { margin-top:8px; border-top:1px solid var(--border,#333); padding-top:6px; }
.taskmonitor__event { display:flex; gap:8px; line-height:20px; }
.taskmonitor__actions { display:flex; gap:8px; margin-top:10px; }
.taskmonitor__actions button,.taskmonitor__confirm button { min-height:32px; padding:0 12px; border:1px solid var(--border,#555); border-radius:6px; background:var(--surface,#222); color:inherit; cursor:pointer; }
.taskmonitor__actions button:hover:not(:disabled),.taskmonitor__confirm button:hover:not(:disabled),.taskmonitor__actions button:focus-visible,.taskmonitor__confirm button:focus-visible { border-color:var(--accent); outline:2px solid color-mix(in srgb,var(--accent) 38%,transparent); outline-offset:1px; }
.taskmonitor__actions button:disabled,.taskmonitor__confirm button:disabled { cursor:not-allowed; opacity:.55; }
.taskmonitor__actions .taskmonitor__stop { border-color:color-mix(in srgb,var(--danger,#ef4444) 48%,var(--border)); color:var(--danger,#ef4444); }
.taskmonitor__confirm { display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-top:10px; padding:10px 12px; border:1px solid color-mix(in srgb,var(--danger,#ef4444) 30%,var(--border)); border-radius:8px; background:color-mix(in srgb,var(--danger,#ef4444) 7%,var(--surface,#222)); }
.taskmonitor__confirm-copy { flex:1 1 150px; font-weight:600; line-height:1.4; }
.taskmonitor__confirm-actions { display:flex; gap:8px; }
.taskmonitor__confirm .taskmonitor__confirm-stop { border-color:var(--danger,#ef4444); background:var(--danger,#ef4444); color:#fff; font-weight:650; }
.taskmonitor__confirm .taskmonitor__confirm-stop:hover:not(:disabled),.taskmonitor__confirm .taskmonitor__confirm-stop:focus-visible { border-color:var(--danger,#ef4444); outline-color:color-mix(in srgb,var(--danger,#ef4444) 42%,transparent); }
.taskmonitor__error { color:#ef4444; margin-top:6px; }
.taskmonitor__message { color:#4ade80; margin-top:6px; }

/* Integrated terminal */
:root {
  --terminal-bg: var(--bg);
  --terminal-fg: var(--fg);
  --terminal-surface: var(--bg-elev);
  --terminal-active: var(--bg-elev-2);
  --terminal-border: var(--border-soft);
  --terminal-muted: var(--fg-dim);
  --terminal-faint: var(--fg-faint);
  --terminal-cursor: var(--accent);
  --terminal-selection: color-mix(in srgb, var(--accent) 28%, transparent);
  /* Auto mode leaves selectionForeground unset: xterm keeps the natural
     foreground, which stays readable over the selection tint on both light
     and dark app themes. */
}
:root[data-terminal-theme="dark"] {
  --terminal-bg: #111315;
  --terminal-fg: #e8e5df;
  --terminal-surface: #17191b;
  --terminal-active: #22262a;
  --terminal-border: #292d31;
  --terminal-muted: #a7a19a;
  --terminal-faint: #70777f;
  --terminal-cursor: #e6a15c;
  --terminal-selection: #4a6d8c;
  --terminal-selection-fg: #ffffff;
}
:root[data-terminal-theme="light"] {
  --terminal-bg: #f7f8fa;
  --terminal-fg: #25272a;
  --terminal-surface: #eef0f3;
  --terminal-active: #e1e5ea;
  --terminal-border: #cfd4da;
  --terminal-muted: #5f6670;
  --terminal-faint: #8b929b;
  --terminal-cursor: #9a4f00;
  --terminal-selection: #6ea8fe;
  --terminal-selection-fg: #0b0f14;
}
:root[data-terminal-theme="dark"] .terminal-panel { color-scheme: dark; }
:root[data-terminal-theme="light"] .terminal-panel { color-scheme: light; }
.workbench-dock--terminal { min-width: 0; }
.terminal-panel { display: flex; flex-direction: column; height: 100%; min-width: 0; background: var(--terminal-bg); color: var(--terminal-fg); }
.terminal-panel__header { display: flex; align-items: center; justify-content: space-between; min-height: 38px; padding: 0 10px; border-bottom: 1px solid var(--terminal-border); background: var(--terminal-surface); }
.terminal-panel__identity, .terminal-panel__actions { display: flex; align-items: center; gap: 8px; min-width: 0; }
.terminal-panel__identity { flex: 1; overflow: hidden; }
.terminal-panel__actions { flex: 0 1 auto; gap: 4px; }
.terminal-panel__identity strong { font-size: var(--text-sm); font-weight: 650; }
.terminal-panel__identity span { max-width: 180px; overflow: hidden; color: var(--terminal-muted); font: 11px ui-monospace, SFMono-Regular, Menlo, monospace; text-overflow: ellipsis; white-space: nowrap; }
.terminal-shell-select { width: 132px; max-width: 30vw; min-width: 0; height: 28px; padding: 0 24px 0 8px; border: 1px solid var(--terminal-border); border-radius: 5px; background: var(--terminal-active); color: var(--terminal-fg); font: inherit; font-size: var(--text-xs); text-overflow: ellipsis; cursor: pointer; }
.terminal-shell-select:hover, .terminal-shell-select:focus-visible { border-color: var(--terminal-cursor); outline: none; }
.terminal-shell-select:disabled { cursor: not-allowed; opacity: .45; }
.terminal-icon-button { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; padding: 0; border: 1px solid transparent; border-radius: 5px; background: transparent; color: var(--terminal-muted); cursor: pointer; }
.terminal-icon-button:hover, .terminal-icon-button:focus-visible { border-color: var(--terminal-border); background: var(--terminal-active); color: var(--terminal-fg); outline: none; }
.terminal-icon-button:disabled { cursor: not-allowed; opacity: .45; }
.terminal-panel__body { display: flex; min-height: 0; flex: 1; flex-direction: column; }
.terminal-error { display: flex; align-items: center; gap: 7px; min-width: 0; padding: 6px 10px; border-bottom: 1px solid color-mix(in srgb, var(--danger) 35%, var(--terminal-border)); background: color-mix(in srgb, var(--danger) 10%, var(--terminal-surface)); color: var(--terminal-muted); font-size: var(--text-xs); }
.terminal-error > span { min-width: 0; flex: 1; overflow-wrap: anywhere; }
.terminal-error > svg { flex: 0 0 auto; color: var(--danger); }
.terminal-session-rail { display: flex; min-width: 0; flex: 0 0 34px; align-items: center; border-bottom: 1px solid var(--terminal-border); background: var(--terminal-surface); }
.terminal-session-rail__list { display: flex; min-width: 0; flex: 1; overflow-x: auto; overflow-y: hidden; padding: 3px 5px; }
.terminal-session { display: flex; min-width: 96px; max-width: 180px; flex: 0 1 180px; align-items: center; min-height: 28px; border-bottom: 2px solid transparent; }
.terminal-session--active { border-bottom-color: var(--terminal-cursor); background: var(--terminal-active); }
.terminal-session__select { display: flex; align-items: center; gap: 7px; min-width: 0; flex: 1; height: 30px; padding: 0 7px; border: 0; background: transparent; color: var(--terminal-muted); font: inherit; font-size: var(--text-xs); text-align: left; cursor: pointer; }
.terminal-session--active .terminal-session__select { color: var(--terminal-fg); }
.terminal-session__title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.terminal-session__status { width: 6px; height: 6px; flex: 0 0 auto; border-radius: 50%; background: var(--terminal-faint); }
.terminal-session__status--running { background: var(--ok); }
.terminal-session__close { display: inline-flex; align-items: center; justify-content: center; width: 25px; height: 25px; margin-right: 2px; padding: 0; border: 0; background: transparent; color: var(--terminal-faint); cursor: pointer; }
.terminal-session__close:hover, .terminal-session__close:focus-visible { color: var(--danger); outline: none; }
.terminal-panel__content { min-width: 0; min-height: 0; flex: 1; background: var(--terminal-bg); }
.terminal-view { width: 100%; height: 100%; padding: 8px 4px 4px 8px; background: var(--terminal-bg); color: var(--terminal-fg); }
.terminal-empty { display: flex; align-items: center; justify-content: center; gap: 9px; height: 100%; padding: 24px; color: var(--terminal-muted); text-align: center; }
.terminal-empty--action { flex-direction: column; }
.terminal-empty--error strong { max-width: min(100%, 560px); overflow-wrap: anywhere; }
.terminal-empty p { margin: 0; }
.terminal-empty__spinner { width: 14px; height: 14px; border: 2px solid var(--terminal-border); border-top-color: var(--terminal-cursor); border-radius: 50%; animation: terminal-spin .8s linear infinite; }
@keyframes terminal-spin { to { transform: rotate(360deg); } }
@media (max-width: 760px) {
  .settings-center {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .settings-center__nav {
    display: flex;
    gap: 4px;
    padding: 8px;
    overflow-x: auto;
    overflow-y: hidden;
    border-right: 0;
    border-bottom: 1px solid var(--border);
    scrollbar-width: none;
  }

  .settings-center__nav::-webkit-scrollbar {
    display: none;
  }

  .settings-center__navitem {
    flex: 0 0 auto;
    width: auto;
    padding: 8px 10px;
  }

  .settings-center__navitem small {
    display: none;
  }

  .settings-center__navitem--active::before {
    inset: auto 10px 0;
    width: auto;
    height: 3px;
  }
}

/* Terminal-drawer footer compaction (terminal is open + non-Creation layout).
/* Terminal-drawer footer compaction (terminal is open + non-Creation layout).
   !important is necessary because the footer padding is set by multiple theme /
   media-query rules with varying specificity that are hard to predict.
   Keep the top spacing (composer→statusbar) intact; only reduce the bottom
   padding that would otherwise waste space between the status bar and terminal. */
.footer.footer--compact {
  padding-bottom: 4px !important;
}

/* Classic and Workbench share the same compact four-view strip at the dock's
/* Classic and Workbench share the same compact four-view strip at the dock's
   minimum width. Creation keeps its equal-column tab treatment. */
@container (max-width: 420px) {
  .app--classic .workbench-dock__tab,
  .app--workbench .workbench-dock__tab,
  :root[data-theme-style] .app--classic .workbench-dock__tab,
  :root[data-theme-style] .app--workbench .workbench-dock__tab {
    padding-left: 10px;
    padding-right: 10px;
    gap: 4px;
  }
}

/* DingTalk bot channel: the credential row and manual setup form need
/* DingTalk bot channel: the credential row and manual setup form need
   their own multi-column layout; the shared .bot-secret-row is forced to a
   single column inside .bot-detail-card, which stacks five elements. */
.bot-connect-panel--dingtalk {
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  padding: 14px;
}
.bot-connect-panel--dingtalk .bot-connect-panel__body {
  gap: 12px;
}
.bot-manual-form.bot-manual-form--dingtalk {
  gap: 10px;
  max-width: none;
}
.bot-manual-form.bot-manual-form--dingtalk .bot-card-field {
  grid-template-columns: minmax(92px, 128px) minmax(0, 1fr);
}
.bot-manual-form.bot-manual-form--dingtalk .bot-card-field > div {
  justify-content: flex-start;
}
/* 钉钉凭据区与飞书一致：单列竖排（通用 .bot-detail-card .bot-secret-row
/* 钉钉凭据区与飞书一致：单列竖排（通用 .bot-detail-card .bot-secret-row
   已强制为 1fr；这里不再覆盖为多列横排，避免 5 个元素挤一行放不下）。 */

/* ── Topic bar title button (click-to-rename in every layout) ────── */
.topicbar__workspace-label {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg-faint);
  font-size: var(--text-sm);
  font-weight: 500;
  line-height: 1;
  padding-left: 8px;
  border-left: 1px solid var(--border-soft);
  user-select: none;
}

.topicbar__title-button,
:root[data-theme-style] .topicbar__title-button {
  max-width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: inherit;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}

.topicbar__title-button:hover,
.topicbar__title-button:focus-visible,
:root[data-theme-style] .topicbar__title-button:hover,
:root[data-theme-style] .topicbar__title-button:focus-visible {
  color: var(--fg);
}

/* ── Topic bar background ───────────────────────────────────────────
/* ── Topic bar background ───────────────────────────────────────────
   Unify the chat-pane header with the surrounding chat surface. The
   topic bar defaults to --bg-elev; in light themes that reads as a hard
   white band, so use #F5F6F9 to blend it into the chat area. Dark themes
   keep the themed elevation so the header never turns light-on-dark.
   !important beats the theme-style / chrome-hidden topicbar rules. */
.topicbar,
:root[data-theme="dark"] .topicbar,
:root[data-theme-style] .topicbar {
  background: var(--bg-elev) !important;
}

:root[data-theme="light"][data-theme-style] .topicbar,
:root[data-theme="light"] .topicbar {
  background: #f5f6f9 !important;
}

@media (prefers-color-scheme: light) {
  :root:not([data-theme]) .topicbar {
    background: #f5f6f9 !important;
  }
}
/* ── Remote project group extras (badge + session rows) ───────────────── */
.project-tree__remote-badge {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-left: 6px;
  border-radius: 50%;
  background: var(--fg-faint);
  vertical-align: middle;
}
.project-tree__remote-badge--connected,
.project-tree__remote-badge--degraded {
  background: var(--ok);
}
.project-tree__remote-badge--connecting,
.project-tree__remote-badge--reconnecting,
.project-tree__remote-badge--pending_hostkey {
  background: var(--warn, var(--fg));
}
.project-tree__remote-badge--stopped,
.project-tree__remote-badge--disconnected {
  background: var(--fg-faint);
}
.project-tree__remote-badge--error {
  background: var(--danger, var(--fg));
}
/* Per-workspace serve state: green only when that group's serve is ready. */
.project-tree__remote-badge--serve-ready {
  background: var(--ok);
}
.project-tree__remote-badge--serve-busy {
  background: var(--warn, var(--fg));
}
.project-tree__remote-badge--serve-error {
  background: var(--danger, var(--fg));
}
.project-tree__remote-badge--serve-idle {
  background: var(--fg-faint);
}

/* ── Remote session surface (remote tab content area) ─────────────── */
.session-recovery {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 16px 28px;
  border-bottom: 1px solid color-mix(in srgb, var(--accent) 24%, var(--border-soft));
  background: color-mix(in srgb, var(--accent) 7%, var(--chat-bg));
  color: var(--accent);
}
.session-recovery__copy {
  flex: 1 1 180px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.session-recovery__copy strong { font-size: var(--text-lg); }
.session-recovery__copy span { color: var(--fg-dim); font-size: var(--text-sm); overflow-wrap: anywhere; }
.session-recovery__copy .session-recovery__wait { color: var(--fg-faint); font-size: var(--text-xs); }
.session-recovery > .btn { flex: 0 0 auto; min-height: 38px; padding-inline: 16px; font-size: var(--text-base); }
.session-recovery > .btn--ghost { background: transparent; border-color: transparent; box-shadow: none; }
.app .session-recovery ~ .footer { padding: 24px 28px 32px; }
.composer-toolbar-send--unavailable { flex-direction: column; align-items: flex-end; }
.composer-toolbar-send__hint { color: var(--fg-dim); font-size: var(--text-xs); white-space: nowrap; }
.session-recovery__detail {
  flex: 1 0 100%;
  min-width: 0;
  max-height: 160px;
  margin: 0;
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: var(--fg-dim);
  font-size: var(--text-sm);
}
.session-recovery--loading { color: var(--fg-dim); background: var(--chat-bg); }
.session-recovery-placeholder {
  display: flex;
  flex: 1;
  min-height: 100%;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 12px;
  padding: 24px;
  color: var(--fg-faint);
  font-size: var(--text-base);
  text-align: center;
}
.session-recovery__spinner { animation: remote-surface-spin 1s linear infinite; }
@media (prefers-reduced-motion: reduce) {
  .session-recovery__spinner { animation: none; }
}
.remote-surface {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  padding: 16px;
  overflow-y: auto;
}
.remote-surface__detail {
  max-width: 60%;
  color: var(--fg-faint);
  font-size: var(--text-sm);
  overflow-wrap: anywhere;
}
@keyframes remote-surface-spin { to { transform: rotate(360deg); } }
.remote-surface__approval,
.remote-surface__ask {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
  max-width: 760px;
  margin: 8px auto 0;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--warn, var(--fg)) 45%, var(--border));
  border-radius: var(--radius-md);
  background: var(--bg-elev);
}
.remote-surface__approval-head { display: flex; align-items: center; gap: 6px; font-size: var(--text-sm); font-weight: 600; }
.remote-surface__approval-body {
  max-height: 180px;
  margin: 0;
  padding: 8px;
  overflow-y: auto;
  border-radius: var(--radius-sm);
  background: var(--bg);
  font-family: var(--font-mono, monospace);
  font-size: var(--text-xs);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.remote-surface__approval-actions { display: flex; justify-content: flex-end; gap: 8px; }
.remote-surface__ask-question { display: flex; flex-direction: column; gap: 6px; }
.remote-surface__ask-prompt { font-size: var(--text-sm); font-weight: 600; }
.remote-surface__ask-options { display: flex; flex-wrap: wrap; gap: 8px; }
.project-tree__group-title--section {
  color: var(--fg-faint);
  font-weight: 520;
  cursor: default;
}
.project-tree__group-caret {
  width: 12px;
  flex: none;
  color: var(--fg-faint);
  font-size: 10px;
  text-align: center;
}
.project-tree__group-icon {
  flex: none;
  color: var(--fg-faint);
}
/* Task 827 ②: the project-group title renders one step larger than the
   project title, both driven by tokens (--project-tree-group-font =
   --project-tree-project-font + 1px), so a theme that changes the project
   size keeps the "one step larger" relationship and font-scale composes.
   Pure sizing: light and dark themes need no extra case. */
.project-tree__pgroup-main {
  position: relative;
  font-size: var(--project-tree-group-font);
}
.project-tree__pgroup-main--menu-open {
  background: color-mix(in srgb, var(--accent) 6%, var(--sidebar-hover));
}
/* Task 827 ③: the group row's icon column — one folder glyph with the fold
   chevron overlaid (collapsed ▸, expanded rotated to ▾), so the collapse
   indicator no longer occupies its own column and the title starts at
   indent + icon column + gap, the same grid the project rows follow. */
.project-tree__group-fold-stack {
  position: relative;
  flex: 0 0 var(--project-tree-icon-col);
  width: var(--project-tree-icon-col);
  height: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.project-tree__group-fold {
  position: absolute;
  top: -4px;
  right: -3px;
  font-size: 9px;
  line-height: 1;
  opacity: 0.7;
  transition: transform var(--dur-fast, 0.12s);
}
.project-tree__group-fold--open {
  transform: rotate(90deg);
}
/* Task 827 ④: drag visuals for the group reorder — a dimmed source row and a
   drop indicator on the target edge (tl 1225: the topic/project-row inset
   bar, not the retired outset hairline). */
.project-tree__pgroup-main--dragging {
  opacity: 0.55;
  cursor: grabbing;
}
/* tl 1225: same inset-bar mechanism as the project rows (and the topic rows
   both mirror) — the group reorder hint used to be an outset hairline outside
   the row box with the same covering/clipping hazards. */
.project-tree__pgroup-main--drop-before {
  box-shadow: inset 0 2px 0 var(--accent);
}
.project-tree__pgroup-main--drop-after {
  box-shadow: inset 0 -2px 0 var(--accent);
}
/* tl 1199 ②: a project drag hovering a group header paints this row-level
   landing highlight (unlike the reorder bands above, the whole row lights up:
   the drop means "into this group", mirroring the session-side nest-target).
   tl 1225: the ring follows the session-side nest-target weight (2px) so the
   "into" feedback reads the same on both tree sides. */
.project-tree__pgroup-main--drop-into {
  background: color-mix(in srgb, var(--accent) 16%, transparent);
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 55%, transparent);
}
.project-tree__pgroup-main--dragging {
  cursor: grabbing;
}
.project-tree__group-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.project-tree__group-count {
  flex: none;
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.project-tree__group-actions {
  display: flex;
  gap: 2px;
  opacity: 0;
  transition: opacity 0.12s;
}
.project-tree__group-title:hover .project-tree__group-actions {
  opacity: 1;
}
.project-tree__group-act {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-faint);
  cursor: pointer;
}
.project-tree__group-act:hover {
  background: var(--bg-hover, var(--sidebar-hover));
  color: var(--fg);
}
.project-tree__group-act--danger:hover {
  color: var(--danger, #e5534b);
}


/* New-group composer panel (NewGroupPanel — the session-tree create-group
   dialog). tl 1149 retired the MoveToGroupPanel; only the classes the
   composer still uses survive here. */
.move-group-panel {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  z-index: var(--z-menu);
  width: min(320px, calc(100% - 48px));
  max-height: min(60vh, 420px);
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-elev);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.22);
  color: var(--fg);
}

.move-group__header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--border);
}

.move-group__header svg {
  color: var(--fg-faint);
  flex: none;
}

.move-group__title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--text-md);
}

.move-group__create {
  display: flex;
  gap: 8px;
  padding: 10px;
}

.move-group__input {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--fg);
  font-size: var(--text-md);
}

/* ── MCP Apps inline surface ─────────────────────────────────────────── */
.mcp-app-card {
  margin-top: 8px;
  border: 1px solid var(--soft-border, #d0d0d0);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.mcp-app-frame {
  display: block;
  width: 100%;
  border: 0;
  background: #fff;
  transition: height 120ms ease;
}

.tool__mcp-app-open {
  margin-top: 8px;
  padding: 4px 12px;
  border: 1px solid var(--soft-border, #d0d0d0);
  border-radius: var(--radius-sm);
  background: transparent;
  color: inherit;
  font-size: var(--text-sm);
  cursor: pointer;
}

.tool__mcp-app-open:hover {
  filter: brightness(0.95);
}

/* Question search panel (#9218): restored after auto-merge dropped the block.
   Token migration: --fg-muted → --fg-faint (retired token).
   tl1244: the panel anchors 8px below .transcript-shell's top (the shell sits
   under the topbar and above the composer), so a viewport-relative cap
   (min(70vh, 520px)) ignored the topbar offset and the real composer height —
   on short windows / tall composers the panel's bottom slid under the input
   bar, hiding the lowest history cards. Percentage max-height on an absolutely
   positioned element resolves against the containing block (.transcript-shell,
   position:relative; height:100% chain bounded by the viewport), so
   calc(100% - 16px) keeps the whole panel inside the shell: 8px gap above and
   8px above the composer. The 520px cap is unchanged for tall windows. */
.question-search-panel {
  position: absolute;
  top: 8px;
  left: 50%;
  transform: translateX(-50%);
  z-index: var(--z-popover);
  width: min(460px, calc(100% - 48px));
  max-height: min(520px, calc(100% - 16px));
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-elev);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.22);
  color: var(--fg);
}
.question-search__header {
  /* tl1244: keep the search box fixed — the results area below is the only
     flexible part, so a tight max-height must never compress the input. */
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--border);
}
.question-search__header svg {
  color: var(--fg-faint);
  flex: none;
}
.question-search__input {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--fg);
  font-size: var(--text-md);
}
.question-search__results {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.question-search__card {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg);
  font-size: var(--text-md);
  line-height: 1.4;
  text-align: left;
  cursor: pointer;
}
.question-search__card:hover {
  background: var(--bg-hover, var(--bg));
  border-color: var(--border);
}
.question-search__index {
  flex: none;
  min-width: 26px;
  text-align: center;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg);
  border: 1px solid var(--border);
  color: var(--fg-faint);
  font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
}
.question-search__text {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  word-break: break-word;
}
.question-search__empty {
  padding: 18px 8px;
  text-align: center;
  color: var(--fg-faint);
  font-size: var(--text-md);
}
.question-search__foot {
  /* tl1244: fixed footer row — only .question-search__results flexes. */
  flex: none;
  padding: 6px 12px;
  border-top: 1px solid var(--border);
  color: var(--fg-faint);
  font-size: var(--text-sm);
}
/* Task 399: transcript find bar — same top-center anchor family as the
   question search panel, clear of the right-edge jump bar. */
.transcript-find {
  position: absolute;
  top: 8px;
  left: 50%;
  transform: translateX(-50%);
  z-index: var(--z-popover);
  width: min(460px, calc(100% - 48px));
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-elev);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.22);
  color: var(--fg);
}
.transcript-find__icon {
  flex: none;
  color: var(--fg-faint);
}
.transcript-find__input {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--fg);
  font-size: var(--text-md);
}
.transcript-find__input:focus {
  outline: none;
  border-color: color-mix(in srgb, var(--accent) 60%, var(--border));
}
.transcript-find__count {
  flex: none;
  min-width: 52px;
  padding: 0 4px;
  color: var(--fg-faint);
  font-size: var(--text-sm);
  font-variant-numeric: tabular-nums;
  text-align: center;
  white-space: nowrap;
}
.transcript-find__btn {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-dim);
  cursor: pointer;
}
.transcript-find__btn:hover:not(:disabled) {
  background: var(--bg-hover, var(--bg));
  border-color: var(--border);
  color: var(--fg);
}
.transcript-find__btn:disabled {
  opacity: 0.4;
  cursor: default;
}
/* Task 399: hit rows. Row backgrounds vary by kind, so highlight with an
   inset accent bar + tint that composites over any row surface. */
.transcript__row--find {
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--accent) 65%, transparent);
}
.transcript__row--find-active {
  background: color-mix(in srgb, var(--accent) 18%, transparent);
  box-shadow: inset 3px 0 0 var(--accent);
  outline: 1px solid color-mix(in srgb, var(--accent) 55%, transparent);
  outline-offset: -1px;
}
/* Shared composer toolbar: context and permissions left, model controls right. */
:root[data-theme-style] .composer-meta.composer-meta--unified .composer-meta__params,
.composer-meta.composer-meta--unified .composer-meta__params {
  display: flex;
  flex-wrap: wrap;
  width: 100%;
  min-width: 0;
  gap: 6px;
  align-items: center;
}
.composer-meta--unified { container-type: inline-size; }
:root[data-theme-style] .composer-meta--unified .composer-meta__control,
.composer-meta--unified .composer-meta__control {
  display: inline-flex;
  flex: 0 0 auto;
  width: auto;
  min-width: 0;
  max-width: none;
}
.composer-meta--unified .composer-meta__control--content { order: 0; }
.composer-meta--unified .composer-meta__control--approval { order: 1; }
.composer-meta--unified .composer-meta__control--intent { order: 2; }
.composer-meta--unified .composer-meta__control--delivery { order: 3; }
:root[data-theme-style] .composer-meta--unified .composer-meta__control--model,
.composer-meta--unified .composer-meta__control--model {
  order: 4;
  flex: 0 1 auto;
  max-width: 48%;
}
.composer-toolbar-send { order: 5; display: flex; gap: 6px; flex-shrink: 0; margin-left: auto; }
/* Task 261: clock-icon prompt history picker (experimental). 任务529：面板经
   AnchoredPopover portal 到 body（.composer-meta overflow:hidden 会裁剪
   absolute 定位面板），surface 规格类挂在 portal 容器上，本处只留按钮容器。 */
.composer-history-picker { position: relative; display: flex; align-items: center; }
.composer-history-menu.composer-menu-surface { width: min(460px, calc(100vw - 48px)); max-width: none; display: flex; flex-direction: column; gap: 6px; }
.composer-history-menu__head { display: flex; align-items: center; gap: 6px; padding: 2px 8px; font-size: var(--text-xs); font-weight: 600; color: var(--fg-dim); }
.composer-history-menu__hint { margin-left: auto; font-weight: 400; font-size: 10px; }
.composer-history-menu__list { display: flex; flex-direction: column; max-height: 280px; overflow: auto; outline: none; }
.composer-history-menu__item { display: flex; align-items: center; gap: 8px; width: 100%; padding: 7px 8px; border: 0; border-radius: 12px; background: transparent; color: var(--fg); font-size: var(--text-sm); text-align: left; cursor: pointer; }
.composer-history-menu__item:hover { background: var(--bg-soft); }
.composer-history-menu__time { flex-shrink: 0; font-size: 10px; color: var(--fg-dim); font-variant-numeric: tabular-nums; }
.composer-history-menu__summary { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.composer-history-menu__empty { padding: 10px 8px; font-size: var(--text-sm); color: var(--fg-dim); }
.composer-history-menu__more { display: flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 8px; border: 0; border-radius: 12px; background: transparent; color: var(--fg-dim); font-size: var(--text-xs); cursor: pointer; }
.composer-history-menu__more:hover:not(:disabled) { background: var(--bg-soft); color: var(--fg); }
/* 任务 869：emoji 面板。弹层同历史提示词路线（AnchoredPopover portal 到
   body），surface 规格类挂在 portal 容器上；网格/单元格尺寸与历史面板同档。 */
.composer-emoji-picker { position: relative; display: flex; align-items: center; }
.composer-emoji-popover.composer-menu-surface { width: min(336px, calc(100vw - 48px)); max-width: none; display: flex; flex-direction: column; gap: 6px; padding: 8px; }
.composer-emoji-menu { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.composer-emoji-menu__loading { min-height: 240px; display: grid; place-items: center; color: var(--fg-dim); }
.composer-emoji-menu__head { display: flex; align-items: center; gap: 6px; padding: 2px 4px; font-size: var(--text-xs); font-weight: 600; color: var(--fg-dim); }
.composer-emoji-menu__title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.composer-emoji-menu__close { margin-left: auto; display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; border: 0; border-radius: 8px; background: transparent; color: var(--fg-dim); cursor: pointer; }
.composer-emoji-menu__close:hover { background: var(--bg-soft); color: var(--fg); }
.composer-emoji-menu__search { display: flex; align-items: center; gap: 6px; padding: 5px 8px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-soft); color: var(--fg-dim); }
.composer-emoji-menu__search-input { flex: 1; min-width: 0; border: 0; outline: none; background: transparent; color: var(--fg); font-size: var(--text-sm); }
.composer-emoji-menu__search-input::placeholder { color: var(--fg-dim); }
.composer-emoji-menu__frequent { display: grid; grid-template-columns: repeat(8, 1fr); gap: 2px; padding-bottom: 4px; border-bottom: 1px solid var(--border-soft); }
.composer-emoji-menu__tabs { display: flex; gap: 2px; overflow-x: auto; scrollbar-width: none; }
.composer-emoji-menu__tabs::-webkit-scrollbar { display: none; }
.composer-emoji-menu__tab { flex-shrink: 0; padding: 3px 8px; border: 0; border-radius: 999px; background: transparent; color: var(--fg-dim); font-size: 11px; cursor: pointer; white-space: nowrap; }
.composer-emoji-menu__tab:hover { background: var(--bg-soft); color: var(--fg); }
.composer-emoji-menu__tab--active { background: var(--bg-soft); color: var(--accent); }
.composer-emoji-menu__grid { display: grid; grid-template-columns: repeat(8, 1fr); gap: 2px; max-height: 216px; overflow-y: auto; }
.composer-emoji-menu__cell { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px; border: 0; border-radius: 8px; background: transparent; font-size: 20px; line-height: 1; cursor: pointer; }
.composer-emoji-menu__cell:hover { background: var(--bg-soft); }
.composer-emoji-menu__empty { padding: 18px 8px; text-align: center; font-size: var(--text-sm); color: var(--fg-dim); }
.composer-history-menu__more:disabled { opacity: 0.6; cursor: default; }
.composer-history-menu__more .spin { animation: spin 0.8s linear infinite; }
:root[data-theme-style] .composer-meta--unified .modelsw__trigger,
:root[data-theme-style] .composer-meta--unified .composer-content-trigger,
.composer-meta--unified .modelsw__trigger,
.composer-meta--unified .composer-content-trigger,
.composer-choice {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px;
  border: 0;
  background: transparent;
  box-shadow: none;
  color: var(--fg);
  font: inherit;
  cursor: pointer;
}
.composer-choice { white-space: nowrap; border-radius: 6px; }
.composer-choice:hover { background: var(--bg-soft); }
.composer-choice:disabled { opacity: 0.5; cursor: default; }
.composer-choice--warning { color: var(--accent); }
.composer-choice:focus-visible, .context-ring:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.composer-meta--unified .modelsw { min-width: 0; }
.composer-meta--unified .composer-effort-control { flex: 0 0 auto; }
/* tl1301: fallback effort rebuild in flight — inline hint beside the effort
   control; fast paths never render it. Reuses the global spin keyframes. */
.composer-effort-applying {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--fg-dim);
  font-size: calc(12px * var(--font-scale));
  white-space: nowrap;
}
.composer-effort-applying::before {
  content: "";
  width: 10px;
  height: 10px;
  border: 2px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@media (prefers-reduced-motion: reduce) {
  .composer-effort-applying::before { animation: none; }
}
.composer-meta--unified .composer-meta__control--model { gap: 4px; }
.composer-meta--unified .context-ring__svg { transform: translateY(1px); }
:root[data-theme-style] .composer-meta--unified .context-ring,
.composer-meta--unified .context-ring { margin-right: 0; }
:root[data-theme-style] .composer-meta--unified .composer-meta__control--approval,
.composer-meta--unified .composer-meta__control--approval { margin-left: 0; }
:root[data-theme-style] .composer-meta--unified .composer-meta__control--model { margin-left: auto; }
.composer-meta--unified .modelsw__kind,
.composer-meta--unified .context-ring__percent { display: none; }
.composer-meta--unified .composer-toolbar-send { margin-left: 2px; }
.composer-meta--unified .modelsw__label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.modelsw__detail, .context-ring__percent { color: var(--fg-dim); }
.context-ring__percent { font-size: calc(12px * var(--font-scale)); }
@container (max-width: 650px) {
  :root[data-theme-style] .composer-meta--unified .composer-meta__control--model,
  .composer-meta--unified .composer-meta__control--model { max-width: 55%; flex: 0 1 auto; }
  .composer-meta--unified .modelsw__kind { display: none; }
}
@container (max-width: 520px) {
  :root[data-theme-style] .composer-meta.composer-meta--unified .composer-meta__params,
  .composer-meta.composer-meta--unified .composer-meta__params {
    flex-wrap: nowrap;
    gap: 4px;
  }
  .composer-meta--unified .composer-meta__control--model { gap: 4px; }
  .composer-meta--unified .composer-choice > span,
  .composer-meta--unified .composer-task-mode-trigger__value,
  .composer-meta--unified .modelsw__label,
  .composer-meta--unified .modelsw__trigger > svg:last-child,
  .composer-meta--unified .context-ring__percent { display: none; }
  :root[data-theme-style] .composer-meta--unified .composer-meta__control--model {
    flex: 0 0 auto;
    max-width: none;
  }
  .composer-meta--unified .modelsw__kind { display: inline-flex; }
  .composer-meta--unified .composer-effort-control .composer-choice > svg:last-child,
  .composer-meta--unified .composer-meta__control--approval .composer-choice > svg:last-child { display: none; }
  .composer-meta--unified .composer-toolbar-send { margin-left: 0; }
}

/* Composer popovers share one surface and row rhythm across all menus. */
:root .composer-menu-surface,
:root[data-theme-style] .composer-menu-surface {
  --composer-menu-radius: 20px;
  --composer-menu-row-radius: 18px;
  --composer-menu-row-height: 34px;
  width: max-content;
  min-width: min(128px, calc(100vw - 16px));
  max-width: min(320px, calc(100vw - 16px));
  padding: 10px 6px;
  border: 1px solid var(--border);
  border-radius: var(--composer-menu-radius);
  background: var(--bg-elev);
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.28);
  color: var(--fg);
  font-size: calc(14px * var(--font-scale));
  line-height: 22px;
}
:root .composer-menu-surface :is(.composer-access-menu__item, .modelsw__item) {
  height: auto;
  min-height: var(--composer-menu-row-height);
  padding: 6px 10px;
  gap: 10px;
  border-radius: var(--composer-menu-row-radius);
  color: var(--fg);
  font-size: inherit;
  font-weight: 400;
  line-height: 22px;
}
:root .composer-menu-surface .composer-access-menu__title {
  font-size: inherit;
  font-weight: 400;
  line-height: 22px;
}
:root .composer-menu-surface :is(.composer-access-menu__label, .modelsw__group-label) {
  padding: 2px 10px 6px;
  color: var(--fg-faint);
  font-size: calc(13px * var(--font-scale));
  line-height: 20px;
  font-weight: 500;
  text-transform: none;
  letter-spacing: normal;
}
:root .composer-menu-surface .composer-access-menu__section { gap: 0; }
:root .composer-menu-surface :is(.composer-access-menu__section + .composer-access-menu__section, .modelsw__group + .modelsw__group, .modelsw__manage) {
  margin-top: 12px;
  border-top: 0;
}
:root .composer-menu-surface .composer-access-menu__section + .composer-access-menu__section { padding-top: 0; }
:root .composer-menu-surface :is(.composer-access-menu__desc, .modelsw__empty) {
  font-size: calc(12px * var(--font-scale));
  line-height: 18px;
  color: var(--fg-dim);
}
:root .composer-menu-surface :is(.composer-access-menu__item, .modelsw__item):is(:hover, :focus-visible),
:root .composer-menu-surface :is(.composer-access-menu__item--active, .modelsw__item--current) {
  background: var(--bg-elev-2);
  color: var(--fg);
}
/* Task 594: the denser surface keeps the disabled look flat on hover too. */
:root .composer-menu-surface .composer-access-menu__item:disabled:hover {
  background: transparent;
}
:root .composer-menu-surface :is(.composer-access-menu__item, .modelsw__item):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
:root .composer-menu-surface button:disabled { opacity: 0.45; cursor: default; }
:root .composer-menu-surface :is(.modelsw__check, .composer-intent-menu__check, .composer-access-menu__item > svg:last-child) { color: var(--accent); }
:root .composer-menu-surface .modelsw__search {
  min-height: 34px;
  margin: 0 4px 12px;
  padding: 6px 10px;
  border-radius: 14px; /* 833-radius-wl:large */
}
:root .composer-menu-surface .modelsw__search-input { font-size: inherit; }
:root .composer-menu-surface .context-ring-popover__inner { padding: 6px 10px; }
:root .composer-menu-surface.modelsw__menu { min-width: min(240px, calc(100vw - 16px)); }
:root .composer-menu-surface.context-ring-popover { min-width: min(260px, calc(100vw - 16px)); }
:root .composer-menu-surface .composer-access-menu__title { overflow-wrap: anywhere; }
:root .composer-choice--permission-auto { color: var(--ok); }
:root { --composer-permission-ask: #60a5fa; }
:root[data-theme="light"] { --composer-permission-ask: #2563eb; }
@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) { --composer-permission-ask: #2563eb; }
}
:root .composer-choice--permission-ask { color: var(--composer-permission-ask); }
:root .composer-choice--permission-yolo { color: var(--err); }

/* Quick-command manager (Settings > General > Quick commands) and the picker the
   composer's + menu opens. The manager had no styles at all before this: its rows
   relied on .mem-input defaults, which is part of why it read as unusable. */
.settings-quick-commands {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* Task 656: 60vh capped the manager well below what the dialog shell allows,
   so everyday lists scrolled when they did not need to. The cap now derives
   from the viewport minus the shell chrome (24px padding x2 + header), so the
   dialog grows vertically up to the same 100dvh - 48px limit the shell owns;
   overflow-y stays as the fallback for lists longer than the screen. */
.settings-quick-commands--panel {
  max-height: calc(100dvh - 160px);
  overflow-y: auto;
  padding-right: 2px;
}

/* Task 262-3: the dialog was too narrow for long snippet text (it wrapped
   mid-word). Give the wide variant a real floor plus a viewport cap so both
   the rows and the create/edit form get usable line length.
   Task 278: the floor moved OUT of this rule — at 680px it still lost to the
   620px shell (.provider-dialog), which is what actually clipped the rows.
   The wide shell (.provider-dialog--wide, 900px) now owns the width and this
   block simply fills it.
   Task 656: the shell itself is now 1100px (see ProviderAccessSettings.css). */
.settings-quick-commands--wide {
  width: 100%;
  max-width: none;
}
.settings-quick-commands--wide .settings-quick-commands__row > textarea.mem-input {
  flex: 1 1 46%;
}

.settings-quick-commands__row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

/* A freshly added row is scrolled into view and tinted once, so "Add" visibly did
   something even when the list is long. */
/* The add draft is a real form rather than a blank row, so the input step is
   visible before anything is stored. */
.settings-quick-commands__draft {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px;
  border: 1px solid var(--accent);
  border-radius: var(--radius-sm);
}
.settings-quick-commands__draft-actions {
  display: flex;
  gap: 6px;
}
.settings-quick-commands__row--fresh {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.settings-quick-commands__row > input.mem-input:first-of-type {
  flex: 1 1 28%;
  min-width: 120px;
}

.settings-quick-commands__row > textarea.mem-input {
  flex: 2 1 52%;
  /* 任务 278 防反弹：flex 子项的自动最小宽（min-width:auto）会让超长
     无空格内容把行撑破、在 900px 弹窗内再次出现横向滚动条；显式归零后
     文本列只能换行/内部滚动，行宽恒等于弹窗内容宽。 */
  min-width: 0;
  resize: vertical;
}

.settings-quick-commands__empty {
  padding: 10px 2px;
  font-size: var(--text-md);
  opacity: 0.75;
}

.composer-content-menu__back {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 8px 10px;
  background: none;
  border: 0;
  border-bottom: 1px solid rgba(127, 127, 127, 0.22);
  color: inherit;
  font: inherit;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
}

.composer-content-menu__back:hover {
  background: rgba(127, 127, 127, 0.1);
}

.composer-content-menu__search {
  width: calc(100% - 20px);
  margin: 8px 10px;
}

/* One-line preview for menu items that carry a secondary line: a long snippet must
   not stretch the popover, the full text is still in the picker. */
.composer-access-menu__hint {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  opacity: 0.7;
}

/* Task 50: long-press a group header to reorder it inside its project.
   tl 1260: the source dim follows the project side's dragging weight
   (.project-tree__folder--dragging / __pgroup-main--dragging both 0.55) so a
   session-group drag reads the same as a project drag. */
.project-tree__group-main--dragging {
  opacity: 0.55;
  cursor: grabbing;
}

/* tl 1267: the session-group placement hints follow the industry quadrisector
   (VS Code ListViewTargetSector / Atlassian pragmatic-dnd / React Aria
   DropIndicator) with TWO distinct treatments, per the tl 1260 rework verdict:
   - BETWEEN rows (drop-before / drop-after) = a 2px accent insertion LINE
     drawn inside the row box at the top/bottom edge, starting at the row's own
     hierarchy indent (--project-tree-drop-inset is fed inline by the TSX with
     the same value the header pads by). This replaces tl 1260's zone-blind
     ring+wash: before and after must be distinguishable mid-drag, and a ring
     on the whole header reads as "into", not "between".
   - INTO (nest-target) = the whole-row container treatment (accent wash +
     2px ring), unchanged from tl 1260 — this is also what an HTML5 session
     drag paints while hovering a header (its drop is always "into").
   The doubled-class selector (0,2,0, later in this file) stays load-bearing
   against `.project-tree__group-main:hover` (tl 1260's hover-beat lesson).
   The lines are ::before pseudo-elements INSIDE the row box (top:0/bottom:0,
   never negative offsets) — the tl 1225 lesson: outset hairlines get covered
   by sibling contain:layout stacking contexts and clipped by the scroll
   container on the first/last row. */
.project-tree__group-main.project-tree__group-main--drop-before,
.project-tree__group-main.project-tree__group-main--drop-after {
  position: relative;
}
.project-tree__group-main.project-tree__group-main--drop-before::before,
.project-tree__group-main.project-tree__group-main--drop-after::before {
  content: "";
  position: absolute;
  left: var(--project-tree-drop-inset, 8px);
  right: 0;
  height: 2px;
  border-radius: 1px;
  background: var(--accent);
  pointer-events: none;
}
.project-tree__group-main.project-tree__group-main--drop-before::before {
  top: 0;
}
.project-tree__group-main.project-tree__group-main--drop-after::before {
  bottom: 0;
}

/* Task 892-B: the INTO band of a group drop (drop on the row = join the
   group's subtree) paints stronger than the insertion lines, so the two
   plain-drop meanings are distinguishable mid-drag. tl 1260: accent twin
   of the project side's --pgroup-main--drop-into (accent 16% wash + 2px ring
   at 55%), doubled-class for the same hover-beat reason. tl 1267: this is
   also the HTML5 session-hover treatment (drop is always "into" there). */
.project-tree__group-main.project-tree__group-main--nest-target {
  background: color-mix(in srgb, var(--accent) 16%, transparent);
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 55%, transparent);
}

/* tl 1267 防呆: a hover over the dragged group itself or one of its own
   descendants must read as "cannot drop here" — not-allowed cursor plus a
   flat gray wash, and the release commits nothing (the TSX never hands a
   blocked hover to dropGroup). Doubled-class for the same hover-beat reason:
   the gray must not be replaced by the 8% accent hover wash mid-drag. */
.project-tree__group-main.project-tree__group-main--drop-blocked {
  cursor: not-allowed;
  background: color-mix(in srgb, var(--fg) 5%, transparent);
}

/* Task 169: desktop drag affordance for group reordering. The grip sits at the
   row start and appears on header hover (plus while dragging), the same
   discoverability contract as the status-bar item editor's handle. Colours use
   the established text tokens; the handle is the only place the cursor
   advertises grabbing, the header itself keeps its pointer cursor. */
.project-tree__group-drag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 12px;
  width: 12px;
  color: var(--fg-faint);
  opacity: 0;
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.project-tree__group-main:hover .project-tree__group-drag,
.project-tree__group-main--dragging .project-tree__group-drag {
  opacity: 1;
}

.project-tree__group-main:hover .project-tree__group-drag {
  color: var(--fg-dim);
}

.project-tree__group-main--dragging .project-tree__group-drag {
  cursor: grabbing;
}

/* The classified gateway-failure cause is what the user acts on; the raw backend
   text stays visible but subordinate, so it can be copied into a report without
   competing with the cause. Standalone (no parent class) because the panel renders
   .settings-error with the shared error styling. */
.settings-error__detail {
  margin-top: 4px;
  font-size: var(--text-xs);
  opacity: 0.75;
  word-break: break-word;
}

/* ── Session versions and copies panel ───────────────────────────────────────
   A table rather than a stack of divs: grid with an explicit gap keeps the
   timestamp and the size from running together, and one column per number makes
   the copies comparable down a column instead of readable only as prose. */
.rc-modal {
  display: flex;
  flex-direction: column;
  /* The shared .modal caps itself at 440px for dialogs, which is far too narrow
     for a table; overriding max-width is what actually widens this panel - setting
     width alone left it at 440px. */
  width: 96vw;
  max-width: 1720px;
  max-height: 88vh;
  overflow: hidden;
  padding: 0;
}
.rc-modal__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 22px;
  border-bottom: 1px solid color-mix(in srgb, currentColor 14%, transparent);
}
.rc-modal__title { font-weight: 600; }
.rc-modal__body { flex: 1 1 auto; min-height: 0; overflow: auto; padding: 12px 22px; }
.rc-modal__foot {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 22px;
  border-top: 1px solid color-mix(in srgb, currentColor 14%, transparent);
}

.rc-table { display: flex; flex-direction: column; }
.rc-row {
  display: grid;
  grid-template-columns: 26px minmax(200px, 2fr) 138px 92px 84px 68px 84px 92px;
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 7px 10px;
  border-radius: var(--radius-sm);
}
.rc-row--head {
  position: sticky;
  top: 0;
  z-index: var(--z-inline-sticky);
  font-size: 0.86em;
  font-weight: 600;
  opacity: 0.72;
  background: inherit;
  border-bottom: 1px solid color-mix(in srgb, currentColor 16%, transparent);
}
.rc-row--group { font-weight: 600; }
.rc-row--group:hover { background: color-mix(in srgb, currentColor 6%, transparent); }
.rc-row--main {
  margin-top: 2px;
  background: color-mix(in srgb, currentColor 9%, transparent);
}
.rc-row--copy { opacity: 0.94; }

.rc-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.rc-caret { flex: 0 0 auto; opacity: 0.7; }
.rc-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rc-muted { opacity: 0.5; }
.rc-unique { font-weight: 700; }
.rc-action { display: flex; justify-content: flex-end; }
.rc-note { margin-left: auto; opacity: 0.8; }

.rc-preview { margin: 8px 0; padding-left: 20px; }
.rc-preview__warn { margin: 8px 0 0; opacity: 0.8; }

.rc-phase { margin-top: 14px; }
.rc-phase:first-child { margin-top: 0; }
.rc-phase__head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 8px 10px 6px;
  font-size: 0.9em;
}
.rc-phase__title { font-weight: 700; }
.rc-phase__count {
  min-width: 20px;
  padding: 0 6px;
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, currentColor 12%, transparent);
  text-align: center;
}
.rc-phase__hint { opacity: 0.6; }
.rc-errors { margin: 0; padding-left: 20px; }
/* 任务 1039：失败横幅上的后端原因——比横幅文案小一号、可换行，长错误
   （重放超限带 resource=value/limit）不撑破横幅。 */
.rc-failed-reason { margin-left: 6px; font-size: 0.85em; opacity: 0.85; word-break: break-all; }
/* 任务 1039r：v3 版本面板里的降级标记——零计数行必须说自己是降级（重放
   被拒/枚举失败），不能和「空会话」混淆。悬停 title 给出完整原因。 */
.sv-degraded {
  margin-left: 6px;
  padding: 0 6px;
  border-radius: var(--radius-pill);
  font-size: 0.8em;
  color: var(--warn);
  border: 1px solid color-mix(in srgb, var(--warn) 45%, transparent);
}
/* 任务 1063：两个分区合并成一个——副本行与 v3 版本徽标在行内共存；v3 版本
   块（heads 表 + 切换/健康/修复）与候选链块并列在展开区内，读数含体积列
   （rc-num 让数字列右对齐，与 .rc-row 的列语义一致）。 */
.rc-versions__badge {
  flex: 0 0 auto;
  margin-left: 8px;
  padding: 1px 7px;
  border-radius: var(--radius-pill);
  font-size: 0.8em;
  font-weight: 500;
  background: color-mix(in srgb, currentColor 14%, transparent);
  white-space: nowrap;
}
/* 任务 1123：候选链推荐拆成「更长」「更新」两条独立标签——各带自己的实际
   值（条数/轮次、最后活动日期），不再合并成一条可能只对一半成立的表述；
   两条标签若同时命中同一链，视觉上并列展示、各自独立可读。 */
.rc-versions__tag {
  margin-left: 6px;
  padding: 1px 6px;
  border-radius: var(--radius-pill);
  font-size: 0.8em;
  font-weight: 500;
  background: color-mix(in srgb, currentColor 12%, transparent);
  white-space: nowrap;
}
.rc-copy__unique-badge {
  margin-left: 6px;
  padding: 1px 7px;
  border-radius: var(--radius-pill);
  font-size: 0.8em;
  font-weight: 600;
  color: var(--warn);
  border: 1px solid color-mix(in srgb, var(--warn) 45%, transparent);
  white-space: nowrap;
}
.rc-versions {
  margin: 8px 0 4px;
  padding: 8px 10px 4px;
  border-top: 1px dashed color-mix(in srgb, currentColor 16%, transparent);
}
.rc-versions__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.94em;
}
.rc-versions__table th,
.rc-versions__table td {
  padding: 4px 8px;
  border-bottom: 1px solid color-mix(in srgb, currentColor 8%, transparent);
  text-align: left;
  vertical-align: baseline;
}
.rc-versions__table th { font-weight: 600; opacity: 0.72; }
.rc-num { text-align: right; font-variant-numeric: tabular-nums; }
.rc-cell-ellipsis {
  max-width: 280px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.rc-cell-nowrap { white-space: nowrap; }
.rc-versions__actions {
  display: flex;
  gap: 8px;
  margin-top: 8px;
  flex-wrap: wrap;
}
.rc-versions__health { margin-top: 6px; }
.rc-versions__issues { margin: 0; padding-left: 18px; }
/* 任务 1064：删除入口——危险动作用 danger 色区分于普通次级按钮，但按钮本体
   仍是常规尺寸（面板里的行内操作，不做大红块）。副本行的操作格里复选框与
   按钮并排，右对齐贴住列尾。 */
.rc-delete {
  color: var(--danger, #e5484d);
  border-color: color-mix(in srgb, var(--danger, #e5484d) 45%, transparent);
}
.rc-action { gap: 8px; }
.rc-result {
  margin-bottom: 10px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, currentColor 8%, transparent);
}

/* The panel's own backdrop sits below the shared confirm dialog, so the merge
   preview is never buried under the table it was opened from. */
.rc-backdrop { z-index: var(--z-local-backdrop); }

.rc-preview-table {
  width: 100%;
  margin: 10px 0;
  border-collapse: collapse;
  font-size: 0.94em;
}
.rc-preview-table th,
.rc-preview-table td {
  padding: 5px 8px;
  text-align: left;
  border-bottom: 1px solid color-mix(in srgb, currentColor 12%, transparent);
}
.rc-preview-table th { font-weight: 600; opacity: 0.72; }
.rc-preview-table td:first-child { max-width: 280px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.rc-outcomes { margin: 0; padding: 0; list-style: none; }
.rc-outcomes li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; padding: 3px 0; }
.rc-outcome__label { font-weight: 600; }
.rc-outcome--ok { color: var(--ok, inherit); }
.rc-outcome--blocked { opacity: 0.75; }
.rc-outcome--failed { color: var(--danger, inherit); }

/* The row a merge would leave as the canonical transcript. Named in advance so
   "which transcript do I end up with" is answered before the merge, not after. */
.rc-row--winner {
  box-shadow: inset 3px 0 0 0 var(--accent, currentColor);
}
.rc-row--winner .rc-label { font-weight: 700; }
.rc-result__hint { margin: 8px 0 0; opacity: 0.85; }

/* Candidate chains an expanded conversation could be merged to. Each row is one
   head's chain back to the root, so their lengths are directly comparable - which
   is what makes "the merge keeps the longest" checkable rather than a claim. */
.rc-chains { margin: 8px 0 4px; padding: 8px 10px 4px; border-top: 1px dashed color-mix(in srgb, currentColor 16%, transparent); }
.rc-chains__head { margin-bottom: 6px; font-size: 0.9em; font-weight: 600; opacity: 0.72; }
/* 任务 1065：链表头部的合成入口与提示——合成是整表级一键操作（选 HEAD → 反
   向合成最长链），所以按钮与状态提示挂在链表头部而不是单行里；行内只保留
   1.34 的预览/选中语义。 */
.rc-chains__actions {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}
.rc-chains__synth-hint { font-size: 0.86em; opacity: 0.7; }
.rc-chain {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 14px;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.94em;
}
.rc-chain--recommended {
  background: color-mix(in srgb, currentColor 8%, transparent);
  box-shadow: inset 3px 0 0 0 var(--accent, currentColor);
}
.rc-chain__name { min-width: 90px; font-weight: 600; }
.rc-chain__badge {
  padding: 1px 7px;
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, currentColor 16%, transparent);
  font-size: 0.86em;
}

/* The colour-filter button keeps its icon and shows the active colours as dots.
   The filter is keyed by storage identifiers, and rendering one of those turned the
   icon into an English word; dots also scale to a multi-select set that no single
   label could name. */
.project-tree__color-filter-dots {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  margin-left: 3px;
}
.project-tree__color-filter-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

/* tl1157: the classic header folds time + colour filtering into one dropdown
   panel. The trigger lights one neutral dot while any filter is active (the
   summary lives in the tooltip); the panel widens past the old 84px time
   menu, and its footer "clear filters" is a distinct quiet action row. */
.project-tree__filter-badge {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-left: 3px;
  border-radius: 50%;
  background: var(--accent);
}

.project-tree__filter-panel {
  min-width: 168px;
  max-height: min(420px, 70vh);
  overflow-y: auto;
}

.project-tree__filter-clear {
  justify-content: center;
  color: var(--fg-faint);
}

.project-tree__filter-clear:disabled {
  opacity: 0.45;
  cursor: default;
}

.project-tree__filter-clear:not(:disabled):hover {
  background: var(--sidebar-hover);
  color: var(--fg);
}

/* tl1170: collapsible time/colour section headers inside the filter panel.
   Default collapsed (chevron points right); the section title row is itself
   the toggle. Theme tokens only, mirrors the quiet title row styling. */
.project-tree__filter-section-toggle {
  --wails-draggable: no-drag;
  display: flex;
  align-items: center;
  gap: 5px;
  width: 100%;
  margin: 2px 0 0;
  padding: 3px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-faint);
  font-size: 10px;
  white-space: nowrap;
  user-select: none;
  text-align: left;
  cursor: pointer;
  transition: background 0.12s, color 0.12s;
}

.project-tree__filter-section-toggle:hover {
  background: var(--sidebar-hover);
  color: var(--fg);
}

.project-tree__filter-section-toggle svg {
  flex: none;
}

/* Each candidate chain's own preview text - the last thing that branch said. Numbers
   tell you which chain is longest; the preview tells you which one you want. */
.rc-chain__preview {
  flex: 1 1 240px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  opacity: 0.72;
  font-size: 0.94em;
}

/* A chain the user has picked to win. Clickable rows need affordance, and the
   pick must survive alongside the recommendation badge without reading as one. */
.rc-chain--picked {
  outline: 1px solid var(--accent, #4c8dff);
  background: color-mix(in srgb, var(--accent, #4c8dff) 12%, transparent);
  cursor: pointer;
}
.rc-chain:not(.rc-chain--picked) {
  cursor: pointer;
}

/* Wide confirm dialog - chain previews and other content-heavy asks. Both the
   width and the max-width are set because the generic .modal max-width wins
   over width alone. */
.reasonix-confirm-dialog--wide {
  width: min(1100px, 94vw);
  max-width: min(1100px, 94vw);
}
.reasonix-confirm-dialog--wide .reasonix-confirm-dialog__message {
  max-height: 82vh;
  overflow-y: auto;
}
/* Chain preview content inside the wide dialog. */
.rc-preview {
  display: flex;
  flex-direction: column;
  gap: 8px;
  text-align: left;
}
.rc-preview__stats {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  font-size: 0.95em;
  opacity: 0.85;
}
.rc-preview__section {
  border: 1px solid var(--border, rgba(255, 255, 255, 0.12));
  border-radius: var(--radius-md);
  padding: 8px 10px;
  background: rgba(127, 127, 127, 0.06);
}
.rc-preview__label {
  font-size: 0.86em;
  opacity: 0.7;
  margin-bottom: 4px;
}
.rc-preview__tail-count {
  font-size: 0.86em;
  opacity: 0.7;
  margin-left: 8px;
}
.rc-preview__line {
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 0.94em;
}
.rc-preview__warn {
  color: var(--warning, #d9a441);
  font-size: 0.92em;
}

/* Explicit per-row preview action: the row itself stays read-only, the button
   carries the preview-and-pick flow, and a picked row wears a badge so the
   state survives scrolling without depending on row highlight alone. */
.rc-chain__preview-btn {
  flex: 0 0 auto;
}
.rc-chain__picked-badge {
  flex: 0 0 auto;
  font-size: 0.86em;
  color: var(--accent, #4c8dff);
}

/* The tail is the part a user judges a branch by - it leads the dialog and its
   lines render longer than the opening's single-line summary. */
.rc-preview__section--tail .rc-preview__line {
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 1em;
  margin: 2px 0;
}

/* Conversation-style preview feed: full messages, role-tagged, scrollable. The
   dialog already scrolls as a whole; the feed is simply the long body. */
.rc-preview__feed {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.rc-preview__feed-empty {
  opacity: 0.6;
  font-size: 0.92em;
  padding: 8px 0;
}
.rc-preview__msg {
  border: 1px solid var(--border, rgba(255, 255, 255, 0.12));
  border-radius: var(--radius-md);
  padding: 8px 12px;
  background: rgba(127, 127, 127, 0.05);
}
.rc-preview__msg--user {
  border-color: color-mix(in srgb, var(--accent, #4c8dff) 45%, transparent);
  background: color-mix(in srgb, var(--accent, #4c8dff) 8%, transparent);
}
.rc-preview__msg-role {
  display: inline-block;
  font-size: 0.8em;
  opacity: 0.65;
  margin-bottom: 4px;
}
.rc-preview__msg-text {
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 0.95em;
  line-height: 1.5;
}

/* The expandable middle of a long branch feed: same semantics as the session
   window's load-older, one click widens both windows. */
.rc-preview__feed-gap {
  align-self: center;
  border: 1px dashed var(--border, rgba(255, 255, 255, 0.18));
  border-radius: var(--radius-md);
  background: transparent;
  color: inherit;
  font-size: 0.9em;
  padding: 6px 14px;
  cursor: pointer;
}

/* ── Session monitor board (task 123, experimental) ───────────────────────────
   A floating diagnostics panel anchored to the project-tree header. It only
   mounts while the experiment switch is on and the user opened it. */
.session-monitor {
  position: fixed;
  /* Above Settings ManagementSurface (z-modal). Opens over the experimental pane. */
  z-index: var(--z-popover);
  /* Anchored just above the trash row it is opened from. */
  bottom: 56px;
  left: 12px;
  width: min(560px, calc(100vw - 24px));
  max-height: min(70vh, 640px);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.32);
  font-size: var(--text-sm);
  line-height: 1.45;
}
.session-monitor__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.session-monitor__title {
  font-weight: 600;
}
.session-monitor__global {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  color: var(--fg-faint);
}
.session-monitor__rows {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.session-monitor__row {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
}
.session-monitor__row--active {
  border-color: var(--accent);
}
.session-monitor__row-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.session-monitor__tab {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.session-monitor__path,
.session-monitor__log-row {
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.session-monitor__metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
}
.session-monitor__miss {
  color: var(--warn);
}
.session-monitor__evicted {
  color: var(--danger);
}
.session-monitor__empty {
  color: var(--fg-faint);
}
.session-monitor__stages {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 10px;
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.session-monitor__stage {
  font-variant-numeric: tabular-nums;
}
.session-monitor__render-metrics {
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.feedback-panel {
  position: fixed;
  left: 12px;
  bottom: 56px;
  /* Above Settings ManagementSurface (z-modal). Opens over the experimental pane. */
  z-index: var(--z-popover);
  width: min(420px, calc(100vw - 24px));
  max-height: min(480px, calc(100vh - 120px));
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-elevated, var(--bg));
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.28);
  overflow: auto;
}
.feedback-panel__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.feedback-panel__title {
  font-weight: 600;
  font-size: var(--text-md);
}
.feedback-panel__actions {
  display: flex;
  gap: 6px;
}
.feedback-panel__empty {
  color: var(--fg-faint);
  font-size: var(--text-sm);
  padding: 8px 0;
}
.feedback-panel__rows {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.feedback-panel__row {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
}
.feedback-panel__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  font-size: var(--text-xs);
  color: var(--fg-faint);
}
.feedback-panel__kind {
  font-weight: 600;
  color: var(--accent);
}
.feedback-panel__tag {
  padding: 0 6px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border);
  font-size: 10px;
}
.feedback-panel__text {
  font-size: var(--text-sm);
  white-space: pre-wrap;
  word-break: break-word;
}

/* 跨会话收件箱面板 (task 320): fixed overlay beside the feedback inbox,
   five-bucket tabs + filters + revision footer. Theme tokens only — no raw
   colors — so graphite/aurora/... themes all render it correctly. */
.collab-inbox-panel {
  position: fixed;
  left: 12px;
  bottom: 56px;
  z-index: var(--z-popover);
  width: min(620px, calc(100vw - 24px));
  max-height: min(640px, calc(100vh - 120px));
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-elevated, var(--bg));
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.28);
  overflow: auto;
}
.collab-inbox-panel__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
/* 任务716 ①：标题横排——nowrap+不收缩，窄容器下不再被压缩成一字一行
   （原布局六控件同行的挤压是竖排截断根因，716 分组后头部仅剩标题+关闭）。 */
.collab-inbox-panel__title {
  font-weight: var(--font-weight-strong);
  font-size: 15px;
  white-space: nowrap;
  flex-shrink: 0;
}
/* 任务716 ②：维护行（定稿第二位，暖色警示底）——危险操作分组（保留期/
   清理条件/立即清理）视觉降权但可达；warn token 调色跟随明暗主题。横向
   出血到面板两缘，还原 v3 设计稿的整幅色带分段。 */
.collab-inbox-panel__maint {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0 -12px;
  padding: 6px 12px;
  border-top: 1px solid color-mix(in srgb, var(--warn) 26%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--warn) 26%, transparent);
  background: color-mix(in srgb, var(--warn) 10%, var(--bg-elevated, var(--bg)));
}
.collab-inbox-panel__maintlabel {
  font-size: var(--text-xs);
  font-weight: var(--font-weight-strong);
  color: color-mix(in srgb, var(--warn) 78%, var(--fg));
}
/* 「标签词+下拉」通用形态（保留期/清理条件共用；中性弱化色供维护行外
   复用，维护行内由上方 warn 覆盖规则接管）。 */
.collab-inbox-panel__retention {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--text-xs);
  color: var(--fg-faint);
}
/* 维护行内的标签词随行底转 warn 调（覆盖 .collab-inbox-panel__retention 的
   中性弱化色，类名保留以钉住「label+select」结构与既有测试选择器）。 */
.collab-inbox-panel__maint .collab-inbox-panel__retention {
  color: color-mix(in srgb, var(--warn) 74%, var(--fg));
}
/* 立即清理按钮：维护行内用 warn 描边（v3 设计稿 warn-btn 语言）。 */
.collab-inbox-panel__cleannow {
  border-color: color-mix(in srgb, var(--warn) 45%, var(--border));
  color: color-mix(in srgb, var(--warn) 80%, var(--fg));
}
/* 任务620：立即清理的一次性反馈（已清理 N 封 / 没有可清理的信件），
   弱化前景、随维护行内联，数秒后由组件侧定时移除。 */
.collab-inbox-panel__cleannote {
  font-size: var(--text-xs);
  color: var(--fg-dim);
  white-space: nowrap;
}
.collab-inbox-panel__buckets,
.collab-inbox-panel__states {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.collab-inbox-panel__bucket,
.collab-inbox-panel__state {
  padding: 3px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: var(--bg);
  color: var(--fg-dim);
  font-size: var(--text-xs);
  cursor: pointer;
}
.collab-inbox-panel__bucket--on,
.collab-inbox-panel__state--on {
  border-color: var(--accent);
  color: var(--accent);
}
.collab-inbox-panel__filters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.collab-inbox-panel__filter {
  flex: 1 1 140px;
  min-width: 0;
  padding: 4px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--fg);
  font-size: var(--text-sm);
  transition: border-color 0.12s, background 0.12s;
}
/* 任务620：发信方/收信方下拉的 hover 反馈——悬停时边框与底色用按钮 hover
   token 亮起（与 .chip:hover 同构），让「我正指着哪个选择器」可感知。 */
.collab-inbox-panel__filter:hover {
  border-color: var(--button-border-hover);
  background: var(--button-bg-hover);
}
/* 任务 649 ②：from/to 下拉的可见标签词（「发信方/收信方」）——此前只有
   aria 文案，肉眼分不清左右两个下拉谁是发信方。布局沿用保留期标签的形态。 */
.collab-inbox-panel__filterwrap {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1 1 170px;
  min-width: 0;
  font-size: var(--text-xs);
  color: var(--fg-faint);
}
/* 任务716 ③：视图工具条（定稿第三位，灰底弱分区）——视图/排序分段 +
   全部已读；横向出血与维护行同款整幅色带，底色用 bg-soft（比面板底
   沉一档的中性灰，跟随明暗主题）。 */
.collab-inbox-panel__toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin: 0 -12px;
  padding: 4px 12px;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  background: var(--bg-soft);
}
.collab-inbox-panel__tlabel {
  font-size: var(--text-xs);
  font-weight: var(--font-weight-strong);
  color: var(--fg-faint);
}
.collab-inbox-panel__sep {
  width: 1px;
  height: 16px;
  background: var(--border);
}
/* 任务 649 ①+任务716 ③：排序/视图分段控件落位视图工具条（716 定稿第三
   位；649 时曾在头行 actions），样式保持胶囊分段——参照设置-权限档位
   .set-seg 的分段语言（容器描边 + 按钮拼合 + 激活 accent-soft 反白）。 */
.collab-inbox-panel__ordertoggle,
.collab-inbox-panel__viewtoggle {
  display: inline-flex;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  overflow: hidden;
  background: var(--bg);
}
.collab-inbox-panel__ordertoggle .collab-inbox-panel__state,
.collab-inbox-panel__viewtoggle .collab-inbox-panel__state {
  border: none;
  border-radius: 0;
  background: transparent;
  white-space: nowrap;
}
.collab-inbox-panel__ordertoggle .collab-inbox-panel__state + .collab-inbox-panel__state,
.collab-inbox-panel__viewtoggle .collab-inbox-panel__state + .collab-inbox-panel__state {
  border-left: 1px solid var(--border);
}
.collab-inbox-panel__ordertoggle .collab-inbox-panel__state--on,
.collab-inbox-panel__viewtoggle .collab-inbox-panel__state--on {
  background: var(--accent-soft);
  color: var(--accent);
  font-weight: var(--font-weight-strong);
}
.collab-inbox-panel__showdismissed {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: var(--text-xs);
  color: var(--fg-faint);
}
.collab-inbox-panel__rows {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.collab-inbox-panel__empty {
  color: var(--fg-faint);
  font-size: var(--text-sm);
  padding: 8px 0;
}
/* 任务587 失败态与空态分离：读取失败显式报错（绝不渲染成「暂无信件」）。
   __error = 无数据时的失败块（错误原文 + 重试）；__errorstrip = 有旧数据时的
   顶部细条（旧数据优先渲染，如实声明不是最新结果）。 */
.collab-inbox-panel__error {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  padding: 10px;
  border: 1px solid var(--danger);
  border-radius: var(--radius-md);
  background: var(--bg);
}
.collab-inbox-panel__error-label {
  color: var(--danger);
  font-size: var(--text-sm);
  font-weight: 600;
}
.collab-inbox-panel__error-detail {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.collab-inbox-panel__errorstrip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 8px;
  border: 1px solid var(--danger);
  border-radius: var(--radius-md);
  color: var(--danger);
  font-size: var(--text-xs);
}
.collab-inbox-panel__row {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
}
.collab-inbox-panel__row--dismissed {
  opacity: 0.55;
}
/* 任务 649 ③：行 hover 高亮——620 件1 只落了 from/to 下拉的 hover，行本身
   从未有过 hover 规则（装机实测「未见效果」的定位结论：实现遗漏，非选择器
   未命中）。悬停行边框与底色用按钮 hover token 亮起，与 __filter:hover 同构。 */
.collab-inbox-panel__row:hover {
  border-color: var(--button-border-hover);
  background: var(--button-bg-hover);
}
.collab-inbox-panel__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  font-size: var(--text-xs);
  color: var(--fg-faint);
}
/* 任务 649 ②：路由行「发信方/收信方」标签词 vs 会话名的两级灰——标签更弱、
   会话名略亮，扫一眼先看到名字。 */
.collab-inbox-panel__route {
  color: var(--fg-dim);
}
.collab-inbox-panel__routelabel {
  color: var(--fg-faint);
}
.collab-inbox-panel__bucketbadge {
  padding: 0 6px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border);
  font-weight: 600;
}
.collab-inbox-panel__bucketbadge--approval {
  color: var(--accent);
  border-color: var(--accent);
}
/* 任务 349n1 群标识：fan-out 来源频道的 #名 chip（列表行 + 对话链条目共用）。 */
.collab-inbox-panel__channel {
  padding: 0 6px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--accent);
  color: var(--accent);
  font-weight: 600;
  white-space: nowrap;
}
.collab-inbox-panel__read {
  padding: 0 6px;
  border-radius: var(--radius-pill);
  border: 1px dashed var(--border);
}
.collab-inbox-panel__read--on {
  border-style: solid;
  color: var(--fg-dim);
}
.collab-inbox-panel__decided {
  color: var(--accent);
  font-weight: 600;
}
.collab-inbox-panel__pending {
  color: var(--warn, var(--accent));
  font-weight: 600;
}
.collab-inbox-panel__preview {
  font-size: var(--text-sm);
  color: var(--fg);
  word-break: break-word;
}
/* 任务 980 ③：预览行可点 → 详情弹窗展示全文。按钮形态清零（原生 button 的
   边框/底色/字体全部抹掉），保留文字外观 + 可点光标 + hover 微亮提示。 */
.collab-inbox-panel__preview--btn {
  border: none;
  margin: 0;
  padding: 0;
  background: transparent;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.collab-inbox-panel__preview--btn:hover {
  color: var(--accent);
}
/* 任务 980 ③：详情弹窗——modal 家族先例（.modal-backdrop/.modal 公共骨架），
   本块只补差异：宽幅 + 纵向 flex + 正文区滚动。
   任务 984：z-index 由 --z-overlay-backdrop(1300) 提升到 --z-popover-elevated(1303)——
   详情弹窗从协作中心主面板(--z-popover 1301)内点出，1300 < 1301 会被主面板盖住。 */
.collab-inbox-detail-backdrop {
  --wails-draggable: no-drag;
  z-index: var(--z-popover-elevated);
}
.collab-inbox-detail {
  max-width: min(720px, 92vw);
  color: var(--fg);
  display: flex;
  flex-direction: column;
  max-height: min(80vh, 720px);
}
.collab-inbox-detail__title {
  margin-bottom: 8px;
}
.collab-inbox-detail__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  margin-bottom: 10px;
  font-size: var(--text-xs);
  color: var(--fg-faint);
}
/* 正文区：全文 pre-wrap 原样展示（信件正文的换行是语义），超高滚动。 */
.collab-inbox-detail__body {
  flex: 1;
  min-height: 80px;
  overflow-y: auto;
  padding: 10px 12px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: var(--bg-soft);
  font-size: var(--text-sm);
  color: var(--fg);
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
}
.collab-inbox-detail__body--loading {
  color: var(--fg-faint);
}
.collab-inbox-panel__rowactions {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
}
.collab-inbox-panel__chain {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
}
.collab-inbox-panel__chainhead {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px;
  background: none;
  border: none;
  color: var(--fg);
  font-size: var(--text-sm);
  cursor: pointer;
  text-align: left;
}
.collab-inbox-panel__chaincount {
  font-weight: 600;
  color: var(--accent);
}
.collab-inbox-panel__chainroute {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg-dim);
}
.collab-inbox-panel__chainbody {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 8px 8px;
}
.collab-inbox-panel__chainentry {
  display: flex;
  gap: 8px;
  font-size: var(--text-xs);
  color: var(--fg-dim);
}
.collab-inbox-panel__foot {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 10px;
  color: var(--fg-faint);
}
.collab-inbox-panel__time {
  color: var(--fg-faint);
}

/* 群聊式协作视图 (task 409): fixed overlay beside the collab inbox panel,
   roster tabs + per-session state/task/exchange rows + channel tail with
   per-member fan-out chips. Theme tokens only — no raw colors — 同收件箱面板
   纪律（graphite/aurora/... 主题都正确渲染）。*/
.collab-group-panel {
  position: fixed;
  left: 12px;
  bottom: 56px;
  z-index: var(--z-popover);
  width: min(620px, calc(100vw - 24px));
  max-height: min(640px, calc(100vh - 120px));
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-elevated, var(--bg));
  box-shadow: var(--shadow-2);
  overflow: auto;
}
.collab-group-panel__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.collab-group-panel__title {
  font-weight: 600;
  font-size: var(--text-md);
}
.collab-group-panel__actions {
  display: flex;
  align-items: center;
  gap: 6px;
}
.collab-group-panel__tabs {
  display: flex;
  gap: 6px;
}
.collab-group-panel__tab {
  padding: 3px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: var(--bg);
  color: var(--fg-dim);
  font-size: var(--text-xs);
  cursor: pointer;
}
.collab-group-panel__tab--on {
  border-color: var(--accent);
  color: var(--accent);
}
.collab-group-panel__rows {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.collab-group-panel__empty {
  padding: 18px 8px;
  text-align: center;
  font-size: var(--text-sm);
  color: var(--fg-faint);
}
.collab-group-panel__error {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--warn, #c80) 55%, var(--border));
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--warn, #c80) 8%, var(--bg));
}
.collab-group-panel__error-label {
  font-size: var(--text-sm);
  font-weight: 600;
}
.collab-group-panel__error-detail {
  font-size: var(--text-xs);
  color: var(--fg-dim);
  word-break: break-all;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.collab-group-panel__errorstrip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 8px;
  border: 1px solid color-mix(in srgb, var(--warn, #c80) 45%, var(--border));
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--warn, #c80) 7%, var(--bg));
  font-size: var(--text-xs);
  color: var(--fg-dim);
}
.collab-group-panel__session {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 7px 9px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: var(--bg);
}
.collab-group-panel__meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
}
.collab-group-panel__state {
  padding: 1px 8px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border);
  font-size: 10px;
  color: var(--fg-dim);
  white-space: nowrap;
}
.collab-group-panel__state--running {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
  color: var(--accent);
}
.collab-group-panel__state--queued {
  border-color: color-mix(in srgb, var(--warn, #c80) 55%, var(--border));
  color: var(--warn, #c80);
}
.collab-group-panel__name {
  font-size: var(--text-sm);
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.collab-group-panel__idtype {
  padding: 1px 6px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border-soft);
  font-size: 10px;
  color: var(--fg-faint);
  white-space: nowrap;
}
.collab-group-panel__unread {
  padding: 1px 6px;
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--accent) 16%, var(--bg));
  font-size: 10px;
  color: var(--accent);
  white-space: nowrap;
}
.collab-group-panel__purpose {
  font-size: var(--text-xs);
  color: var(--fg-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.collab-group-panel__card {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: var(--text-xs);
}
.collab-group-panel__cardstatus {
  padding: 1px 6px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border);
  font-size: 10px;
  color: var(--fg-dim);
  white-space: nowrap;
}
.collab-group-panel__cardstatus--running {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
  color: var(--accent);
}
.collab-group-panel__cardtitle {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg);
}
.collab-group-panel__preview {
  font-size: var(--text-xs);
  color: var(--fg-faint);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.collab-group-panel__channel {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.collab-group-panel__channelhead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  padding: 6px 9px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  background: var(--bg);
  color: var(--fg);
  font-size: var(--text-sm);
  cursor: pointer;
  text-align: left;
}
.collab-group-panel__channelname {
  font-weight: 600;
}
.collab-group-panel__channelcounts {
  font-size: 10px;
  color: var(--fg-faint);
  white-space: nowrap;
}
.collab-group-panel__channelbody {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 4px 2px 2px 10px;
  border-left: 2px solid var(--border-soft);
  margin-left: 8px;
}
.collab-group-panel__message {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.collab-group-panel__sender {
  font-size: var(--text-xs);
  font-weight: 600;
  color: var(--fg-dim);
}
.collab-group-panel__messagebody {
  font-size: var(--text-sm);
  white-space: pre-wrap;
  word-break: break-word;
}
.collab-group-panel__fanout {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.collab-group-panel__fanoutcell {
  padding: 1px 6px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border);
  font-size: 10px;
  color: var(--fg-faint);
  white-space: nowrap;
}
.collab-group-panel__fanoutcell--read {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  color: var(--accent);
}
.collab-group-panel__fanoutcell--failed {
  border-color: color-mix(in srgb, var(--warn, #c80) 55%, var(--border));
  color: var(--warn, #c80);
}
.collab-group-panel__foot {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 10px;
  color: var(--fg-faint);
}
.collab-group-panel__note {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.collab-group-panel__time {
  color: var(--fg-faint);
  white-space: nowrap;
}

/* 任务 802：频道消息 tab 的微信式群聊（左群列表 + 右消息流 + 输入框）。
   配色全部走既有 token（409 面板同源），气泡用 --accent 区分自己。 */
.channel-chat {
  display: flex;
  gap: 8px;
  height: min(540px, calc(100vh - 240px));
  min-height: 320px;
}
.channel-chat--loading,
.channel-chat__placeholder {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-sm);
  color: var(--fg-faint);
}
.channel-chat__list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 220px;
  flex-shrink: 0;
  overflow-y: auto;
  border-right: 1px solid var(--border);
  padding-right: 6px;
}
.channel-chat__listhead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 2px 2px 4px;
}
.channel-chat__listtitle {
  font-weight: 600;
  font-size: var(--text-sm);
}
.channel-chat__item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 8px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  text-align: left;
  cursor: pointer;
  font: inherit;
  color: inherit;
}
.channel-chat__item--on {
  border-color: var(--border);
  background: color-mix(in srgb, var(--accent) 8%, var(--bg));
}
.channel-chat__itemname {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--text-sm);
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.channel-chat__ownerbadge {
  flex-shrink: 0;
  padding: 0 4px;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  font-size: 9px;
  font-weight: 400;
  color: var(--fg-dim);
}
.channel-chat__ownerbadge--me {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
  color: var(--accent);
}
.channel-chat__unread {
  flex-shrink: 0;
  margin-left: auto;
  min-width: 16px;
  padding: 0 4px;
  border-radius: var(--radius-pill);
  background: var(--accent);
  color: var(--bg);
  font-size: 9px;
  text-align: center;
}
.channel-chat__itempreview {
  font-size: var(--text-xs);
  color: var(--fg-faint);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.channel-chat__main {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
  min-width: 0;
}
.channel-chat__time {
  color: var(--fg-dim);
  font-size: var(--text-sm);
  white-space: nowrap;
  align-self: flex-start;
}
.channel-chat__chathead {
  display: flex;
  align-items: center;
  gap: 8px;
}
.settings-input {
  width: 100%;
  max-width: 420px;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-elev);
  color: var(--fg);
}
.channel-chat__back {
  border: none;
  background: transparent;
  color: var(--fg-dim);
  font-size: 16px;
  line-height: 1;
  cursor: pointer;
  padding: 0 2px;
}
.channel-chat__chatname {
  font-weight: 600;
  font-size: var(--text-md);
}
.channel-chat__chattopic {
  font-size: var(--text-xs);
  color: var(--fg-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.channel-chat__chatmeta {
  margin-left: auto;
  font-size: var(--text-xs);
  color: var(--fg-faint);
  white-space: nowrap;
}
.channel-chat__actionerror {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border: 1px solid color-mix(in srgb, var(--warn, #c80) 55%, var(--border));
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--warn, #c80) 8%, var(--bg));
  font-size: var(--text-xs);
  color: var(--fg-dim);
  word-break: break-all;
}
.channel-chat__stream {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
  padding: 4px 2px;
}
.channel-chat__row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-width: 88%;
}
.channel-chat__row--own {
  align-self: flex-end;
  align-items: flex-end;
}
.channel-chat__rowmeta {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-size: 10px;
  color: var(--fg-faint);
}
.channel-chat__sender {
  font-weight: 600;
  color: var(--fg-dim);
}
.channel-chat__typebadge {
  padding: 0 4px;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  font-size: 9px;
  color: var(--fg-dim);
}
.channel-chat__typebadge--human {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
  color: var(--accent);
}
.channel-chat__bubble {
  padding: 6px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-elevated, var(--bg));
  font-size: var(--text-sm);
  white-space: pre-wrap;
  word-break: break-word;
}
.channel-chat__row--own .channel-chat__bubble {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  background: color-mix(in srgb, var(--accent) 12%, var(--bg-elevated, var(--bg)));
}
.channel-chat__receipts {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.channel-chat__receipt {
  font-size: 9px;
  color: var(--fg-faint);
}
.channel-chat__receipt--read {
  color: var(--accent);
}
.channel-chat__receipt--failed {
  color: var(--warn, #c80);
}
.channel-chat__tombstone {
  align-self: center;
  font-size: 10px;
  color: var(--fg-faint);
  font-style: italic;
}
.channel-chat__composer {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  border-top: 1px solid var(--border);
  padding-top: 6px;
}
.channel-chat__input {
  flex: 1;
  resize: none;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  color: inherit;
  font: inherit;
  font-size: var(--text-sm);
}
.channel-chat__send {
  flex-shrink: 0;
}
.channel-chat__detail {
  position: absolute;
  inset: 44px 12px 34px auto;
  width: min(300px, 70%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-elevated, var(--bg));
  box-shadow: var(--shadow-2);
  overflow-y: auto;
  z-index: var(--z-local-raised);
}
.channel-chat__detailhead {
  display: flex;
  align-items: baseline;
