}
/* 用户 1138：链名/预览截断处一律 ellipsis + title hover */
.collab-chat-view__dirname {
  font-size: var(--text-sm);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.collab-chat-view__dirmeta {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}
.collab-chat-view__dirpreview {
  flex: 1;
  min-width: 0;
  font-size: var(--text-xs, 11px);
  color: var(--text-muted, inherit);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.collab-chat-view__dircount {
  flex: none;
  font-size: var(--text-xs, 11px);
  color: var(--text-muted, inherit);
}
.collab-chat-view__direrror {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  font-size: var(--text-xs, 11px);
  color: var(--text-muted, inherit);
}
.collab-chat-view__dirempty,
.collab-chat-view__placeholder {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
