  color: var(--text-muted, inherit);
  font-size: var(--text-sm);
}
.collab-chat-view__placeholderhint {
  font-size: var(--text-xs, 11px);
}
.collab-chat-view__replay {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.collab-chat-view__replayhead {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
  flex: none;
  min-width: 0;
}
.collab-chat-view__replaytitle {
  font-weight: 600;
  font-size: var(--text-sm);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.collab-chat-view__replaysub {
  font-size: var(--text-xs, 11px);
  color: var(--text-muted, inherit);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.collab-chat-view__stream {
