}
.collab-chat-view__msgpeer {
  font-size: 10px;
  color: var(--text-muted, inherit);
}
.collab-chat-view__readonly {
  padding: 8px 14px;
  border-top: 1px solid var(--border);
  background: var(--bg-soft);
  font-size: var(--text-xs, 11px);
  color: var(--text-muted, inherit);
  flex: none;
}
.collab-chat-view__ctx {
  position: fixed;
  z-index: var(--z-tooltip);
  min-width: 230px;
  padding: 4px 0;
  background: var(--bg-elevated, var(--bg));
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 8px 28px color-mix(in srgb, var(--shadow-color) 18%, transparent);
  overflow: hidden;
